QT_ISI(18,{"2674":["(Sesungguhnya) lafal Qad di sini menunjukkan makna Tahqiq, artinya sungguh telah pasti (beruntunglah) berbahagialah (orang-orang yang beriman).",[["قَدْ","Sesungguhnya"],["أَفْلَحَ","berjaya"],["ٱلْمُؤْمِنُونَ","(ialah) orang-orang yang beriman"]]],"2675":["(Yaitu orang-orang yang khusyuk dalam salatnya) dengan merendahkan diri penuh perasaan kepada Allah.",[["ٱلَّذِينَ","Orang yang"],["هُمْ","[mereka]"],["فِى","semasa"],["صَلَاتِهِمْ","doa mereka"],["خَـٰشِعُونَ","(adalah) dengan rendah hati tunduk"]]],"2676":["(Dan orang-orang yang menjauhkan diri dari hal yang tiada berguna) berupa perkataan dan hal-hal lainnya.",[["وَٱلَّذِينَ","Orang yang"],["هُمْ","[mereka]"],["عَنِ","daripada"],["ٱللَّغْوِ","cakap-cakap yang sia-sia"],["مُعْرِضُونَ","berpaling"]]],"2677":["(Dan orang-orang yang terhadap zakat mereka menunaikannya) membayarnya.",[["وَٱلَّذِينَ","Orang yang"],["هُمْ","[mereka]"],["لِلزَّكَوٰةِ","daripada kerja-kerja pembersihan"],["فَـٰعِلُونَ","(adalah) pelaku"]]],"2678":["(Dan orang-orang yang terhadap kemaluannya mereka selalu memeliharanya) dari yang diharamkan.",[["وَٱلَّذِينَ","Dan orang yang"],["هُمْ","[mereka]"],["لِفُرُوجِهِمْ","kesopanan mereka"],["حَـٰفِظُونَ","(adalah) penjaga"]]],"2679":["(Kecuali terhadap istri-istri mereka) (atau terhadap budak yang mereka miliki) yakni hamba sahaya wanita yang mereka tawan dari peperangan (maka sesungguhnya mereka dalam hal ini tiada tercela) bila mereka mendatanginya.",[["إِلَّا","Kecuali"],["عَلَىٰٓ","daripada"],["أَزْوَٰجِهِمْ","pasangan mereka"],["أَوْ","atau"],["مَا","apa"],["مَلَكَتْ","memiliki"],["أَيْمَـٰنُهُمْ","tangan kanan mereka"],["فَإِنَّهُمْ","maka sesungguhnya mereka"],["غَيْرُ","(adalah) tidak"],["مَلُومِينَ","patut dipersalahkan"]]],"2680":["(Barang siapa menginginkan yang selain itu) selain istri-istri sendiri dan sahaya wanita tawanan mereka untuk pelampiasan hajat biologisnya, seumpamanya melakukan masturbasi (maka mereka itulah orang-orang yang melampaui batas) yakni melampaui batas halal dan melakukan hal-hal yang diharamkan bagi mereka.",[["فَمَنِ","Kemudian sesiapa sahaja"],["ٱبْتَغَىٰ","mencari"],["وَرَآءَ","di luar"],["ذَٰلِكَ","bahawa"],["فَأُو۟لَـٰٓئِكَ","kemudian mereka"],["هُمُ","[mereka]"],["ٱلْعَادُونَ","(ialah) orang-orang yang melampaui batas"]]],"2681":["(Dan orang-orang yang terhadap amanat yang dipercayakan kepada mereka) dapat dibaca secara jamak dan mufrad, yakni Amaanaatihim dan Amaanatihim (dan janji mereka) yang mereka adakan di antara sesama mereka atau antara mereka dengan Allah, seperti salat dan lain-lainnya (mereka memeliharanya) benar-benar menjaganya.",[["وَٱلَّذِينَ","Dan orang yang"],["هُمْ","[mereka]"],["لِأَمَـٰنَـٰتِهِمْ","daripada amanah mereka"],["وَعَهْدِهِمْ","dan janji mereka"],["رَٰعُونَ","(adalah) pemerhati"]]],"2682":["(Dan orang-orang yang terhadap salat mereka) dapat dibaca dalam bentuk jamak dan mufrad, yakni Shalawaatihim dan shalaatihim (mereka memeliharanya) mereka mengerjakannya tepat pada waktu-waktunya.",[["وَٱلَّذِينَ","Dan orang yang"],["هُمْ","[mereka]"],["عَلَىٰ","atas"],["صَلَوَٰتِهِمْ","doa mereka"],["يُحَافِظُونَ","mereka jaga"]]],"2683":["(Mereka itulah orang-orang yang akan mewarisi) bukan selain mereka.",[["أُو۟لَـٰٓئِكَ","Mereka itu"],["هُمُ","[mereka]"],["ٱلْوَٰرِثُونَ","(adalah) ahli waris"]]],"2684":["(Yakni yang akan mewarisi surga Firdaus) yaitu surga yang tempatnya paling tinggi. (Mereka kekal di dalamnya) di dalam ayat-ayat yang telah lalu terkandung isyarat yang menunjukkan tempat kembali di akhirat. Hal ini sangat relevan bila disebutkan hal-hal yang menyangkut masalah permulaan atau asal kejadian, sesudah pembahasan tadi.",[["ٱلَّذِينَ","Siapa"],["يَرِثُونَ","akan mewarisi"],["ٱلْفِرْدَوْسَ","syurga itu"],["هُمْ","mereka"],["فِيهَا","di dalamnya"],["خَـٰلِدُونَ","(akan) kekal selama-lamanya"]]],"2685":["(Dan) Allah telah berfirman, (Sesungguhnya Kami telah menciptakan manusia) yakni Adam (dari suatu sari pati) lafal Sulaalatin berasal dari perkataan Salaltusy Syai-a Minasy Syai-i, artinya aku telah memeras sesuatu daripadanya, yang dimaksud adalah inti sari dari sesuatu itu (berasal dari tanah) lafal Min Thiinin berta'alluq kepada lafal Sulaalatin.",[["وَلَقَدْ","Dan sesungguhnya"],["خَلَقْنَا","Kami mencipta"],["ٱلْإِنسَـٰنَ","umat manusia"],["مِن","daripada"],["سُلَـٰلَةٍۢ","satu intipati"],["مِّن","daripada"],["طِينٍۢ","tanah liat"]]],"2686":["(Kemudian Kami jadikan ia) manusia atau keturunan Adam (dari nuthfah) yakni air mani (yang berada dalam tempat yang kokoh) yaitu rahim.",[["ثُمَّ","Kemudian"],["جَعَلْنَـٰهُ","Kami letak dia"],["نُطْفَةًۭ","(sebagai) titisan air mani"],["فِى","dalam"],["قَرَارٍۢ","tempat berehat"],["مَّكِينٍۢ","tegas"]]],"2687":["(Kemudian air mani itu Kami jadikan segumpal darah) darah kental (lalu segumpal darah itu Kami jadikan segumpal daging) daging yang besarnya sekepal tangan (dan segumpal daging itu Kami jadikan tulang-belulang, lalu tulang-belulang itu Kami bungkus dengan daging) menurut qiraat yang lain lafal 'Izhaaman dalam dua tempat tadi dibaca 'Azhman, yakni dalam bentuk tunggal. Dan lafal Khalaqnaa yang artinya menciptakan, pada tiga tempat tadi bermakna Shayyarnaa, artinya Kami jadikan (kemudian Kami jadikan dia sebagai makhluk yang lain) yaitu dengan ditiupkan roh ke dalam tubuhnya. (Maka Maha Sucilah Allah, Pencipta Yang Paling Baik) sebaik-baik Yang Menciptakan. Sedangkan Mumayyiz dari lafal Ahsan tidak disebutkan, karena sudah dapat diketahui dengan sendirinya, yaitu lafal Khalqan.",[["ثُمَّ","Kemudian"],["خَلَقْنَا","Kami mencipta"],["ٱلنُّطْفَةَ","titisan air mani"],["عَلَقَةًۭ","(menjadi) bahan yang berpaut"],["فَخَلَقْنَا","kemudian Kami ciptakan"],["ٱلْعَلَقَةَ","bahan yang melekat"],["مُضْغَةًۭ","(menjadi) ketulan embrio"],["فَخَلَقْنَا","kemudian Kami ciptakan"],["ٱلْمُضْغَةَ","ketulan embrio"],["عِظَـٰمًۭا","(ke dalam) tulang"],["فَكَسَوْنَا","kemudian Kami beri pakaian"],["ٱلْعِظَـٰمَ","tulang"],["لَحْمًۭا","(dengan) daging"],["ثُمَّ","kemudian"],["أَنشَأْنَـٰهُ","Kami menghasilkannya"],["خَلْقًا","(sebagai) ciptaan"],["ءَاخَرَ ۚ","yang lain"],["فَتَبَارَكَ","Sungguh diberkati"],["ٱللَّهُ","Allah"],["أَحْسَنُ","(yang) Terbaik"],["ٱلْخَـٰلِقِينَ","(dari) Pencipta"]]],"2688":["(Kemudian, sesudah itu sesungguhnya kamu sekalian benar-benar akan mati).",[["ثُمَّ","Kemudian"],["إِنَّكُم","sesungguhnya, kamu"],["بَعْدَ","selepas"],["ذَٰلِكَ","bahawa"],["لَمَيِّتُونَ","nescaya (akan) mati"]]],"2689":["(Kemudian, sesungguhnya kamu sekalian akan dibangkitkan di hari kiamat) untuk menjalani hisab dan pembalasan.",[["ثُمَّ","Kemudian"],["إِنَّكُمْ","sesungguhnya, kamu"],["يَوْمَ","(pada) hari"],["ٱلْقِيَـٰمَةِ","Kiamat"],["تُبْعَثُونَ","akan dibangkitkan"]]],"2690":["(Dan sesungguhnya Kami telah menciptakan di atas kalian tujuh buah jalan) yakni tujuh langit; lafal Tharaaiq ini adalah bentuk jamak dari lafal Thariiqah, dikatakan demikian karena ia adalah jalan-jalan bagi para Malaikat (dan tidaklah Kami terhadap makhluk) yang berada di bawah tujuh langit itu (melupakannya) dengan membiarkan langit itu runtuh menimpa mereka, sehingga mereka binasa semuanya, akan tetapi Kami menahannya supaya jangan runtuh; sebagaimana yang telah disebutkan dalam firman-Nya yang lain, yaitu, \"Dan Dia menahan (benda-benda) langit jatuh ke bumi.\" (Q.S. Al-Hajj, 65).",[["وَلَقَدْ","Dan sesungguhnya"],["خَلَقْنَا","Kami (telah) mencipta"],["فَوْقَكُمْ","di atas kamu"],["سَبْعَ","tujuh"],["طَرَآئِقَ","laluan"],["وَمَا","dan bukan"],["كُنَّا","Kami"],["عَنِ","daripada"],["ٱلْخَلْقِ","penciptaan"],["غَـٰفِلِينَ","tak sedar"]]],"2691":["(Dan Kami turunkan air dari langit menurut suatu ukuran) berdasarkan kecukupan mereka (lalu Kami jadikan air itu menetap di bumi, dan sesungguhnya Kami benar-benar berkuasa menghilangkannya) jika demikian mereka pasti akan mati bersama dengan hewan ternak mereka karena kehausan.",[["وَأَنزَلْنَا","Dan Kami turunkan"],["مِنَ","daripada"],["ٱلسَّمَآءِ","langit"],["مَآءًۢ","air"],["بِقَدَرٍۢ","dalam (sewajarnya) ukuran"],["فَأَسْكَنَّـٰهُ","kemudian Kami jadikan ia menetap"],["فِى","dalam"],["ٱلْأَرْضِ ۖ","bumi"],["وَإِنَّا","Dan sesungguhnya, Kami"],["عَلَىٰ","pada"],["ذَهَابٍۭ","mengambilnya"],["بِهِۦ","mengambilnya"],["لَقَـٰدِرُونَ","nescaya (ada) Sanggup"]]],"2692":["(Lalu dengan air itu, Kami tumbuhkan untuk kalian kebun-kebun kurma dan anggur) kedua jenis buah-buahan ini kebanyakan terdapat di negeri Arab (di dalam kebun-kebun itu kalian peroleh buah-buahan yang banyak dan sebagian dari buah-buahan itu kalian makan) di waktu musim panas dan musim dingin.",[["فَأَنشَأْنَا","Kemudian Kami hasilkan"],["لَكُم","bagi kamu"],["بِهِۦ","olehnya"],["جَنَّـٰتٍۢ","taman-taman"],["مِّن","pokok kurma"],["نَّخِيلٍۢ","pokok kurma"],["وَأَعْنَـٰبٍۢ","dan anggur"],["لَّكُمْ","bagi kamu"],["فِيهَا","di dalamnya"],["فَوَٰكِهُ","(adalah) buah-buahan"],["كَثِيرَةٌۭ","melimpah ruah"],["وَمِنْهَا","dan daripada mereka"],["تَأْكُلُونَ","kamu makan"]]],"2693":["(Dan) Kami tumbuhkan pula (pohon kayu yang asal tumbuhnya dari Thursina) dapat dibaca Sina dan Saina dengan tidak menerima Tanwin karena menjadi 'Alamiyah, artinya nama sebuah bukit. Jika tidak menerima tanwin karena Illat Ta'nits, maka berarti nama suatu lembah (yang menghasilkan) dapat dibaca Tunbitu dan Tanbutu (minyak) bila menurut bacaan Tunbitu maka huruf Ba dianggap huruf Zaidah, bila menurut bacaan yang kedua yaitu Tanbutu maka huruf Ba dianggap sebagai huruf Ta'diyah yang menggandengkan Fi'il dengan Maf'ul; pohon yang dimaksud adalah pohon Zaitun (dan sebagai penyedap bagi orang-orang yang makan) lafal ini di'athafkan kepada lafal Bid Duhni, sehingga dibaca Wa Shibghin Lil Aakiliina. Artinya, sebagai penyedap suapan yang dicelupkan kepadanya kemudian dimakan, yang dimaksud adalah minyak Zaitun tersebut.",[["وَشَجَرَةًۭ","Dan pokok"],["تَخْرُجُ","(yang) muncul"],["مِن","daripada"],["طُورِ","Gunung Sinai"],["سَيْنَآءَ","Gunung Sinai"],["تَنۢبُتُ","(yang) menghasilkan"],["بِٱلدُّهْنِ","minyak"],["وَصِبْغٍۢ","dan keseronokan"],["لِّلْـَٔاكِلِينَ","bagi yang makan"]]],"2694":["(Dan sesungguhnya pada binatang-binatang ternak bagi kalian) yakni unta, sapi dan kambing (benar-benar terdapat pelajaran yang penting) bahan pelajaran yang kalian dapat mengambil manfaat besar daripadanya (Kami memberi minum kalian) dapat dibaca Nasqiikum dan Nusqiikum (dari apa yang ada di dalam perutnya) yakni air susu (dan juga pada hewan ternak itu terdapat faedah yang banyak bagi kalian) dari bulu domba, unta dan kambing serta manfaat-manfaat yang lainnya (dan sebagian daripadanya kalian makan).",[["وَإِنَّ","Dan sesungguhnya"],["لَكُمْ","bagi kamu"],["فِى","dalam"],["ٱلْأَنْعَـٰمِ","lembu itu"],["لَعِبْرَةًۭ ۖ","sesungguhnya, (adalah) pengajaran"],["نُّسْقِيكُم","Kami memberi kamu minum"],["مِّمَّا","daripada apa"],["فِى","(berada) dalam"],["بُطُونِهَا","perut mereka"],["وَلَكُمْ","dan untuk kamu"],["فِيهَا","dalam diri mereka"],["مَنَـٰفِعُ","(adalah) faedah"],["كَثِيرَةٌۭ","ramai"],["وَمِنْهَا","dan daripada mereka"],["تَأْكُلُونَ","kamu makan"]]],"2695":["(Dan di atas punggung-punggung ternak itu) khususnya unta (dan juga di atas bahtera) yaitu perahu-perahu dan kapal-kapal (kalian diangkut).",[["وَعَلَيْهَا","Dan pada mereka"],["وَعَلَى","dan seterusnya"],["ٱلْفُلْكِ","[the] kapal"],["تُحْمَلُونَ","kamu dibawa"]]],"2696":["(Dan sesungguhnya Kami telah mengutus Nuh kepada kaumnya, lalu ia berkata, \"Hai kaumku! Sembahlah oleh kamu sekalian Allah) taatilah dan esakanlah Allah (karena sekali-kali tidak ada Tuhan bagi kalian selain Dia) lafal Ghairuhu merupakan Isim dari Maa, sedangkan lafal sebelumnya menjadi Khabar dari Maa dan huruf Min adalah huruf Zaidah. (Maka mengapa kalian tidak bertakwa kepada-Nya?\") tidak takut kepada azab-Nya, mengapa kalian menyembah selain-Nya?",[["وَلَقَدْ","Dan sesungguhnya"],["أَرْسَلْنَا","Kami utus"],["نُوحًا","Nuh"],["إِلَىٰ","kepada"],["قَوْمِهِۦ","umatnya"],["فَقَالَ","dan dia berkata"],["يَـٰقَوْمِ","Wahai kaumku"],["ٱعْبُدُوا۟","Ibadah"],["ٱللَّهَ","Allah"],["مَا","tidak"],["لَكُم","bagi kamu"],["مِّنْ","(adalah) mana-mana"],["إِلَـٰهٍ","tuhan"],["غَيْرُهُۥٓ ۖ","selain Dia"],["أَفَلَا","Kemudian tidak akan"],["تَتَّقُونَ","kamu takut"]]],"2697":["(Maka pemuka-pemuka orang yang kafir di antara kaumnya berkata) kepada para pengikut mereka, (\"Orang ini tidak lain hanyalah manusia seperti kalian, yang bermaksud hendak menjadi seorang yang lebih tinggi) lebih mulia dan berpengaruh (dari kalian) maksudnya ia ingin menjadi orang yang banyak pengikutnya, dan para pengikutnya adalah kalian sendiri. (Dan kalau Allah menghendaki) supaya tidak disembah selain daripada-Nya (tentu Dia mengutus beberapa Malaikat) untuk menyampaikan hal tersebut, tidak mengutus manusia. (Belum pernah kami mendengar seruan yang seperti ini) yang diserukan oleh Nabi Nuh, maksudnya ajaran tauhid (pada masa nenek moyang kami yang dahulu) yakni umat-umat terdahulu.",[["فَقَالَ","Tetapi berkata"],["ٱلْمَلَؤُا۟","ketua-ketua"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["مِن","antara"],["قَوْمِهِۦ","umatnya"],["مَا","Ini bukan"],["هَـٰذَآ","Ini bukan"],["إِلَّا","tetapi"],["بَشَرٌۭ","seorang lelaki"],["مِّثْلُكُمْ","macam kamu"],["يُرِيدُ","dia mahu"],["أَن","kepada"],["يَتَفَضَّلَ","menegaskan kelebihan (nya)."],["عَلَيْكُمْ","atas kamu"],["وَلَوْ","dan jika"],["شَآءَ","Allah telah menghendaki"],["ٱللَّهُ","Allah telah menghendaki"],["لَأَنزَلَ","nescaya Dia (akan) menurunkan"],["مَلَـٰٓئِكَةًۭ","malaikat"],["مَّا","Tidak"],["سَمِعْنَا","kami dengar"],["بِهَـٰذَا","ini"],["فِىٓ","daripada"],["ءَابَآئِنَا","nenek moyang kita"],["ٱلْأَوَّلِينَ","nenek moyang kita"]]],"2698":["(Ia tiada lain) maksudnya Nuh ini tidak lain (hanyalah seorang laki-laki yang berpenyakit gila) dalam keadaan gila (maka tunggulah terhadapnya) tunggulah dia, atau biarkanlah dia (sampai suatu waktu\") hingga saat kematiannya. Maksud mereka biarkanlah dia begitu, nanti juga mati sendiri.",[["إِنْ","Tidak"],["هُوَ","dia"],["إِلَّا","(adalah) tetapi"],["رَجُلٌۢ","seorang lelaki"],["بِهِۦ","dalam dirinya"],["جِنَّةٌۭ","(adalah) kegilaan"],["فَتَرَبَّصُوا۟","jadi tunggu"],["بِهِۦ","berkenaan dia"],["حَتَّىٰ","sehingga"],["حِينٍۢ","suatu masa"]]],"2699":["(Berdoalah) Nabi Nuh, (\"Ya Rabbku! Tolonglah aku) atas mereka (karena mereka mendustakan aku\") yakni mereka tidak mau percaya lagi kepadaku, maka binasakanlah mereka. Maka Allah berfirman memperkenankan doanya:",[["قَالَ","Dia berkata"],["رَبِّ","Tuhanku"],["ٱنصُرْنِى","Tolong aku"],["بِمَا","kerana"],["كَذَّبُونِ","mereka menafikan aku"]]],"2700":["(Lalu Kami wahyukan kepadanya, \"Buatlah bahtera) yakni perahu (di bawah pengawasan Kami) maksudnya di bawah penilikan dan pengawasan Kami (dan wahyu Kami) yaitu perintah Kami (maka apabila perintah Kami datang) yakni perintah untuk membinasakan mereka (dan tanur telah memancarkan air) dapur pembuat roti telah memancarkan air, sebagai pertanda bagi Nabi Nuh (maka masukkanlah ke dalam bahtera itu) naikkanlah ke dalamnya (dari tiap-tiap jenis) hewan (sepasang) jantan dan betina. Lafal Itsnaini adalah Maf'ul, sedangkan huruf Min berta'alluq kepada lafal Usluk. Menurut suatu kisah disebutkan, bahwa Allah swt. mengumpulkan bagi Nabi Nuh segala macam jenis binatang liar dan burung-burung, serta hewan-hewan lainnya. Kemudian Nabi Nuh memukulkan tangannya kepada tiap-tiap jenis, tangan kanannya mengenai jenis jantan dan tangan kirinya mengenai jenis betina, kemudian ia menaikkan semuanya ke dalam bahtera. Menurut Qiraat yang lain lafal kulli dibaca Kullin; berdasarkan qiraat ini lafal Zaujaini menjadi Maf'ul dan lafal Itsnaini berkedudukan mengukuhkan maknanya (dan juga keluargamu) istri dan anak-anakmu (kecuali orang yang telah lebih dahulu ketetapan azab atasnya di antara mereka) yaitu istri dan anaknya yang bernama Kan`an, lain halnya dengan anak-anaknya yang lain, yaitu Sam, Ham dan Yafits, Nabi Nuh mengangkut mereka bersama dengan istri-istri mereka ke dalam bahtera. Di dalam surah Hud telah disebutkan melalui firman-Nya, 'Dan muatkan pula orang-orang yang beriman. Dan tidak beriman bersama dengan Nuh itu kecuali sedikit.' (Q.S. Hud, 40). Menurut suatu pendapat dikatakan, bahwa jumlah mereka ada enam orang laki-laki berikut istri mereka. Menurut pendapat yang lain dikatakan, bahwa semua orang yang ada di dalam bahtera jumlahnya tujuh puluh delapan orang; separuh laki-laki dan yang separuh lagi perempuan. (Dan janganlah kamu bicarakan dengan Aku tentang orang-orang yang zalim) yaitu orang-orang yang kafir, biarkanlah mereka binasa (karena sesungguhnya mereka akan ditenggelamkan).",[["فَأَوْحَيْنَآ","Jadi Kami memberi inspirasi"],["إِلَيْهِ","kepadanya"],["أَنِ","Itu"],["ٱصْنَعِ","membina"],["ٱلْفُلْكَ","kapal itu"],["بِأَعْيُنِنَا","di bawah mata kita"],["وَوَحْيِنَا","dan inspirasi Kami"],["فَإِذَا","kemudian apabila"],["جَآءَ","datang"],["أَمْرُنَا","Perintah Kami"],["وَفَارَ","dan memancar keluar"],["ٱلتَّنُّورُ ۙ","ketuhar"],["فَٱسْلُكْ","kemudian letak"],["فِيهَا","ke dalamnya"],["مِن","daripada"],["كُلٍّۢ","setiap (jenis)"],["زَوْجَيْنِ","(dari) pasangan"],["ٱثْنَيْنِ","dua"],["وَأَهْلَكَ","dan keluarga kamu"],["إِلَّا","kecuali"],["مَن","mereka"],["سَبَقَ","(telah) mendahului"],["عَلَيْهِ","terhadap siapa"],["ٱلْقَوْلُ","Firman"],["مِنْهُمْ ۖ","daripadanya"],["وَلَا","Dan jangan"],["تُخَـٰطِبْنِى","alamat Aku"],["فِى","tentang"],["ٱلَّذِينَ","orang yang"],["ظَلَمُوٓا۟ ۖ","dizalimi"],["إِنَّهُم","sesungguhnya, mereka"],["مُّغْرَقُونَ","(adalah) mereka yang akan ditenggelamkan"]]],"2701":["(Apabila kamu telah lengkap) telah genap (yakni kamu dan orang-orang yang bersamamu berada di atas bahtera itu, maka ucapkanlah, 'Segala puji bagi Allah yang telah menyelamatkan kami dari orang-orang yang zalim') yakni orang-orang yang kafir dengan dibinasakannya mereka.",[["فَإِذَا","Dan apabila"],["ٱسْتَوَيْتَ","kamu (telah) menaiki"],["أَنتَ","kamu"],["وَمَن","dan sesiapa"],["مَّعَكَ","(ada) bersama kamu"],["عَلَى","[pada]"],["ٱلْفُلْكِ","kapal itu"],["فَقُلِ","kemudian berkata"],["ٱلْحَمْدُ","pujian"],["لِلَّهِ","bagi Allah"],["ٱلَّذِى","Siapa"],["نَجَّىٰنَا","(telah) menyelamatkan kita"],["مِنَ","daripada"],["ٱلْقَوْمِ","rakyat"],["ٱلظَّـٰلِمِينَ","orang yang zalim"]]],"2702":["(Dan berdoalah) di kala kamu turun dari bahtera, ('Ya Rabbku! Tempatkanlah aku pada tempat) kalau dibaca Munzalan berarti menjadi Mashdar dan Isim Makan/tempat sekaligus, apabila dibaca Manzilan berarti tempat berlabuh (yang diberkati) yakni tempat tersebut diberkati (dan Engkau adalah sebaik-baik yang memberi tempat'\") maksudnya Engkau adalah pemberi tempat yang paling baik kepada semua yang telah disebutkan tadi.",[["وَقُل","Dan katakan"],["رَّبِّ","Tuhanku"],["أَنزِلْنِى","menyebabkan aku mendarat"],["مُنزَلًۭا","(di) tempat pendaratan"],["مُّبَارَكًۭا","diberkati"],["وَأَنتَ","dan kamu"],["خَيْرُ","(adalah) yang terbaik"],["ٱلْمُنزِلِينَ","(dari) orang-orang yang menyebabkan darat.'"]]],"2703":["(Sesungguhnya pada kejadian itu) kisah Nabi Nuh dan bahteranya serta dibinasakan-Nya orang-orang kafir (benar-benar terdapat beberapa tanda) yang menunjukkan kepada kekuasaan Allah swt. (dan sesungguhnya) huruf In di sini adalah bentuk Takhfif daripada Inna, sedangkan isimnya adalah Dhamir Sya'an, bentuk asalnya adalah Innahu yakni sesungguhnya hal itu (Kamilah yang mencoba mereka) menguji kaum Nuh dengan mengutus Nuh kepada mereka supaya Nuh memberi nasihat dan pelajaran kepada mereka.",[["إِنَّ","Sesungguhnya"],["فِى","dalam"],["ذَٰلِكَ","bahawa"],["لَـَٔايَـٰتٍۢ","sesungguhnya (adalah) tanda-tanda"],["وَإِن","dan sesungguhnya"],["كُنَّا","Kami"],["لَمُبْتَلِينَ","pasti menguji"]]],"2704":["(Kemudian, Kami jadikan sesudah mereka umat) kaum (yang lain) mereka adalah kaum Ad.",[["ثُمَّ","Kemudian"],["أَنشَأْنَا","Kami menghasilkan"],["مِنۢ","selepas mereka"],["بَعْدِهِمْ","selepas mereka"],["قَرْنًا","satu generasi"],["ءَاخَرِينَ","yang lain"]]],"2705":["(Lalu Kami utus kepada mereka, seorang rasul dari kalangan mereka sendiri) yaitu Nabi Hud (\"Hendaklah) ia mengatakan kepada mereka (kalian menyembah Allah, sekali-kali tidak ada Tuhan selain daripada-Nya. Mengapa kalian tidak bertakwa) takut kepada azab-Nya karenanya kalian harus beriman kepada-Nya.",[["فَأَرْسَلْنَا","Dan Kami telah mengutus"],["فِيهِمْ","antara mereka"],["رَسُولًۭا","seorang Rasul"],["مِّنْهُمْ","daripada diri mereka sendiri"],["أَنِ","[bahawa]"],["ٱعْبُدُوا۟","Ibadah"],["ٱللَّهَ","Allah"],["مَا","tidak"],["لَكُم","bagi kamu"],["مِّنْ","(adalah) mana-mana"],["إِلَـٰهٍ","tuhan"],["غَيْرُهُۥٓ ۖ","selain Dia"],["أَفَلَا","Kemudian tidak akan"],["تَتَّقُونَ","kamu takut"]]],"2706":["(Dan berkatalah pemuka-pemuka yang kafir di antara kaumnya dan yang mendustakan akan menemui hari akhirat) yakni tempat mereka kembali kelak (dan yang telah Kami mewahkan mereka) Kami berikan nikmat kepada mereka (dalam kehidupan di dunia, 'Orang ini tidak lain hanyalah manusia seperti kalian, dia makan dari apa yang kalian makan dan minum dari apa yang kalian minum').",[["وَقَالَ","Dan berkata"],["ٱلْمَلَأُ","ketua-ketua"],["مِن","daripada"],["قَوْمِهِ","umatnya"],["ٱلَّذِينَ","yang"],["كَفَرُوا۟","kufur"],["وَكَذَّبُوا۟","dan dinafikan"],["بِلِقَآءِ","(the) mesyuarat"],["ٱلْـَٔاخِرَةِ","(dari) Akhirat"],["وَأَتْرَفْنَـٰهُمْ","sedang Kami telah memberi mereka kemewahan"],["فِى","dalam"],["ٱلْحَيَوٰةِ","kehidupan"],["ٱلدُّنْيَا","dunia"],["مَا","Tidak"],["هَـٰذَآ","(adalah) ini"],["إِلَّا","tetapi"],["بَشَرٌۭ","seorang lelaki"],["مِّثْلُكُمْ","macam kamu"],["يَأْكُلُ","Dia makan"],["مِمَّا","tentang apa"],["تَأْكُلُونَ","kamu makan"],["مِنْهُ","[daripadanya]"],["وَيَشْرَبُ","dan dia minum"],["مِمَّا","tentang apa"],["تَشْرَبُونَ","kamu minum"]]],"2707":["(Dan) demi Allah (sesungguhnya jika kamu sekalian menaati manusia yang seperti kalian) di dalam ayat ini terkandung makna Qasam atau sumpah dan Syarat, sedangkan Jawab dari Syarat tersebut terkandung pada ayat selanjutnya (niscaya bila demikian, kalian benar-benar) yakni jika kalian menaatinya (menjadi orang-orang yang merugi\") mendapat kerugian.",[["وَلَئِنْ","Dan pastinya jika"],["أَطَعْتُم","kamu taat"],["بَشَرًۭا","seorang lelaki"],["مِّثْلَكُمْ","macam kamu"],["إِنَّكُمْ","sesungguhnya, kamu"],["إِذًۭا","kemudian"],["لَّخَـٰسِرُونَ","nescaya (akan) merugi"]]],"2708":["(\"Apakah ia menjanjikan kepada kalian, bahwa bila kalian telah mati dan telah menjadi tanah dan tulang-belulang, kalian sesungguhnya akan dikeluarkan dari kuburan kalian) lafal Mukhrajuuna merupakan Khabar dari Annakum yang pertama, sedangkan lafal Annakum yang kedua berfungsi mengukuhkan makna Annakum yang pertama tadi, disebutkan lagi karena panjangnya Fashl atau pemisah antara Khabar dan 'Amilnya.",[["أَيَعِدُكُمْ","Adakah dia berjanji kepada kamu"],["أَنَّكُمْ","bahawa kamu"],["إِذَا","apabila"],["مِتُّمْ","kamu sudah mati"],["وَكُنتُمْ","dan kamu menjadi"],["تُرَابًۭا","habuk"],["وَعِظَـٰمًا","dan tulang"],["أَنَّكُم","bahawa kamu"],["مُّخْرَجُونَ","(akan) dilahirkan"]]],"2709":["(Jauh, jauh sekali) lafal Haihaata Haihaata adalah Isim Fi'il Madhi yang bermakna Mashdar, artinya jauh, jauh sekali dari kebenaran (apa yang diancamkan kepada kalian itu) yaitu dihidupkannya kembali kalian dari kuburan. Huruf Lam pada lafal Limaa Tuu'aduna adalah Lam Zaidah yang mengandung makna Bayan atau penjelasan.",[["۞ هَيْهَاتَ","Jauh-(mengarut)"],["هَيْهَاتَ","jauh-(mengarut)"],["لِمَا","adalah apa"],["تُوعَدُونَ","kamu dijanjikan"]]],"2710":["(Tiada lain hal itu) yakni kehidupan yang sesungguhnya (hanyalah kehidupan kita di dunia ini, kita mati kemudian kita hidup) yaitu dengan hidupnya anak-anak kita (dan sekali-kali kita tidak akan dibangkitkan kembali).",[["إِنْ","Tidak"],["هِىَ","ia"],["إِلَّا","(adalah) tetapi"],["حَيَاتُنَا","hidup kita"],["ٱلدُّنْيَا","dunia"],["نَمُوتُ","kita mati"],["وَنَحْيَا","dan kita hidup"],["وَمَا","dan bukan"],["نَحْنُ","kita"],["بِمَبْعُوثِينَ","(akan) dibangkitkan"]]],"2711":["(Ia tiada lain) Rasul itu (hanyalah seorang laki-laki yang mengada-adakan kebohongan terhadap Allah, dan kami sekali-kali tidak akan beriman kepadanya\") tidak akan percaya dengan adanya berbangkit sesudah mati.",[["إِنْ","Tidak"],["هُوَ","(ialah) dia"],["إِلَّا","tetapi"],["رَجُلٌ","seorang lelaki"],["ٱفْتَرَىٰ","yang (telah) mencipta"],["عَلَى","tentang"],["ٱللَّهِ","Allah"],["كَذِبًۭا","satu pembohongan"],["وَمَا","dan bukan"],["نَحْنُ","kita"],["لَهُۥ","(dalam) dia"],["بِمُؤْمِنِينَ","(adalah) orang yang beriman"]]],"2712":["(Rasul itu berdoa, \"Ya Rabbku! Tolonglah aku karena mereka mendustakanku\").",[["قَالَ","Dia berkata"],["رَبِّ","Tuhanku"],["ٱنصُرْنِى","Tolong aku"],["بِمَا","kerana"],["كَذَّبُونِ","mereka menafikan aku"]]],"2713":["(Allah berfirman, \"Dalam sedikit waktu lagi) sebentar lagi. Huruf Ma di sini adalah Zaidah (pasti mereka akan menjadi) akan menjadi orang-orang (yang menyesal\") atas kekafiran dan kedustaan mereka.",[["قَالَ","Dia berkata"],["عَمَّا","Selepas beberapa ketika"],["قَلِيلٍۢ","Selepas beberapa ketika"],["لَّيُصْبِحُنَّ","pasti mereka akan menjadi"],["نَـٰدِمِينَ","menyesal"]]],"2714":["(Maka dimusnahkanlah mereka oleh suara yang mengguntur) suara yang menandakan turunnya azab dan binasanya makhluk (dengan hak) maka matilah mereka (dan Kami jadikan mereka bagaikan tumbuh-tumbuhan yang kering) Kami jadikan mereka seperti tanaman yang kering atau mati (maka alangkah jauhnya) dari rahmat (bagi orang-orang yang zalim itu) yakni orang-orang yang mendustakan Rasul itu.",[["فَأَخَذَتْهُمُ","Maka tangkaplah mereka"],["ٱلصَّيْحَةُ","tangisan yang mengerikan"],["بِٱلْحَقِّ","dalam kebenaran"],["فَجَعَلْنَـٰهُمْ","dan Kami jadikan mereka"],["غُثَآءًۭ ۚ","(as) sampah daun mati"],["فَبُعْدًۭا","Jadi jauh"],["لِّلْقَوْمِ","dengan rakyat"],["ٱلظَّـٰلِمِينَ","orang yang zalim"]]],"2715":["(Kemudian Kami ciptakan sesudah mereka umat-umat) kaum-kaum (yang lain).",[["ثُمَّ","Kemudian"],["أَنشَأْنَا","Kami menghasilkan"],["مِنۢ","selepas mereka"],["بَعْدِهِمْ","selepas mereka"],["قُرُونًا","satu generasi"],["ءَاخَرِينَ","yang lain"]]],"2716":["(Tidak dapat sesuatu umat pun mendahului ajalnya) seumpamanya mereka mati sebelum ajal mereka (dan tidak dapat pula mereka terlambat) dari ajalnya itu. Lafal Yasta'khiruna dalam bentuk jamak dikaitkan kepada lafal Ummatin yang bentuknya muannats, hal ini memandang dari segi maknanya, karena ummatin berarti jamak.",[["مَا","Tidak"],["تَسْبِقُ","boleh mendahului"],["مِنْ","sebarang"],["أُمَّةٍ","bangsa"],["أَجَلَهَا","istilahnya"],["وَمَا","dan bukan"],["يَسْتَـْٔخِرُونَ","mereka (boleh) menangguhkan (ia)"]]],"2717":["(Kemudian Kami utus rasul-rasul Kami berturut-turut) lafal Tatran dapat pula dibaca Tatraa tanpa memakai harakat Tanwin, artinya berturut-turut yang di antara kedua rasul terdapat pemisah jarak waktu yang cukup lama. (Manakala datang kepada suatu umat) lafal Jaa-a Ummatan dapat dibaca Jaa-a ummatan yakni dengan mentashhilkan huruf Hamzah yang kedua, sehingga ucapannya seolah-olah ada huruf Wau (Rasul, umat itu mendustakannya, maka Kami perikutkan sebagian mereka dengan sebagian yang lain) Kami samakan mereka dengan umat-umat terdahulu dalam hal terbinasa (dan Kami jadikan mereka buah tutur manusia maka kebinasaanlah bagi orang-orang yang tidak beriman).",[["ثُمَّ","Kemudian"],["أَرْسَلْنَا","Kami utus"],["رُسُلَنَا","Rasul-rasul Kami"],["تَتْرَا ۖ","(dalam) berturut-turut"],["كُلَّ","setiap masa"],["مَا","setiap masa"],["جَآءَ","datang"],["أُمَّةًۭ","(kepada) suatu bangsa"],["رَّسُولُهَا","Rasulnya"],["كَذَّبُوهُ ۚ","mereka menafikannya"],["فَأَتْبَعْنَا","maka Kami jadikan (mereka) mengikut"],["بَعْضَهُم","sebahagian mereka"],["بَعْضًۭا","yang lain"],["وَجَعَلْنَـٰهُمْ","dan Kami jadikan mereka"],["أَحَادِيثَ ۚ","riwayat-riwayat"],["فَبُعْدًۭا","Jadi jauh"],["لِّقَوْمٍۢ","dengan suatu kaum"],["لَّا","tidak"],["يُؤْمِنُونَ","mereka beriman"]]],"2718":["(Kemudian Kami utus Musa dan saudaranya Harun dengan membawa tanda-tanda kebesaran Kami, dan bukti yang nyata) hujah yang nyata, yaitu berupa tangan, tongkat dan mukjizat-mukjizat lainnya.",[["ثُمَّ","Kemudian"],["أَرْسَلْنَا","Kami utus"],["مُوسَىٰ","Musa"],["وَأَخَاهُ","dan abangnya"],["هَـٰرُونَ","Harun"],["بِـَٔايَـٰتِنَا","dengan Tanda-tanda Kami"],["وَسُلْطَـٰنٍۢ","dan pihak berkuasa"],["مُّبِينٍ","yang nyata"]]],"2719":["(Kepada Firaun dan pembesar-pembesar kaumnya, maka mereka ini takabur) sombong tidak mau beriman kepada ayat-ayat dan mukjizat-mukjizat, dan juga mereka tidak mau beriman kepada Allah (dan mereka adalah orang-orang yang sombong) yaitu menindas kaum Bani Israel secara lalim.",[["إِلَىٰ","Kepada"],["فِرْعَوْنَ","Firaun"],["وَمَلَإِي۟هِۦ","dan ketua-ketuanya"],["فَٱسْتَكْبَرُوا۟","tetapi mereka bersikap angkuh"],["وَكَانُوا۟","dan mereka"],["قَوْمًا","suatu kaum"],["عَالِينَ","bongkak"]]],"2720":["(Dan mereka berkata, \"Apakah pantas kita percaya kepada dua orang manusia seperti kita juga, padahal kaum mereka adalah orang-orang yang menghambakan diri kepada kita?\") yakni kaum Bani Israel; mereka tunduk dan dianggap hina oleh Firaun.",[["فَقَالُوٓا۟","Kemudian mereka berkata"],["أَنُؤْمِنُ","Adakah kita akan beriman"],["لِبَشَرَيْنِ","(dalam) dua lelaki"],["مِثْلِنَا","seperti diri kita sendiri"],["وَقَوْمُهُمَا","sedangkan rakyat mereka"],["لَنَا","bagi kami"],["عَـٰبِدُونَ","(adalah) hamba"]]],"2721":["(Maka tetaplah mereka mendustakan keduanya, sebab itu mereka adalah termasuk orang-orang yang dibinasakan).",[["فَكَذَّبُوهُمَا","Maka mereka mendustakan mereka"],["فَكَانُوا۟","dan mereka menjadi"],["مِنَ","daripada"],["ٱلْمُهْلَكِينَ","mereka yang telah musnah"]]],"2722":["(Dan sesungguhnya telah Kami berikan Kitab kepada Musa) kitab Taurat (agar mereka) kaumnya, yaitu bangsa Bani Israel (mendapat petunjuk) dengan adanya kitab Taurat itu dari kesesatan. Aku memberikannya sekali turun sesudah Firaun dan kaumnya binasa",[["وَلَقَدْ","Dan sesungguhnya"],["ءَاتَيْنَا","Kami memberi"],["مُوسَى","Musa"],["ٱلْكِتَـٰبَ","Kitab Suci"],["لَعَلَّهُمْ","supaya mereka boleh"],["يَهْتَدُونَ","dibimbing"]]],"2723":["(Dan telah Kami jadikan putra Maryam) yakni Nabi Isa (beserta ibunya suatu tanda) kekuasaan Kami. Dalam ayat ini tidak disebutkan dua tanda karena keduanya terlibat dalam satu tanda itu, yaitu Maryam dapat melahirkan Nabi Isa tanpa suami (dan Kami menempatkan keduanya di suatu tanah tinggi) yakni tempat di dataran tinggi, yaitu di Baitulmakdis, atau di Damaskus, atau di Palestina; sehubungan dengan hal ini banyak pendapat mengenainya (yang datar) rata tanahnya sehingga para penghuninya menetap dengan nyaman (dan mempunyai banyak sumber air) yang mengalir lagi jernih sebagai suatu kenyataan.",[["وَجَعَلْنَا","Dan Kami jadikan"],["ٱبْنَ","(si) anak lelaki"],["مَرْيَمَ","(dari) Maryam"],["وَأُمَّهُۥٓ","dan ibunya"],["ءَايَةًۭ","sebuah Tanda"],["وَءَاوَيْنَـٰهُمَآ","dan Kami melindungi mereka"],["إِلَىٰ","kepada"],["رَبْوَةٍۢ","tanah tinggi"],["ذَاتِ","daripada ketenangan"],["قَرَارٍۢ","daripada ketenangan"],["وَمَعِينٍۢ","dan mata air"]]],"2724":["(Hai Rasul-rasul! Makanlah dari makanan yang baik-baik) makanan-makanan yang halal (dan kerjakanlah amal yang saleh) amal-amal yang fardu dan sunah. (Sesungguhnya Aku Maha Mengetahui apa yang kalian kerjakan) maka kelak Aku akan memperhitungkannya atas kalian.",[["يَـٰٓأَيُّهَا","Wahai para Rasul"],["ٱلرُّسُلُ","Wahai para Rasul"],["كُلُوا۟","makan"],["مِنَ","daripada"],["ٱلطَّيِّبَـٰتِ","perkara yang baik"],["وَٱعْمَلُوا۟","dan melakukan"],["صَـٰلِحًا ۖ","benar (perbuatan)"],["إِنِّى","Sesungguhnya, Aku"],["بِمَا","tentang apa"],["تَعْمَلُونَ","kamu lakukan"],["عَلِيمٌۭ","Maha Mengetahui"]]],"2725":["(Dan) ketahuilah (bahwasanya ini) yakni agama Islam (adalah agama kalian) hai orang-orang yang diajak bicara, maksudnya kalian harus memeluknya (agama yang satu) lafal Ummatan Waahidatan ini menjadi Hal yang bersifat Lazimah atau tetap. Menurut suatu qiraat yang lain lafal Anna haadzihi dibaca Takhfif sehingga menjadi An Haadzihi, sedangkan menurut qiraat yang lainnya lagi dibaca Inna Haadzihi, dan dianggap sebagai jumlah Isti'naf atau kalimat baru, sehingga artinya menjadi, sesungguhnya agama Islam ini (dan Aku adalah Rabb kalian, maka bertakwalah kalian kepada-Ku) artinya takutlah kalian kepada-Ku.",[["وَإِنَّ","Dan sesungguhnya"],["هَـٰذِهِۦٓ","ini"],["أُمَّتُكُمْ","agama kamu"],["أُمَّةًۭ","(ialah) agama"],["وَٰحِدَةًۭ","satu"],["وَأَنَا۠","Dan Aku"],["رَبُّكُمْ","Tuhanmu"],["فَٱتَّقُونِ","maka takutlah kepada-Ku"]]],"2726":["(Kemudian mereka memecah belah) para pengikut Rasul itu (perkara mereka) yakni agama mereka (menjadi beberapa pecahan di antara mereka) lafal Zuburan ini menjadi Hal dari Fa'ilnya lafal Taqaththa'uu, artinya, menjadi sekte-sekte yang bertentangan, seperti yang terjadi di kalangan orang-orang Yahudi dan orang-orang Nasrani serta lain-lainnya. (Tiap-tiap golongan terhadap apa yang ada pada sisi mereka) agama yang mereka pegang (merasa bangga) merasa puas dan gembira.",[["فَتَقَطَّعُوٓا۟","Tetapi mereka memotong"],["أَمْرَهُم","urusan mereka (perpaduan)"],["بَيْنَهُمْ","antara mereka"],["زُبُرًۭا ۖ","(menjadi) mazhab"],["كُلُّ","setiap satu"],["حِزْبٍۭ","puak"],["بِمَا","pada apa"],["لَدَيْهِمْ","mereka ada"],["فَرِحُونَ","bergembira"]]],"2727":["(Maka biarkanlah mereka) biarkanlah orang-orang kafir Mekah itu (dalam kesesatannya) (sampai suatu waktu) hingga saat kematian mereka.",[["فَذَرْهُمْ","Jadi tinggalkan mereka"],["فِى","dalam"],["غَمْرَتِهِمْ","kekeliruan mereka"],["حَتَّىٰ","sehingga"],["حِينٍ","suatu masa"]]],"2728":["(Apakah mereka mengira bahwa sesungguhnya apa-apa yang Kami berikan kepada mereka) artinya, Kami limpahkan kepada mereka (berupa harta benda dan anak-anak) di dunia ini.",[["أَيَحْسَبُونَ","Adakah mereka fikir"],["أَنَّمَا","itu apa"],["نُمِدُّهُم","Kami meluaskan kepada mereka"],["بِهِۦ","[dengannya]"],["مِن","daripada"],["مَّالٍۢ","kekayaan"],["وَبَنِينَ","dan kanak-kanak"]]],"2729":["(Kami bersegera) menyegerakan (memberikan kebaikan-kebaikan kepada mereka) tidak, sesungguhnya tidak demikian (sebenarnya mereka tidak sadar) bahwasanya hal itu adalah pengluluh atau Istidraj buat mereka.",[["نُسَارِعُ","Kami menyegerakan"],["لَهُمْ","kepada mereka"],["فِى","dalam"],["ٱلْخَيْرَٰتِ ۚ","yang baik"],["بَل","Bahkan"],["لَّا","tidak"],["يَشْعُرُونَ","mereka rasa"]]],"2730":["(Sesungguhnya orang-orang yang karena perasaan khasyyah mereka kepada Rabb mereka) disebabkan mereka takut kepada-Nya (mereka merasa takut sekali) kepada azab-Nya.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["هُم","[mereka]"],["مِّنْ","daripada"],["خَشْيَةِ","(yang) takut"],["رَبِّهِم","(dari) Tuhan mereka"],["مُّشْفِقُونَ","(adalah) berhati-hati"]]],"2731":["(Dan orang-orang yang terhadap ayat-ayat Rabb mereka) Alquran (mereka beriman) sangat percaya kepadanya.",[["وَٱلَّذِينَ","Dan mereka"],["هُم","[mereka]"],["بِـَٔايَـٰتِ","dalam (the) Tanda-tanda"],["رَبِّهِمْ","(dari) Tuhan mereka"],["يُؤْمِنُونَ","beriman"]]],"2732":["(Dan orang-orang yang tidak mempersekutukan dengan Rabb mereka) sesuatu apa pun.",[["وَٱلَّذِينَ","Dan mereka"],["هُم","[mereka]"],["بِرَبِّهِمْ","dengan Tuhan mereka"],["لَا","jangan"],["يُشْرِكُونَ","rakan kongsi bersekutu"]]],"2733":["(Dan orang-orang yang memberikan) yang menginfakkan (apa yang telah mereka berikan) mereka infakkan berupa zakat dan amal-amal saleh (dengan hati yang takut) takut amalnya tidak diterima (karena mereka tahu bahwa sesungguhnya mereka) sebelum lafal Annahum ini diperkirakan adanya huruf Lam yang menjarkannya (akan dikembalikan kepada Rabb mereka).",[["وَٱلَّذِينَ","Dan orang yang"],["يُؤْتُونَ","memberi"],["مَآ","apa"],["ءَاتَوا۟","mereka memberi"],["وَّقُلُوبُهُمْ","sedangkan hati mereka"],["وَجِلَةٌ","(adalah) takut"],["أَنَّهُمْ","kerana mereka"],["إِلَىٰ","kepada"],["رَبِّهِمْ","Tuhan mereka"],["رَٰجِعُونَ","(akan) kembali"]]],"2734":["(Mereka itu bersegera untuk mendapatkan kebaikan-kebaikan, dan merekalah orang-orang yang segera memperolehnya) menurut ilmu Allah.",[["أُو۟لَـٰٓئِكَ","(Ia adalah) mereka"],["يُسَـٰرِعُونَ","yang menyegerakan"],["فِى","dalam"],["ٱلْخَيْرَٰتِ","kebaikan (perbuatan)"],["وَهُمْ","dan mereka"],["لَهَا","dalam diri mereka"],["سَـٰبِقُونَ","(adalah) yang paling utama"]]],"2735":["(Kami tiada membebani seseorang melainkan menurut kesanggupannya) yang sesuai dengan kemampuannya, oleh karenanya barang siapa tidak mampu melakukan salat sambil berdiri, maka ia boleh melakukannya sambil duduk, dan barang siapa tidak mampu melakukan puasa maka ia boleh berbuka (dan pada sisi Kami) di sisi Kami (ada suatu kitab yang membicarakan dengan benar) apa yang telah dilakukan oleh seseorang, yaitu Lohmahfuz; padanya ditulis semua amal-amal perbuatan (dan mereka) kita semua orang yang beramal (tidak dianiaya) barang sedikit pun dari amal-amalnya, oleh karenanya sedikit pun tidak dikurangi pahala amal kebaikannya, dan tidak pula ditambah dosa-dosanya.",[["وَلَا","Dan tidak"],["نُكَلِّفُ","Kita bebankan"],["نَفْسًا","mana-mana jiwa"],["إِلَّا","kecuali"],["وُسْعَهَا ۖ","(kepada) kapasitinya"],["وَلَدَيْنَا","dan dengan Kami"],["كِتَـٰبٌۭ","(adalah) Rekod"],["يَنطِقُ","(yang) bercakap"],["بِٱلْحَقِّ ۚ","dengan kebenaran"],["وَهُمْ","dan mereka"],["لَا","(akan) tidak"],["يُظْلَمُونَ","dizalimi"]]],"2736":["(Tetapi hati mereka) yakni orang-orang kafir itu (dalam kealpaan) artinya, kebodohan (mengenai hal ini) yaitu Alquran (dan mereka banyak mengerjakan perbuatan-perbuatan selain daripada itu) selain amal-amal kebaikan yang dilakukan oleh orang-orang yang beriman (mereka tetap mengerjakannya) oleh sebab itu mereka diazab.",[["بَلْ","Bahkan"],["قُلُوبُهُمْ","hati mereka"],["فِى","(ada) dalam"],["غَمْرَةٍۢ","kekeliruan"],["مِّنْ","atas"],["هَـٰذَا","ini"],["وَلَهُمْ","dan untuk mereka"],["أَعْمَـٰلٌۭ","(adalah) perbuatan"],["مِّن","selain"],["دُونِ","selain"],["ذَٰلِكَ","bahawa"],["هُمْ","mereka"],["لَهَا","baginya"],["عَـٰمِلُونَ","(adalah) pelaku"]]],"2737":["(Hingga) menunjukkan makna Ibtida (apabila Kami timpakan kepada orang-orang yang hidup mewah di antara mereka) yakni orang-orang kaya dan pemimpin-pemimpin mereka (azab) dengan pedang dalam perang Badar (dengan serta merta mereka memekik minta tolong) mereka ribut meminta tolong. Kemudian dikatakan kepada mereka,",[["حَتَّىٰٓ","Sehinggalah"],["إِذَآ","apabila"],["أَخَذْنَا","Kita rampas"],["مُتْرَفِيهِم","mereka yang kaya raya"],["بِٱلْعَذَابِ","dengan hukuman"],["إِذَا","lihatlah"],["هُمْ","mereka"],["يَجْـَٔرُونَ","menangis minta tolong"]]],"2738":["(\"Janganlah kalian memekik, minta tolong pada hari ini. Sesungguhnya kalian tidak akan mendapat pertolongan dari Kami) maksudnya tidak ada seorang pun yang dapat menolong kalian.",[["لَا","Jangan"],["تَجْـَٔرُوا۟","menangis minta tolong"],["ٱلْيَوْمَ ۖ","hari ini"],["إِنَّكُم","Sesungguhnya kamu"],["مِّنَّا","daripada Kami"],["لَا","tidak"],["تُنصَرُونَ","akan dibantu"]]],"2739":["(Sesungguhnya ayat-ayat-Ku) dari Alquran (selalu dibacakan kepada kalian, tetapi kalian selalu berpaling ke belakang) mundur ke belakang maksudnya kalian tidak mau menerimanya.",[["قَدْ","Sesungguhnya"],["كَانَتْ","adalah"],["ءَايَـٰتِى","Ayat-ayat Aku"],["تُتْلَىٰ","dibacakan"],["عَلَيْكُمْ","kepada kamu"],["فَكُنتُمْ","tapi kamu guna"],["عَلَىٰٓ","(ke) pada"],["أَعْقَـٰبِكُمْ","tumit kamu"],["تَنكِصُونَ","berpatah balik"]]],"2740":["(Dengan menyombongkan diri) tidak mau beriman (akan keakuan kalian) yakni membanggakan Kakbah atau tanah suci yang kalian tempati, maksudnya kalian beranggapan bahwa diri kalian adalah penduduknya, oleh karena itu kalian merasa dalam keadaan aman dari azab Allah, berbeda dengan kaum-kaum yang lain di tempat tinggal mereka selain dari tanah suci (dan seraya bergadang) lafal Samiran menjadi Hal, artinya mereka berkumpul membentuk suatu kelompok sambil berbincang-bincang di waktu malam hari; hal ini mereka lakukan di sekeliling Kakbah (kalian mengucapkan perkataan-perkataan yang keji terhadapnya\") lafal Tahjuruuna ini jika berasal dari Fi'il Tsulatsi artinya tidak menganggap Alquran. Jika berasal dari Fi'il Ruba'i berarti mereka membuat-buat perkataan yang keji tanpa hak terhadap diri Nabi saw. dan Alquran. Selanjutnya Allah swt. berfirman,",[["مُسْتَكْبِرِينَ","(Menjadi) sombong"],["بِهِۦ","mengenainya"],["سَـٰمِرًۭا","bercakap-cakap pada waktu malam"],["تَهْجُرُونَ","bercakap jahat"]]],"2741":["(Maka apakah mereka tidak memperhatikan) asal lafal Yaddabbaruu adalah Yatadabbaruuna, kemudian huruf Ta dimasukkan ke dalam huruf Dal setelah terlebih dahulu diganti menjadi Dal, sehingga jadilah Yaddabbaruuna (perkataan ini) Alquran ini yang menunjukkan kebenaran Nabi saw. (atau apakah telah datang kepada mereka apa yang tidak pernah datang kepada nenek moyang mereka dahulu?)",[["أَفَلَمْ","Kemudian, jangan"],["يَدَّبَّرُوا۟","mereka merenung"],["ٱلْقَوْلَ","Firman"],["أَمْ","atau"],["جَآءَهُم","telah datang kepada mereka"],["مَّا","apa"],["لَمْ","tidak"],["يَأْتِ","(telah) datang"],["ءَابَآءَهُمُ","(kepada) nenek moyang mereka"],["ٱلْأَوَّلِينَ","(kepada) nenek moyang mereka"]]],"2742":["(Ataukah mereka tidak mengenal Rasul mereka, karena itu mereka memungkirinya?)",[["أَمْ","Atau"],["لَمْ","jangan"],["يَعْرِفُوا۟","mereka mengenali"],["رَسُولَهُمْ","Rasul mereka"],["فَهُمْ","jadi mereka"],["لَهُۥ","(sedang) menolaknya"],["مُنكِرُونَ","(sedang) menolaknya"]]],"2743":["(Atau apakah patut mereka berkata, \"Padanya ada penyakit gila\") Istifham atau kata tanya di sini mengandung arti Taqrir atau menetapkan perkara yang hak, yaitu membenarkan Nabi dan membenarkan bahwa Rasul-rasul telah datang kepada umat-umat terdahulu, serta mereka mengetahui bahwa Rasul mereka adalah orang yang jujur dan dapat dipercaya, dan bahwasanya Rasul mereka itu tidak gila. (Sebenarnya) lafal Bal menunjukkan makna Intiqal (dia telah membawa kebenaran kepada mereka) yakni Alquran yang di dalamnya terkandung ajaran Tauhid dan hukum-hukum Islam (dan kebanyakan mereka benci kepada kebenaran itu).",[["أَمْ","Atau"],["يَقُولُونَ","mereka berkata"],["بِهِۦ","Dalam dia"],["جِنَّةٌۢ ۚ","(adalah) kegilaan"],["بَلْ","Bahkan"],["جَآءَهُم","dia membawa mereka"],["بِٱلْحَقِّ","kebenaran"],["وَأَكْثَرُهُمْ","tetapi kebanyakan mereka"],["لِلْحَقِّ","kepada kebenaran"],["كَـٰرِهُونَ","(ada) enggan"]]],"2744":["(Andaikata kebenaran itu menuruti) artinya Alquran itu menuruti (hawa nafsu mereka) seumpamanya Alquran itu datang dengan membawa hal-hal yang mereka sukai, seperti menisbatkan sekutu dan anak kepada Allah, padahal Allah Maha Suci dari hal tersebut (pasti binasalah langit dan bumi dan semua yang ada di dalamnya) yakni menyimpang dari tatanan yang sebenarnya dan tidak seperti apa yang disaksikan sekarang, hal itu disebabkan adanya dua pengaruh kekuasaan yang saling tarik-menarik. (Sebenarnya Kami telah mendatangkan kepada mereka kebanggaan mereka) yaitu Alquran yang di dalamnya terkandung sebutan dan kemuliaan mereka (tetapi mereka berpaling dari kebanggaan itu).",[["وَلَوِ","Tetapi jika"],["ٱتَّبَعَ","(telah) mengikuti"],["ٱلْحَقُّ","kebenaran"],["أَهْوَآءَهُمْ","keinginan mereka"],["لَفَسَدَتِ","nescaya (akan) rosak"],["ٱلسَّمَـٰوَٰتُ","langit"],["وَٱلْأَرْضُ","dan bumi"],["وَمَن","dan sesiapa"],["فِيهِنَّ ۚ","(ada) di dalamnya"],["بَلْ","Bahkan"],["أَتَيْنَـٰهُم","Kami telah membawa mereka"],["بِذِكْرِهِمْ","peringatan mereka"],["فَهُمْ","tetapi mereka"],["عَن","daripada"],["ذِكْرِهِم","peringatan mereka"],["مُّعْرِضُونَ","(sedang) berpaling"]]],"2745":["(Atau kamu meminta upah kepada mereka) sebagai imbalan dari apa yang kamu datangkan buat mereka yaitu masalah keimanan (maka upah Rabbmu) adalah pahala, upah dan rezeki-Nya (adalah lebih baik) dan menurut qiraat yang lain dibaca Kharjan dalam dua tempat tadi; tetapi menurut qiraat yang lainnya lagi dibaca Kharaajan pada keduanya (dan Dia adalah Pemberi rezeki Yang Paling Baik) Pengupah Yang Paling Utama.",[["أَمْ","Atau"],["تَسْـَٔلُهُمْ","kamu bertanya kepada mereka"],["خَرْجًۭا","(untuk) bayaran"],["فَخَرَاجُ","Tetapi pembayaran"],["رَبِّكَ","Tuhanmu"],["خَيْرٌۭ ۖ","(adalah) terbaik"],["وَهُوَ","dan Dia"],["خَيْرُ","(adalah) yang Terbaik"],["ٱلرَّٰزِقِينَ","(dari) Pembekal"]]],"2746":["(Dan sesungguhnya kamu benar-benar menyeru mereka kepada jalan) tuntunan (yang lurus) yaitu agama Islam.",[["وَإِنَّكَ","Dan sesungguhnya, kamu"],["لَتَدْعُوهُمْ","pasti memanggil mereka"],["إِلَىٰ","kepada"],["صِرَٰطٍۢ","(the) Jalan"],["مُّسْتَقِيمٍۢ","Lurus"]]],"2747":["(Dan sesungguhnya orang-orang yang tidak beriman kepada adanya hari akhirat) adanya hari berbangkit dan pembalasan pahala serta azab (dari jalan yang lurus) dari tuntunan yang lurus (mereka benar-benar menyimpang) yakni membelok.",[["وَإِنَّ","Dan sesungguhnya"],["ٱلَّذِينَ","orang yang"],["لَا","jangan"],["يُؤْمِنُونَ","beriman"],["بِٱلْـَٔاخِرَةِ","di akhirat"],["عَنِ","daripada"],["ٱلصِّرَٰطِ","laluan itu"],["لَنَـٰكِبُونَ","sesungguhnya (sedang) menyimpang"]]],"2748":["(Andaikata mereka Kami belas kasihani, dan Kami lenyapkan kemudaratan yang mereka alami) yakni kelaparan yang menimpa mereka di Mekah selama tujuh tahun itu (benar-benar mereka akan terus-menerus) masih tetap dan berkepanjangan (dalam keterlaluan mereka) dalam kesesatan mereka (mereka bergelimang) terombang-ambing.",[["۞ وَلَوْ","Dan jika"],["رَحِمْنَـٰهُمْ","Kami telah mengasihani mereka"],["وَكَشَفْنَا","dan Kami hapuskan"],["مَا","apa"],["بِهِم","(ada) pada mereka"],["مِّن","daripada"],["ضُرٍّۢ","(yang) kesusahan"],["لَّلَجُّوا۟","pasti mereka akan berterusan"],["فِى","dalam"],["طُغْيَـٰنِهِمْ","pelanggaran mereka"],["يَعْمَهُونَ","merayau buta"]]],"2749":["(Dan sesungguhnya Kami telah pernah menimpakan azab kepada mereka) kelaparan itu (tetapi mereka masih tidak tunduk) masih tidak mau merendahkan diri (kepada Rabb mereka, dan juga mereka tidak mau ber-tadharru' kepada-Nya) maksudnya mereka tidak mau juga meminta kepada Allah dengan berdoa kepada-Nya.",[["وَلَقَدْ","Dan sesungguhnya"],["أَخَذْنَـٰهُم","Kami menangkap mereka"],["بِٱلْعَذَابِ","dengan hukuman"],["فَمَا","tetapi tidak"],["ٱسْتَكَانُوا۟","mereka menyerahkan"],["لِرَبِّهِمْ","kepada Tuhan mereka"],["وَمَا","dan bukan"],["يَتَضَرَّعُونَ","mereka berdoa dengan rendah hati"]]],"2750":["(Hingga) lafal Hattaa menunjukkan makna Ibtida atau permulaan (apabila Kami bukakan untuk mereka suatu pintu yang di dalamnya ada) terdapat (azab yang keras) yaitu perang Badar tempat mereka terbunuh (tiba-tiba mereka menjadi berputus asa) putus harapan dari semua kebaikan.",[["حَتَّىٰٓ","Sehinggalah"],["إِذَا","apabila"],["فَتَحْنَا","Kami buka"],["عَلَيْهِم","bagi mereka"],["بَابًۭا","sebuah pintu pagar"],["ذَا","daripada suatu hukuman"],["عَذَابٍۢ","daripada suatu hukuman"],["شَدِيدٍ","teruk"],["إِذَا","lihatlah"],["هُمْ","mereka"],["فِيهِ","di dalamnya"],["مُبْلِسُونَ","(akan berada dalam) putus asa"]]],"2751":["(Dan Dialah Yang menciptakan) yang menjadikan (bagi kamu sekalian pendengaran) lafal As Sam'u maknanya Al Asmaa', dalam bentuk jamak (penglihatan dan kalbu) hati. (Amat sedikitlah) lafal Maa mengukuhkan makna yang terkandung dalam lafal Qaliilan (kalian bersyukur).",[["وَهُوَ","Dan Dia"],["ٱلَّذِىٓ","(ialah) Yang"],["أَنشَأَ","dihasilkan"],["لَكُمُ","bagi kamu"],["ٱلسَّمْعَ","pendengaran"],["وَٱلْأَبْصَـٰرَ","dan penglihatan"],["وَٱلْأَفْـِٔدَةَ ۚ","dan perasaan"],["قَلِيلًۭا","sedikit"],["مَّا","(ialah) apa"],["تَشْكُرُونَ","kamu ucapkan terima kasih"]]],"2752":["(Dan Dialah yang mengembangbiakkan kalian) menciptakan kalian (di bumi ini, dan hanya kepada-Nyalah kalian akan dihimpunkan) akan dibangkitkan menjadi hidup kembali kemudian menghadap kepada-Nya.",[["وَهُوَ","Dan Dia"],["ٱلَّذِى","(ialah) Yang"],["ذَرَأَكُمْ","memperbanyakkan kamu"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["وَإِلَيْهِ","dan kepada-Nya"],["تُحْشَرُونَ","kamu akan dikumpulkan"]]],"2753":["(Dan Dialah yang menghidupkan) dengan meniupkan roh ke dalam Mudhghah atau janin (dan mematikan, dan Dialah yang mengatur pertukaran malam dan siang) malam gelap, dan siang menjadi terang, serta menambah panjang dan mengurangi waktu salah satu di antara keduanya. (Maka apakah kalian tidak memahaminya?) maksudnya memahami ciptaan Allah swt., kemudian kalian mengambil pelajaran daripadanya.",[["وَهُوَ","Dan Dia"],["ٱلَّذِى","(ialah) Yang"],["يُحْىِۦ","memberi kehidupan"],["وَيُمِيتُ","dan menyebabkan kematian"],["وَلَهُ","dan untuk Dia"],["ٱخْتِلَـٰفُ","(ialah) silih berganti"],["ٱلَّيْلِ","(dari) malam"],["وَٱلنَّهَارِ ۚ","dan hari"],["أَفَلَا","Kemudian tidak akan"],["تَعْقِلُونَ","kamu sebab"]]],"2754":["(Sebenarnya mereka mengucapkan perkataan yang serupa dengan perkataan yang diucapkan oleh orang-orang dahulu kala).",[["بَلْ","Bahkan"],["قَالُوا۟","mereka berkata"],["مِثْلَ","(yang) seperti"],["مَا","apa"],["قَالَ","berkata"],["ٱلْأَوَّلُونَ","bekas (orang)"]]],"2755":["(Mereka berkata) orang-orang dahulu itu, (\"Apakah betul, apabila kami telah mati dan kami telah menjadi tanah dan tulang-belulang, apakah sesungguhnya kami benar-benar akan dibangkitkan hidup kembali?) memang kalian akan dibangkitkan kembali oleh-Nya. Kedua huruf Hamzah pada dua tempat ini dapat dibaca Tahqiq, sehingga bacaannya menjadi A-innaa. Sebagaimana huruf Hamzah yang keduanya dapat pula dibaca Tas-hil, sehingga bacaannya menjadi Ayinnaa. Sehubungan dengan bacaan ini ada dua pendapat, yaitu men-tahqiq-kan kedua Hamzahnya dan men-tashil-kan Hamzah yang kedua.",[["قَالُوٓا۟","Mereka berkata"],["أَءِذَا","Apa! apabila"],["مِتْنَا","kita mati"],["وَكُنَّا","dan menjadi"],["تُرَابًۭا","habuk"],["وَعِظَـٰمًا","dan tulang"],["أَءِنَّا","adakah kita"],["لَمَبْعُوثُونَ","pasti dibangkitkan"]]],"2756":["(Sesungguhnya kami dan bapak-bapak kami telah diberi ancaman dengan ini) yaitu dengan masalah akan dibangkitkan menjadi hidup kembali sesudah mati (dahulu, tiada lain) tidak lain (ia hanyalah dongengan-dongengan) kebohongan-kebohongan (orang-orang dahulu kala\") wazan lafal Asaathiir sama dengan lafal Al Adhaahiik dan Al-A`aajiib, adalah bentuk jamak dari lafal Usthuurah artinya dongengan atau fiksi.",[["لَقَدْ","Sesungguhnya"],["وُعِدْنَا","kita telah dijanjikan"],["نَحْنُ","[kami]"],["وَءَابَآؤُنَا","dan nenek moyang kita"],["هَـٰذَا","ini"],["مِن","sebelum"],["قَبْلُ","sebelum"],["إِنْ","tidak"],["هَـٰذَآ","(adalah) ini"],["إِلَّآ","tetapi"],["أَسَـٰطِيرُ","(the) cerita"],["ٱلْأَوَّلِينَ","(dari) orang-orang dahulu"]]],"2757":["(Katakanlah) kepada mereka, (\"Kepunyaan siapakah bumi ini, dan semua yang ada padanya) yakni semua makhluk yang ada padanya (jika kalian mengetahui?\") siapa pencipta dan pemiliknya.",[["قُل","Katakanlah"],["لِّمَنِ","milik siapa (kepunyaan)"],["ٱلْأَرْضُ","bumi"],["وَمَن","dan sesiapa"],["فِيهَآ","(ada) di dalamnya"],["إِن","jika"],["كُنتُمْ","kamu"],["تَعْلَمُونَ","mengetahui"]]],"2758":["(Mereka akan menjawab, \"Kepunyaan Allah.\" Katakanlah) kepada mereka, (\"Maka apakah kalian tidak memikirkannya?\") asal Tadzakkaruuna adalah Tatadzakkaruuna kemudian huruf Ta yang kedua diidgamkan atau dimasukkan ke dalam huruf Dzal setelah terlebih dahulu diganti menjadi Dzal, sehingga jadilah Tadzakkaruuna, artinya mengambil pelajaran. Maksudnya, apakah kalian tidak mengambil pelajaran daripadanya, karena kalian mengetahui, bahwa Tuhan Yang Maha Kuasa yang telah menciptakan untuk pertama kali, Maha Kuasa pula untuk menghidupkannya kembali, sesudah ciptaan-Nya mati.",[["سَيَقُولُونَ","Mereka akan berkata"],["لِلَّهِ ۚ","Kepada Allah"],["قُلْ","Katakanlah"],["أَفَلَا","Kemudian tidak akan"],["تَذَكَّرُونَ","kamu ingat"]]],"2759":["(Katakanlah! \"Siapakah Rabb langit yang tujuh dan Rabb Arasy yang besar\") yakni Al Kursi.",[["قُلْ","Katakanlah"],["مَن","Siapa"],["رَّبُّ","(ialah) Tuhan"],["ٱلسَّمَـٰوَٰتِ","(dari) tujuh langit"],["ٱلسَّبْعِ","(dari) tujuh langit"],["وَرَبُّ","dan (yang) Tuhan"],["ٱلْعَرْشِ","(dari) Arasy"],["ٱلْعَظِيمِ","yang Agung"]]],"2760":["(Mereka akan menjawab, \"Kepunyaan Allah\". Katakanlah! \"Apakah kalian tidak bertakwa?\") tidak takut bila kalian menyembah selain-Nya.",[["سَيَقُولُونَ","Mereka akan berkata"],["لِلَّهِ ۚ","Allah"],["قُلْ","Katakanlah"],["أَفَلَا","Kemudian tidak akan"],["تَتَّقُونَ","kamu takut (dia)"]]],"2761":["(Katakanlah! \"Siapakah yang di tangan-Nya berada kekuasaan) yakni merajai (segala sesuatu) lafal Malakuut huruf Ta yang ada padanya menunjukkan makna Mubalaghah, yakni kekuasaan di atas segala kekuasaan (sedangkan Dia melindungi dan tidak membutuhkan perlindungan) Dia melindungi dan tidak memerlukan perlindungan (jika kalian mengetahui?\")",[["قُلْ","Katakanlah"],["مَنۢ","Siapakah (ia)"],["بِيَدِهِۦ","di Tangan Siapa"],["مَلَكُوتُ","(ialah) kekuasaan"],["كُلِّ","(dari) semua"],["شَىْءٍۢ","benda"],["وَهُوَ","dan Dia"],["يُجِيرُ","melindungi"],["وَلَا","dan tiada (seorang)"],["يُجَارُ","(boleh) dilindungi"],["عَلَيْهِ","terhadap Dia"],["إِن","Jika"],["كُنتُمْ","kamu"],["تَعْلَمُونَ","mengetahui"]]],"2762":["(Mereka akan menjawab, \"Kepunyaan Allah\") menurut qiraat yang lain dibaca Allah, baik dalam ayat ini maupun dalam ayat sebelumnya. Demikian itu karena makna yang dimaksud adalah, kepunyaan siapakah hal-hal yang telah disebutkan itu (Katakanlah! \"Kalau demikian maka dari jalan manakah kalian merasa ditipu?\") ditipu dan dikelabui dari perkara yang hak, yaitu menyembah Allah semata. Maksudnya, bagaimanakah bisa terbayangkan dalam benak kalian bahwasanya hal ini batil?",[["سَيَقُولُونَ","Mereka akan berkata"],["لِلَّهِ ۚ","Allah"],["قُلْ","Katakanlah"],["فَأَنَّىٰ","Kemudian bagaimana"],["تُسْحَرُونَ","adakah kamu tertipu"]]],"2763":["(Sebenarnya Kami telah membawa kebenaran kepada mereka) dengan sesungguhnya (dan sesungguhnya mereka benar-benar orang-orang yang berdusta) sewaktu mereka menentang kebenaran itu; kebenaran tersebut adalah,",[["بَلْ","Bahkan"],["أَتَيْنَـٰهُم","Kami (telah) membawa mereka"],["بِٱلْحَقِّ","kebenaran"],["وَإِنَّهُمْ","tetapi sesungguhnya, mereka"],["لَكَـٰذِبُونَ","sesungguhnya, (adalah) pendusta"]]],"2764":["(Allah sekali-kali tidak mempunyai anak, dan sekali-kali tidak ada tuhan yang lain beserta-Nya, kalau ada tuhan beserta-Nya) jika ada tuhan lain di samping Dia (masing-masing tuhan itu akan membawa makhluk yang diciptakannya) yang menguasai makhluknya sendiri dan mempertahankannya dari makhluk tuhan yang lain (dan sebagian dari tuhan-tuhan itu akan mengalahkan sebagian yang lain) sebagian di antara mereka berupaya untuk mengalahkan sebagian yang lain sebagaimana apa yang biasa dilakukan oleh raja-raja di dunia. (Maha Suci Allah) lafal Subhaanallaah ini berarti mensucikan Dia (dari apa yang mereka sifatkan) kepada-Nya, seperti apa yang telah disebutkan tadi.",[["مَا","Tidak"],["ٱتَّخَذَ","Allah telah mengambil"],["ٱللَّهُ","Allah telah mengambil"],["مِن","sebarang"],["وَلَدٍۢ","nak"],["وَمَا","dan bukan"],["كَانَ","ialah"],["مَعَهُۥ","dengan Dia"],["مِنْ","sebarang"],["إِلَـٰهٍ ۚ","tuhan"],["إِذًۭا","Kemudian"],["لَّذَهَبَ","nescaya (akan) diambil"],["كُلُّ","setiap satu"],["إِلَـٰهٍۭ","tuhan"],["بِمَا","apa"],["خَلَقَ","dia cipta"],["وَلَعَلَا","dan pasti akan dikalahkan"],["بَعْضُهُمْ","sebahagian mereka"],["عَلَىٰ","[pada]"],["بَعْضٍۢ ۚ","yang lain"],["سُبْحَـٰنَ","Maha Suci"],["ٱللَّهِ","(kepada) Allah"],["عَمَّا","atas apa"],["يَصِفُونَ","mereka sifatkan"]]],"2765":["(Yang mengetahui semua yang gaib dan semua yang tampak) maksudnya semua yang tidak tampak dan semua yang tampak. Kalau dibaca 'Aalimil Ghaibi menjadi sifat, artinya yang mengetahui dan seterusnya. Jika dibaca 'Aalimul Ghaibi berarti menjadi Khabar dari Mubtada yang tidak disebutkan yaitu lafal Huwa, artinya Dia Mengetahui yang gaib (maka Maha Tinggi Dia) Maha Besar Dia (dari apa yang mereka persekutukan) kepada-Nya.",[["عَـٰلِمِ","Maha Mengetahui"],["ٱلْغَيْبِ","(dari) perkara ghaib"],["وَٱلشَّهَـٰدَةِ","dan yang disaksikan"],["فَتَعَـٰلَىٰ","Maha Tinggi Dia"],["عَمَّا","atas apa"],["يُشْرِكُونَ","mereka bergaul"]]],"2766":["(Katakanlah! \"Ya Rabbku! Jika) lafal Imma pada asalnya terdiri daripada gabungan antara In Syarthiyyah dan Ma Zaidah (Engkau sungguh-sungguh hendak memperlihatkan kepadaku apa yang diancamkan kepada mereka) berupa azab, hal ini benar-benar terjadi dalam perang Badar, yaitu banyak dari kalangan orang-orang musyrik yang mati terbunuh.",[["قُل","Katakanlah"],["رَّبِّ","Tuhanku"],["إِمَّا","Jika"],["تُرِيَنِّى","Kamu patut tunjukkan aku"],["مَا","apa"],["يُوعَدُونَ","mereka dijanjikan"]]],"2767":["(Ya Rabbku! Maka janganlah Engkau jadikan aku berada di antara orang-orang yang zalim.\") karena aku pun nanti akan binasa pula bersama dengan mereka.",[["رَبِّ","Tuhanku"],["فَلَا","maka (buat) jangan"],["تَجْعَلْنِى","letak aku"],["فِى","antara"],["ٱلْقَوْمِ","rakyat"],["ٱلظَّـٰلِمِينَ","orang yang zalim"]]],"2768":["(Dan sesungguhnya Kami benar-benar kuasa untuk memperlihatkan kepadamu apa yang Kami ancamkan kepada mereka).",[["وَإِنَّا","Dan sesungguhnya Kami"],["عَلَىٰٓ","pada"],["أَن","bahawa"],["نُّرِيَكَ","Kami tunjukkan kepada kamu"],["مَا","apa"],["نَعِدُهُمْ","Kami telah berjanji kepada mereka"],["لَقَـٰدِرُونَ","pasti mampu"]]],"2769":["(Tolaklah dengan menampilkan hal yang lebih baik) yaitu budi pekerti yang baik, bersikap lapang dada dan berpaling dari mereka yang kafir (hal yang buruk itu) perlakuan mereka yang menyakitkan terhadap dirimu. Ayat ini diturunkan sebelum ada perintah untuk berperang. (Kami lebih mengetahui apa yang mereka sifatkan) kedustaan dan buat-buatan mereka, maka kelak Kami akan membalasnya kepada mereka.",[["ٱدْفَعْ","Tolak"],["بِٱلَّتِى","oleh itu"],["هِىَ","yang"],["أَحْسَنُ","(adalah) terbaik"],["ٱلسَّيِّئَةَ ۚ","yang jahat"],["نَحْنُ","Kami"],["أَعْلَمُ","tahu yang terbaik"],["بِمَا","tentang apa"],["يَصِفُونَ","mereka sifatkan"]]],"2770":["(Dan katakanlah! \"Ya Rabbku! Aku berlindung kepada Engkau) aku meminta perlindungan (dari bisikan-bisikan setan) dari kecenderungan-kecenderungan setan yang selalu setan embus-embuskan itu.",[["وَقُل","Dan katakan"],["رَّبِّ","Tuhanku"],["أَعُوذُ","Aku mencari perlindungan"],["بِكَ","pada-Mu"],["مِنْ","daripada"],["هَمَزَٰتِ","(the) cadangan"],["ٱلشَّيَـٰطِينِ","(dari) orang-orang yang jahat"]]],"2771":["(Dan aku berlindung pula kepada Engkau, ya Rabbku, dari kedatangan setan-setan itu kepadaku\") dalam perkara-perkaraku, karena sesungguhnya mereka datang hanya dengan membawa keburukan belaka.",[["وَأَعُوذُ","Dan aku mencari perlindungan"],["بِكَ","pada-Mu"],["رَبِّ","Tuhanku"],["أَن","Jangan-jangan"],["يَحْضُرُونِ","mereka hadir bersama aku"]]],"2772":["(Sehingga) lafal Hattaa menunjukkan makna Ibtida atau permulaan (apabila datang kematian kepada seseorang dari mereka) kemudian ia melihat kedudukannya di neraka dan di surga seandainya ia beriman (dia berkata, \"Ya Rabbku! Kembalikanlah aku) ke dunia. Ungkapan Jamak pada lafal Irji'uuni mengandung makna Ta'zhim atau mengagungkan.",[["حَتَّىٰٓ","Sehinggalah"],["إِذَا","apabila"],["جَآءَ","datang"],["أَحَدَهُمُ","(kepada) salah seorang daripada mereka"],["ٱلْمَوْتُ","kematian itu"],["قَالَ","katanya"],["رَبِّ","Tuhanku"],["ٱرْجِعُونِ","Hantar aku balik"]]],"2773":["(Agar aku berbuat amal yang saleh) dengan mengatakan, 'Aku bersaksi tiada Tuhan selain Allah', hal ini akan menjadi penghapus (terhadap yang telah aku tinggalkan\") aku sia-siakan umurku. Maksudnya, supaya hal itu menjadi penggantinya. Maka Allah berfirman, (\"Sekali-kali tidak) tidak ada kembali lagi. (Sesungguhnya itu) permohonan untuk kembali ke dunia (adalah perkataan yang diucapkannya saja) tidak ada manfaat bagi pembicaranya. (Dan di hadapan mereka) (ada dinding) penghalang yang menahan mereka untuk dapat kembali lagi ke dunia (sampai hari mereka dibangkitkan\") yang tiada kembali lagi sesudahnya.",[["لَعَلِّىٓ","Yang aku boleh"],["أَعْمَلُ","lakukan"],["صَـٰلِحًۭا","benar (perbuatan)"],["فِيمَا","pada apa"],["تَرَكْتُ ۚ","aku tinggalkan"],["كَلَّآ ۚ","Tidak"],["إِنَّهَا","Sesungguhnya, ia"],["كَلِمَةٌ","(adalah) perkataan"],["هُوَ","dia"],["قَآئِلُهَا ۖ","bercakap itu"],["وَمِن","dan di hadapan mereka"],["وَرَآئِهِم","dan di hadapan mereka"],["بَرْزَخٌ","(adalah) penghalang"],["إِلَىٰ","sehingga"],["يَوْمِ","(the) Hari"],["يُبْعَثُونَ","mereka dibangkitkan"]]],"2774":["(Apabila sangkakala ditiup) tiupan malaikat Israfil yang pertama atau yang kedua (maka tidaklah ada lagi pertalian nasab di antara mereka pada hari itu) yang dapat mereka bangga-banggakan (dan tidak pula mereka saling bertanya) tentang nasab tersebut, berbeda dengan ketika mereka hidup di dunia. Hal tersebut disebabkan kengerian yang menyibukkan diri mereka pada hari kiamat itu, yakni melihat sebagian kengerian-kengerian yang ada padanya. Pada sebagian waktu dari hari kiamat mereka sadar pula, sebagaimana yang diungkapkan oleh ayat yang lain, yaitu, \"Dan sebagian dari mereka menghadap kepada sebagian yang lain berbantah-bantahan.\" (Q.S. Ash-Shaffat, 27).",[["فَإِذَا","Maka apabila"],["نُفِخَ","ditiup"],["فِى","dalam"],["ٱلصُّورِ","sangkakala"],["فَلَآ","maka tidak"],["أَنسَابَ","(ada) akan ada hubungan"],["بَيْنَهُمْ","antara mereka"],["يَوْمَئِذٍۢ","hari itu"],["وَلَا","dan bukan"],["يَتَسَآءَلُونَ","adakah mereka akan bertanya sesama sendiri"]]],"2775":["(Barang siapa yang berat timbangannya) karena amal-amal kebaikan (maka mereka itulah orang-orang yang mendapat keberuntungan) yakni orang-orang yang beruntung.",[["فَمَن","Kemudian (yang) yang"],["ثَقُلَتْ","(adalah) berat"],["مَوَٰزِينُهُۥ","penimbangnya"],["فَأُو۟لَـٰٓئِكَ","kemudian mereka"],["هُمُ","mereka"],["ٱلْمُفْلِحُونَ","(adalah) orang yang berjaya"]]],"2776":["(Dan barang siapa yang ringan timbangannya) karena dosa-dosanya (maka mereka itulah orang-orang yang merugikan dirinya sendiri) maka mereka (kekal di dalam neraka Jahanam).",[["وَمَنْ","Tetapi (yang) yang"],["خَفَّتْ","(adalah) ringan"],["مَوَٰزِينُهُۥ","penimbangnya"],["فَأُو۟لَـٰٓئِكَ","kemudian mereka"],["ٱلَّذِينَ","mereka [yang]"],["خَسِرُوٓا۟","dah kalah"],["أَنفُسَهُمْ","jiwa mereka"],["فِى","dalam"],["جَهَنَّمَ","Neraka"],["خَـٰلِدُونَ","mereka (akan) kekal selama-lamanya"]]],"2777":["(Muka mereka dibakar api neraka) api neraka membakarnya (dan mereka di dalam neraka itu dalam keadaan cacat) bibir mereka bagian atas dan bawah mengkerut memperlihatkan gigi-gigi mereka, kemudian dikatakan kepada mereka,",[["تَلْفَحُ","Akan terbakar"],["وُجُوهَهُمُ","muka mereka"],["ٱلنَّارُ","neraka"],["وَهُمْ","dan mereka"],["فِيهَا","di dalamnya"],["كَـٰلِحُونَ","(akan) tersengih dengan bibir tersesar"]]],"2778":["(Bukankah ayat-ayat-Ku) dari Alquran (telah dibacakan kepada kamu sekalian) maksudnya kalian telah diperingatkan melaluinya (tetapi kalian selalu mendustakannya?)",[["أَلَمْ","tidak"],["تَكُنْ","tidak"],["ءَايَـٰتِى","Ayat-ayat Aku"],["تُتْلَىٰ","dibacakan"],["عَلَيْكُمْ","kepada kamu"],["فَكُنتُم","dan kamu pernah (untuk)"],["بِهَا","menafikan mereka"],["تُكَذِّبُونَ","menafikan mereka"]]],"2779":["(Mereka berkata, \"Ya Rabb kami! Kami telah dikuasai oleh kejahatan kami) menurut qiraat yang lain dibaca Syaqawatunaa, keduanya merupakan Mashdar dan bermakna sama, yaitu kejahatan kami (dan adalah kami orang-orang yang sesat) dari jalan petunjuk.",[["قَالُوا۟","Mereka (akan) berkata"],["رَبَّنَا","Wahai Tuhan kami"],["غَلَبَتْ","Diatasi"],["عَلَيْنَا","[pada] kami"],["شِقْوَتُنَا","celaka kami"],["وَكُنَّا","dan kami"],["قَوْمًۭا","suatu kaum"],["ضَآلِّينَ","sesat"]]],"2780":["(Ya Rabb kami! Keluarkanlah kami daripadanya maka jika kami kembali) kepada pelanggaran lagi (maka sesungguhnya kami adalah orang-orang yang zalim\").",[["رَبَّنَآ","Wahai Tuhan kami"],["أَخْرِجْنَا","Bawa kami keluar"],["مِنْهَا","daripadanya"],["فَإِنْ","maka jika"],["عُدْنَا","kita balik"],["فَإِنَّا","maka sesungguhnya, kita"],["ظَـٰلِمُونَ","(akan menjadi) orang-orang yang zalim"]]],"2781":["(Allah berfirman) kepada mereka melalui lisan malaikat Malik penjaga neraka, sesudah jangka waktu yang lamanya dua kali lipat umur dunia, (\"Tinggallah dengan hina di dalamnya) makin menjauhlah kalian di dalam neraka dengan hina (dan janganlah kalian berbicara dengan Aku\") untuk meminta supaya azab dihentikan dari diri kalian; dijawab demikian supaya mereka tidak mempunyai harapan lagi untuk dapat diangkat dari dalam neraka.",[["قَالَ","Dia (akan) berkata"],["ٱخْسَـُٔوا۟","Tetap dihina"],["فِيهَا","di dalamnya"],["وَلَا","dan jangan"],["تُكَلِّمُونِ","bercakap kepada-Ku"]]],"2782":["(Sesungguhnya ada segolongan dari hamba-hamba-Ku) mereka adalah kaum Muhajirin (berdoa, \"Ya Rabb kami! Kami telah beriman, maka ampunilah kami dan berilah kami rahmat dan Engkau adalah Pemberi rahmat Yang Paling Baik\").",[["إِنَّهُۥ","Sesungguhnya"],["كَانَ","(ada) ada"],["فَرِيقٌۭ","sebuah parti"],["مِّنْ","daripada"],["عِبَادِى","budak-budak aku"],["يَقُولُونَ","(siapa) berkata"],["رَبَّنَآ","Wahai Tuhan kami"],["ءَامَنَّا","Kami beriman"],["فَٱغْفِرْ","jadi maafkan"],["لَنَا","kami"],["وَٱرْحَمْنَا","dan kasihanilah kami"],["وَأَنتَ","dan kamu"],["خَيْرُ","(adalah) terbaik"],["ٱلرَّٰحِمِينَ","(dari) orang-orang yang mengasihani"]]],"2783":["(Lalu kalian menjadikan mereka buah ejekan) lafal Sikhriyyan dapat pula dibaca Sukhriyyan keduanya merupakan bentuk Mashdar, maknanya adalah ejekan. Di antara mereka yang menjadi bahan ejekan orang-orang musyrik adalah sahabat Bilal, sahabat Shuhaib, sahabat Ammar, sahabat Salman (sehingga menjadikan kalian lupa mengingat Aku) kalian melupakannya disebabkan kalian sibuk dengan memperolok-olokkan mereka. Mengingat mereka sering lupa, maka sifat pelupa dinisbatkan kepada mereka (dan adalah kalian selalu menertawakan mereka).",[["فَٱتَّخَذْتُمُوهُمْ","Tetapi kamu mengambil mereka"],["سِخْرِيًّا","(dalam) ejekan"],["حَتَّىٰٓ","sehingga"],["أَنسَوْكُمْ","mereka membuat kamu lupa"],["ذِكْرِى","zikir aku"],["وَكُنتُم","dan kamu pernah (untuk)"],["مِّنْهُمْ","pada mereka"],["تَضْحَكُونَ","ketawa"]]],"2784":["(Sesungguhnya Aku memberi balasan kepada mereka di hari ini) kenikmatan yang abadi (karena kesabaran mereka) dalam menghadapi ejekan kalian dan perlakuan yang menyakitkan dari kalian terhadap mereka (sesungguhnya mereka) bila dibaca Innahum berarti jumlah Isti'naf, artinya, sesungguhnya mereka. Jika dibaca Annahum berarti menjadi Maf'ul kedua dari lafal Jazaituhum, artinya, bahwasanya mereka (itulah orang-orang yang menang) memperoleh apa yang mereka dambakan.",[["إِنِّى","Sesungguhnya aku"],["جَزَيْتُهُمُ","telah memberi ganjaran kepada mereka"],["ٱلْيَوْمَ","Hari ini"],["بِمَا","kerana"],["صَبَرُوٓا۟","mereka bersabar"],["أَنَّهُمْ","sesungguhnya, mereka"],["هُمُ","[mereka]"],["ٱلْفَآئِزُونَ","(adalah) orang-orang yang berjaya"]]],"2785":["(Berfirmanlah) Allah swt. kepada mereka melalui lisan malaikat Malik. Menurut qiraat yang lain dibaca Qul, yakni katakanlah kepada mereka, (\"Berapa lamakah kalian tinggal di bumi) di dunia dan di dalam kuburan kalian (yakni berapa tahunkah bilangannya?\") lafal 'Adada Siniina berkedudukan menjadi Tamyiz.",[["قَـٰلَ","Dia akan berkata"],["كَمْ","berapa lama"],["لَبِثْتُمْ","adakah kamu kekal"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["عَدَدَ","(dalam) nombor"],["سِنِينَ","(dari) tahun"]]],"2786":["(Mereka menjawab, \"Kami tinggal hanya sehari atau setengah hari) mereka ragu, dan menganggap pendek masa tinggal mereka disebabkan kengerian mereka melihat besarnya azab di hari itu (maka tanyakanlah kepada malaikat-malaikat yang menghitung\") amal perbuatan makhluk.",[["قَالُوا۟","Mereka akan berkata"],["لَبِثْنَا","Kami kekal"],["يَوْمًا","sehari"],["أَوْ","atau"],["بَعْضَ","bahagian"],["يَوْمٍۢ","(dari) sehari"],["فَسْـَٔلِ","tetapi bertanya"],["ٱلْعَآدِّينَ","mereka yang terus mengira"]]],"2787":["(Berfirmanlah) Allah swt. melalui lisan malaikat Malik. Menurut qiraat yang lain lafal Qaala dibaca Qul, artinya katakanlah. (\"Tiada lain) (kalian tinggal hanya sebentar saja, kalau kalian sesungguhnya mengetahui\") lama masa tinggal kalian itu, sedikit sekali jika dibandingkan keabadian kalian di dalam neraka.",[["قَـٰلَ","Dia akan berkata"],["إِن","Tidak"],["لَّبِثْتُمْ","kamu tinggal"],["إِلَّا","tetapi"],["قَلِيلًۭا ۖ","sedikit"],["لَّوْ","jika"],["أَنَّكُمْ","hanya kamu"],["كُنتُمْ","[kamu]"],["تَعْلَمُونَ","tahu"]]],"2788":["(Maka apakah kalian mengira, bahwa sesungguhnya Kami menciptakan kalian secara bermain-main) yakni tidak ada hikmah dan manfaatnya (dan bahwa kalian tidak akan dikembalikan kepada Kami?) kalau dibaca Laa Turja'uuna artinya, kalian tidak dikembalikan. Dan kalau dibaca Tarji'uuna artinya, kalian akan kembali. Tentu saja tidak, sebenarnya supaya kalian menjadi hamba-hamba-Ku untuk Kami perintah dan Kami larang, kemudian kalian kembali kepada Kami untuk menerima pembalasan amal perbuatan kalian. Hal ini sebagaimana yang diungkapkan oleh firman-Nya yang lain, yaitu, \"Dan Aku tidak menciptakan jin dan manusia melainkan supaya mereka menyembah Aku.\" (Q.S. Adz-Dzariyat, 56).",[["أَفَحَسِبْتُمْ","Kemudian adakah kamu berfikir"],["أَنَّمَا","bahawa"],["خَلَقْنَـٰكُمْ","Kami mencipta kamu"],["عَبَثًۭا","tanpa guna"],["وَأَنَّكُمْ","dan bahawa kamu"],["إِلَيْنَا","kepada Kami"],["لَا","tidak"],["تُرْجَعُونَ","akan dikembalikan"]]],"2789":["(Maka Maha Tinggi Allah) dari main-main dan hal-hal lainnya yang tidak layak bagi kebesaran-Nya (Raja Yang Sebenarnya; tidak ada Tuhan selain Dia, Rabb Yang mempunyai Arasy yang mulia) yakni Al-Kursi atau singgasana bagi raja.",[["فَتَعَـٰلَى","Begitu mulia"],["ٱللَّهُ","Allah"],["ٱلْمَلِكُ","sang Raja"],["ٱلْحَقُّ ۖ","Kebenaran"],["لَآ","(Ada) tidak"],["إِلَـٰهَ","tuhan"],["إِلَّا","kecuali"],["هُوَ","Dia"],["رَبُّ","(yang) Tuhan"],["ٱلْعَرْشِ","(dari) Arasy"],["ٱلْكَرِيمِ","Yang Berhormat"]]],"2790":["(Dan barang siapa menyembah tuhan yang lain di samping Allah, padahal tak ada suatu dalil pun baginya tentang itu) lafal Laa Burhaana ini menjadi sifat yang Kasyifah atau yang terbuka, akan tetapi tidak dimengerti, karena pada kenyataannya hal itu mustahil (maka sesungguhnya perhitungannya) yakni pembalasan perbuatannya itu (di sisi Rabbnya. Sesungguhnya orang-orang yang kafir itu tidak beruntung) yakni tidak berbahagia.",[["وَمَن","Dan sesiapa"],["يَدْعُ","menyeru"],["مَعَ","dengan"],["ٱللَّهِ","Allah"],["إِلَـٰهًا","tuhan"],["ءَاخَرَ","lain"],["لَا","tidak"],["بُرْهَـٰنَ","bukti"],["لَهُۥ","baginya"],["بِهِۦ","di dalamnya"],["فَإِنَّمَا","Kemudian sahaja"],["حِسَابُهُۥ","akaunnya"],["عِندَ","(adalah) dengan"],["رَبِّهِۦٓ ۚ","Tuhannya"],["إِنَّهُۥ","Sesungguhnya, [dia]"],["لَا","tidak"],["يُفْلِحُ","akan berjaya"],["ٱلْكَـٰفِرُونَ","orang kafir"]]],"2791":["(Dan katakanlah! \"Ya Rabbku! Berilah ampun dan berilah rahmat) kepada orang-orang Mukmin dalam bentuk rahmat di samping ampunan itu (dan Engkau adalah pemberi rahmat yang paling baik\") artinya Pemberi rahmat yang paling utama.",[["وَقُل","Dan katakan"],["رَّبِّ","Tuhanku"],["ٱغْفِرْ","maafkan"],["وَٱرْحَمْ","dan kasihanilah"],["وَأَنتَ","dan kamu"],["خَيْرُ","(adalah) Terbaik"],["ٱلرَّٰحِمِينَ","(dari) orang-orang yang mengasihani"]]],"2792":["Ini adalah (suatu surah yang Kami turunkan dan Kami wajibkan) dapat dibaca secara Takhfif, yaitu Faradhnaahaa, dapat pula dibaca secara Musyaddad, yaitu Farradhnaahaa. Dikatakan demikian karena banyaknya fardu-fardu atau kewajiban-kewajiban yang terkandung di dalamnya (dan Kami turunkan di dalamnya ayat-ayat yang jelas) yakni jelas dan gamblang maksud-maksudnya (agar kalian selalu mengingatnya) asal kata Tadzakkaruuna ialah Tatadzakkaruuna, kemudian huruf Ta yang kedua diidgamkan kepada huruf Zal, sehingga menjadi Tadzakkaruuna, artinya mengambil pelajaran daripadanya.",[["سُورَةٌ","A Surah"],["أَنزَلْنَـٰهَا","Kami (telah) menurunkannya"],["وَفَرَضْنَـٰهَا","dan Kami (telah) mewajibkannya"],["وَأَنزَلْنَا","dan Kami (telah) mewahyukan"],["فِيهَآ","di dalamnya"],["ءَايَـٰتٍۭ","ayat-ayat"],["بَيِّنَـٰتٍۢ","yang nyata"],["لَّعَلَّكُمْ","supaya kamu"],["تَذَكَّرُونَ","ambil iktibar"]]],"2793":["(Perempuan yang berzina dan laki-laki yang berzina) kedua-duanya bukan muhshan atau orang yang terpelihara dari berzina disebabkan telah kawin. Hadd bagi pelaku zina muhshan adalah rajam, menurut keterangan dari Sunah. Huruf Al yang memasuki kedua lafal ini adalah Al Maushulah sekaligus sebagai Mubtada, mengingat kedudukan Mubtada di sini mirip dengan Syarat, maka Khabarnya kemasukan huruf Fa, sebagaimana yang disebutkan dalam ayat berikutnya, yaitu, (maka deralah tiap-tiap seorang dari keduanya seratus kali dera) yakni sebanyak seratus kali pukulan. Jika dikatakan Jaladahu artinya ia memukul kulit seseorang; makna yang dimaksud adalah mendera. Kemudian ditambahkan hukuman pelaku zina yang bukan muhshan ini menurut keterangan dari Sunah, yaitu harus diasingkan atau dibuang selama satu tahun penuh. Bagi hamba sahaya hanya dikenakan hukuman separuh dari hukuman orang yang merdeka tadi (dan janganlah belas kasihan kalian kepada keduanya mencegah kalian untuk menjalankan agama Allah) yakni hukum-Nya, seumpamanya kalian melalaikan sesuatu dari hudud yang harus diterima keduanya (jika kalian beriman kepada Allah dan hari akhirat) yaitu hari berbangkit. Dalam ungkapan ayat ini terkandung anjuran untuk melakukan pengertian yang terkandung sebelum syarat. Ungkapan sebelum syarat tadi, yaitu kalimat \"Dan janganlah belas kasihan kalian kepada keduanya, mencegah kalian untuk menjalankan hukum Allah\", merupakan Jawab dari Syarat, atau menunjukkan kepada pengertian Jawab Syarat (dan hendaklah hukuman mereka berdua disaksikan) dalam pelaksanaan hukuman deranya (oleh sekumpulan dari orang-orang yang beriman) menurut suatu pendapat para saksi itu cukup tiga orang saja; sedangkan menurut pendapat yang lain, bahwa saksi-saksi itu jumlahnya harus sama dengan para saksi perbuatan zina, yaitu sebanyak empat orang saksi laki-laki.",[["ٱلزَّانِيَةُ","perempuan zina"],["وَٱلزَّانِى","dan orang yang berzina"],["فَٱجْلِدُوا۟","[kemudian] sebat"],["كُلَّ","setiap satu"],["وَٰحِدٍۢ","satu"],["مِّنْهُمَا","daripada mereka"],["مِا۟ئَةَ","(dengan) ratus"],["جَلْدَةٍۢ ۖ","sebatan"],["وَلَا","Dan (jangan)"],["تَأْخُذْكُم","menahan kamu"],["بِهِمَا","kesian kat mereka"],["رَأْفَةٌۭ","kesian kat mereka"],["فِى","tentang"],["دِينِ","(agama) Allah"],["ٱللَّهِ","(agama) Allah"],["إِن","jika"],["كُنتُمْ","kamu"],["تُؤْمِنُونَ","beriman"],["بِٱللَّهِ","kepada Allah"],["وَٱلْيَوْمِ","dan Hari"],["ٱلْـَٔاخِرِ ۖ","yang Terakhir"],["وَلْيَشْهَدْ","Dan biarkan saksi"],["عَذَابَهُمَا","hukuman mereka"],["طَآئِفَةٌۭ","satu kumpulan"],["مِّنَ","daripada"],["ٱلْمُؤْمِنِينَ","orang yang beriman"]]],"2794":["(Laki-laki yang berzina tidak menikahi) (melainkan perempuan yang berzina atau perempuan yang musyrik; dan perempuan yang berzina tidak dikawini melainkan oleh laki-laki yang berzina atau laki-laki yang musyrik) pasangan yang cocok buat masing-masingnya sebagaimana yang telah disebutkan tadi (dan yang demikian itu diharamkan) menikahi perempuan-perempuan yang berzina (atas orang-orang Mukmin) yang terpilih. Ayat ini diturunkan tatkala orang-orang miskin dari kalangan sahabat Muhajirin berniat untuk mengawini para pelacur orang-orang musyrik, karena mereka orang kaya-kaya. Kaum Muhajirin yang miskin menyangka kekayaan yang dimilikinya itu akan dapat menanggung nafkah mereka. Karena itu dikatakan, bahwa pengharaman ini khusus bagi para sahabat Muhajirin yang miskin tadi. Tetapi menurut pendapat yang lain mengatakan pengharaman ini bersifat umum dan menyeluruh, kemudian ayat ini dinasakh oleh firman-Nya yang lain, yaitu, \"Dan nikahkanlah orang-orang yang sendirian di antara kalian...\" (Q.S. An Nur, 32).",[["ٱلزَّانِى","Si penzina"],["لَا","(akan) tidak"],["يَنكِحُ","kahwin"],["إِلَّا","kecuali"],["زَانِيَةً","perempuan zina"],["أَوْ","atau"],["مُشْرِكَةًۭ","seorang wanita musyrik"],["وَٱلزَّانِيَةُ","dan perempuan zina"],["لَا","(akan) tidak"],["يَنكِحُهَآ","kahwin dengan dia"],["إِلَّا","kecuali"],["زَانٍ","seorang penzina"],["أَوْ","atau"],["مُشْرِكٌۭ ۚ","seorang lelaki musyrik"],["وَحُرِّمَ","Dan dilarang"],["ذَٰلِكَ","bahawa"],["عَلَى","kepada"],["ٱلْمُؤْمِنِينَ","orang yang beriman"]]],"2795":["(Dan orang-orang yang menuduh wanita-wanita yang baik-baik) menuduh berzina wanita-wanita yang memelihara dirinya dari perbuatan zina (dan mereka tidak mendatangkan empat orang saksi) yang menyaksikan perbuatan zina mereka dengan mata kepala sendiri (maka deralah mereka) bagi masing-masing dari mereka (delapan puluh kali dera, dan janganlah kalian terima kesaksian mereka) dalam suatu perkara pun (buat selama-lamanya. Dan mereka itulah orang-orang yang fasik) karena mereka telah melakukan dosa besar.",[["وَٱلَّذِينَ","Dan orang yang"],["يَرْمُونَ","menuduh"],["ٱلْمُحْصَنَـٰتِ","wanita yang suci"],["ثُمَّ","kemudian"],["لَمْ","tidak"],["يَأْتُوا۟","mereka bawa"],["بِأَرْبَعَةِ","empat"],["شُهَدَآءَ","saksi"],["فَٱجْلِدُوهُمْ","kemudian sebat mereka"],["ثَمَـٰنِينَ","(dengan) lapan puluh"],["جَلْدَةًۭ","sebatan"],["وَلَا","dan jangan"],["تَقْبَلُوا۟","terima"],["لَهُمْ","mereka"],["شَهَـٰدَةً","kesaksian"],["أَبَدًۭا ۚ","pernah"],["وَأُو۟لَـٰٓئِكَ","Dan mereka"],["هُمُ","mereka"],["ٱلْفَـٰسِقُونَ","(adalah) orang-orang yang durhaka"]]],"2796":["(Kecuali orang-orang yang bertobat sesudah itu dan memperbaiki) amal perbuatan mereka (maka sesungguhnya Allah Maha Pengampun) terhadap dosa tuduhan mereka itu (lagi Maha Penyayang) kepada mereka, yaitu dengan memberikan inspirasi untuk bertobat kepada mereka, yang dengan tobat itu terhapuslah julukan fasik dari diri mereka, kemudian kesaksian mereka dapat diterima kembali. Akan tetapi menurut suatu pendapat bahwa kesaksian mereka tetap tidak dapat diterima. Pendapat ini beranggapan bahwa pengertian Istitsna atau pengecualian di sini hanya kembali kepada kalimat terakhir dari ayat sebelumnya tadi, yaitu, \"Dan mereka itulah orang-orang yang fasik\". Maksudnya hanya status fasik saja yang dihapus dari mereka, sedangkan ketiadagunaan kesaksiannya masih tetap.",[["إِلَّا","Kecuali"],["ٱلَّذِينَ","orang yang"],["تَابُوا۟","bertaubat"],["مِنۢ","selepas"],["بَعْدِ","selepas"],["ذَٰلِكَ","bahawa"],["وَأَصْلَحُوا۟","dan pembaharuan"],["فَإِنَّ","Maka sesungguhnya"],["ٱللَّهَ","Allah"],["غَفُورٌۭ","Maha Pengampun"],["رَّحِيمٌۭ","Maha Mengasihani"]]],"2797":["(Dan orang-orang yang menuduh istrinya) berbuat zina (padahal mereka tidak mempunyai saksi-saksi) atas perbuatan itu (selain diri mereka sendiri) kasus ini telah terjadi pada segolongan para Sahabat (maka persaksian orang itu) lafal ayat ini menjadi Mubtada (ialah empat kali bersumpah) lafal ayat ini dapat dinashabkan karena dianggap sebagai Mashdar (dengan nama Allah, sesungguhnya dia adalah termasuk orang-orang yang benar) dalam tuduhan yang ia lancarkan kepada istrinya itu, yakni tuduhan berbuat zina.",[["وَٱلَّذِينَ","Dan orang yang"],["يَرْمُونَ","menuduh"],["أَزْوَٰجَهُمْ","pasangan mereka"],["وَلَمْ","dan bukan"],["يَكُن","mempunyai"],["لَّهُمْ","bagi mereka"],["شُهَدَآءُ","saksi"],["إِلَّآ","kecuali"],["أَنفُسُهُمْ","diri mereka"],["فَشَهَـٰدَةُ","maka kesaksian itu"],["أَحَدِهِمْ","(dari) salah seorang daripada mereka"],["أَرْبَعُ","(adalah) empat"],["شَهَـٰدَٰتٍۭ","testimoni"],["بِٱللَّهِ ۙ","oleh Allah"],["إِنَّهُۥ","bahawa dia"],["لَمِنَ","(adalah) pasti daripada"],["ٱلصَّـٰدِقِينَ","yang benar"]]],"2798":["(Dan sumpah yang kelima, bahwa laknat Allah atasnya, jika ia termasuk orang-orang yang berdusta) dalam hal ini yang menjadi Khabar dari Mubtada pada ayat yang sebelumnya tadi ialah, Untuk menolak hukuman hudud menuduh berzina yang akan ditimpakan atas dirinya.",[["وَٱلْخَـٰمِسَةُ","Dan yang kelima"],["أَنَّ","bahawa"],["لَعْنَتَ","(laknat) Allah"],["ٱللَّهِ","(laknat) Allah"],["عَلَيْهِ","(berada) atasnya"],["إِن","jika"],["كَانَ","dia adalah"],["مِنَ","daripada"],["ٱلْكَـٰذِبِينَ","pendusta"]]],"2799":["(Istrinya itu dapat dihindarkan) dapat mempertahankan dirinya (dari hukuman) hudud berzina yang telah dikuatkan dengan kesaksian sumpah suaminya yaitu (oleh sumpahnya empat kali atas nama Allah, sesungguhnya suaminya itu benar-benar termasuk orang-orang yang dusta) dalam tuduhan yang ia lancarkan terhadap dirinya, yaitu tuduhan melakukan zina.",[["وَيَدْرَؤُا۟","Tetapi ia akan menghalang"],["عَنْهَا","daripada dia"],["ٱلْعَذَابَ","azab"],["أَن","bahawa"],["تَشْهَدَ","dia bersaksi"],["أَرْبَعَ","empat"],["شَهَـٰدَٰتٍۭ","testimoni"],["بِٱللَّهِ ۙ","oleh Allah"],["إِنَّهُۥ","bahawa dia"],["لَمِنَ","(adalah) pasti daripada"],["ٱلْكَـٰذِبِينَ","pendusta"]]],"2800":["(Dan yang kelima, bahwa laknat Allah atasnya jika suaminya itu termasuk orang-orang yang benar) dalam tuduhannya itu.",[["وَٱلْخَـٰمِسَةَ","Dan yang kelima"],["أَنَّ","bahawa"],["غَضَبَ","kemurkaan Allah"],["ٱللَّهِ","kemurkaan Allah"],["عَلَيْهَآ","(berada) padanya"],["إِن","jika"],["كَانَ","dia adalah"],["مِنَ","daripada"],["ٱلصَّـٰدِقِينَ","yang benar"]]],"2801":["(Dan andaikata tidak ada karunia Allah dan rahmat-Nya atas diri kalian) dengan menutupi hal tersebut (dan andaikata Allah bukan Penerima tobat) maksudnya, Allah menerima tobatnya yang disebabkan tuduhannya itu dan dosa-dosa yang lainnya (lagi Maha Bijaksana) dalam keputusan-Nya mengenai masalah ini dan hal-hal yang lain, niscaya Dia akan menjelaskan mana yang benar dalam masalah ini, dan niscaya pula Dia akan menyegerakan hukuman-Nya kepada orang-orang yang berhak menerimanya.",[["وَلَوْلَا","Dan jika tidak"],["فَضْلُ","(untuk) Rahmat Allah"],["ٱللَّهِ","(untuk) Rahmat Allah"],["عَلَيْكُمْ","ke atas kamu"],["وَرَحْمَتُهُۥ","dan RahmatNya"],["وَأَنَّ","dan bahawa"],["ٱللَّهَ","Allah"],["تَوَّابٌ","(adalah) Sering Kembali (kepada Rahmat)"],["حَكِيمٌ","Maha Bijaksana"]]],"2802":["(Sesungguhnya orang-orang yang membawa berita bohong) kedustaan yang paling buruk yang dilancarkan terhadap Siti Aisyah r.a. Umulmukminin, ia dituduh melakukan zina (adalah dari golongan kalian juga) yakni segolongan dari kaum Mukmin. Siti Aisyah mengatakan, bahwa mereka adalah Hissan bin Tsabit, Abdullah bin Ubay, Misthah dan Hamnah binti Jahsy. (Janganlah kalian kira bahwa berita bohong itu) hai orang-orang Mukmin selain dari mereka yang melancarkan tuduhan itu (buruk bagi kalian, tetapi hal itu mengandung kebaikan bagi kalian) dan Allah akan memberikan pahalanya kepada kalian. Kemudian Allah swt. menampakkan kebersihan Siti Aisyah r.a. Dan orang yang telah menolongnya yaitu Shofwan. Sehubungan dengan peristiwa ini Siti Aisyah r.a. telah menceritakan, sebagai berikut, \"Aku ikut bersama Nabi saw. dalam suatu peperangan, yaitu sesudah diturunkannya ayat mengenai hijab bagi kaum wanita. Setelah Nabi saw. menunaikan tugasnya, lalu ia kembali dan kota Madinah sudah dekat. Pada suatu malam setelah istirahat Nabi saw. menyerukan supaya rombongan melanjutkan perjalanan kembali. Aku pergi dari rombongan untuk membuang hajat besarku. Setelah selesai, aku kembali ke rombongan yang sedang bersiap-siap untuk berangkat, akan tetapi ternyata kalungku putus/jatuh, lalu aku kembali lagi ke tempat buang hajat tadi untuk mencarinya. Mereka mengangkat sekedupku ke atas unta kendaraanku, karena mereka menduga bahwa aku telah berada di dalamnya. Karena kaum wanita pada saat itu beratnya ringan sekali, disebabkan mereka hanya makan sedikit. Aku menemukan kembali kalungku yang hilang itu, lalu aku datang ke tempat rombongan, ternyata mereka telah berlalu. Lalu aku duduk di tempat semula, dengan harapan bahwa rombongan akan merasa kehilangan aku, lalu mereka kembali ke tempatku. Mataku mengantuk sekali, sehingga aku tertidur; sedangkan Shofwan pada waktu itu berada jauh dari rombongan pasukan karena beristirahat sendirian. Kemudian dari tempat istirahatnya itu ia melanjutkan kembali perjalanannya menyusul pasukan. Ketika ia sampai ke tempat pasukan, ia melihat ada seseorang sedang tidur, lalu ia langsung mengenaliku, karena ia pernah melihatku sebelum ayat hijab diturunkan. Aku terbangun ketika dia mengucapkan Istirja', 'yaitu kalimat Innaa Lillaahi Wa Innaa Ilaihi RaaJi'uuna'. Aku segera menutup wajahku dengan kain jilbab. Demi Allah, sepatah kata pun ia tidak berbicara denganku, terkecuali hanya kalimat Istirja'nya sewaktu ia merundukkan hewan hendaraannya kemudian ia turun dengan berpijak kepada kaki depan untanya. Selanjutnya aku menaiki unta kendaraannya dan ia langsung menuntun kendaraannya yang kunaiki, hingga kami dapat menyusul rombongan pasukan, yaitu sesudah mereka beristirahat pada siang hari yang panasnya terik. Akhirnya tersiarlah berita bohong yang keji itu, semoga binasalah mereka yang membuat-buatnya. Sumber pertama yang menyiarkannya adalah Abdullah bin Ubay bin Salul.\" Hanya sampai di sinilah kisah siti Aisyah menurut riwayat yang dikemukakan oleh Imam Bukhari dan Imam Muslim. Selanjutnya Allah berfirman, (\"Tiap-tiap seseorang dari mereka) akan dibalas kepadanya (dari dosa yang dikerjakannya) mengenai berita bohong ini. (Dan siapa di antara mereka yang mengambil bagian yang terbesar dalam penyiaran berita bohong itu) maksudnya orang yang menjadi biang keladi dan berperanan penting dalam penyiaran berita bohong ini, yang dimaksud adalah Abdullah bin Ubay (baginya azab yang besar\") yakni neraka kelak di akhirat",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["جَآءُو","dibawa"],["بِٱلْإِفْكِ","pembohongan itu"],["عُصْبَةٌۭ","(adalah) kumpulan"],["مِّنكُمْ ۚ","antara kamu"],["لَا","Jangan"],["تَحْسَبُوهُ","fikirkanlah"],["شَرًّۭا","teruk"],["لَّكُم ۖ","bagi kamu"],["بَلْ","tidak"],["هُوَ","ia"],["خَيْرٌۭ","(adalah) baik"],["لَّكُمْ ۚ","bagi kamu"],["لِكُلِّ","Untuk setiap"],["ٱمْرِئٍۢ","orang"],["مِّنْهُم","antara mereka"],["مَّا","(ialah) apa"],["ٱكْتَسَبَ","dia perolehi"],["مِنَ","daripada"],["ٱلْإِثْمِ ۚ","dosa itu"],["وَٱلَّذِى","dan orang yang"],["تَوَلَّىٰ","mengambil bahagian yang lebih besar daripadanya"],["كِبْرَهُۥ","mengambil bahagian yang lebih besar daripadanya"],["مِنْهُمْ","antaranya"],["لَهُۥ","baginya"],["عَذَابٌ","(ialah) azab"],["عَظِيمٌۭ","yang besar"]]],"2803":["(Mengapa tidak, sewaktu kalian mendengar berita bohong itu orang-orang Mukmin dan Mukminat berprasangka terhadap diri mereka sendiri) sebagian dari mereka mempunyai prasangka terhadap sebagian yang lain (dengan sangkaan yang baik, dan mengapa tidak berkata, \"Ini adalah suatu berita bohong yang nyata\") dan jelas bohongnya. Di dalam ayat ini terkandung ungkapan Iltifat dari orang-orang yang diajak bicara. Maksudnya, mengapa kalian hai golongan orang-orang yang menuduh, mempunyai dugaan seperti itu dan berani mengatakan hal itu?",[["لَّوْلَآ","kenapa tidak"],["إِذْ","apabila"],["سَمِعْتُمُوهُ","kamu mendengarnya"],["ظَنَّ","fikir"],["ٱلْمُؤْمِنُونَ","lelaki yang beriman"],["وَٱلْمُؤْمِنَـٰتُ","dan wanita yang beriman"],["بِأَنفُسِهِمْ","kebaikan diri mereka"],["خَيْرًۭا","kebaikan diri mereka"],["وَقَالُوا۟","dan katakan"],["هَـٰذَآ","Ini"],["إِفْكٌۭ","(adalah) pembohongan"],["مُّبِينٌۭ","yang nyata"]]],"2804":["(Mengapa tidak) (mendatangkan) golongan yang menuduh itu (empat orang saksi atas berita bohong itu?) maksudnya orang-orang yang menyaksikan peristiwa itu. (Oleh karena mereka tidak mendatangkan saksi-saksi maka mereka itulah pada sisi Allah) menurut hukum-Nya (orang-orang yang dusta) dalam tuduhannya.",[["لَّوْلَا","Mengapa (tidak) tidak"],["جَآءُو","mereka bawa"],["عَلَيْهِ","baginya"],["بِأَرْبَعَةِ","empat"],["شُهَدَآءَ ۚ","saksi"],["فَإِذْ","Kemudian apabila"],["لَمْ","tidak"],["يَأْتُوا۟","mereka bawa"],["بِٱلشُّهَدَآءِ","para saksi"],["فَأُو۟لَـٰٓئِكَ","kemudian mereka"],["عِندَ","dekat Allah"],["ٱللَّهِ","dekat Allah"],["هُمُ","mereka"],["ٱلْكَـٰذِبُونَ","(adalah) orang-orang yang berdusta"]]],"2805":["(Sekiranya tidak ada karunia Allah dan rahmat-Nya kepada kalian semua di dunia dan di akhirat, niscaya kalian ditimpa, karena pembicaraan kalian) hai golongan yang menuduh (tentang berita bohong itu, azab yang besar) di akhirat kelak.",[["وَلَوْلَا","Dan jika tidak"],["فَضْلُ","(untuk) Rahmat"],["ٱللَّهِ","(milik) Allah"],["عَلَيْكُمْ","ke atas kamu"],["وَرَحْمَتُهُۥ","dan RahmatNya"],["فِى","dalam"],["ٱلدُّنْيَا","dunia"],["وَٱلْـَٔاخِرَةِ","dan akhirat"],["لَمَسَّكُمْ","pasti akan menyentuh kamu"],["فِى","dalam"],["مَآ","apa"],["أَفَضْتُمْ","kamu telah tergesa-gesa dengan licik"],["فِيهِ","berkenaan dengannya"],["عَذَابٌ","azab"],["عَظِيمٌ","yang besar"]]],"2806":["(Di waktu kalian menerima berita bohong itu dari mulut ke mulut) yaitu sebagian di antara kalian menceritakannya kepada sebagian yang lain. Lafal Talaqqaunahu berasal dari lafal Tatalaqqaunahu, kemudian salah satu dari huruf Ta dibuang sehingga jadilah Talaqqaunahu. Lafal Idz tadi dinashabkan oleh lafal Massakum atau oleh lafal Afadhtum (dan kalian katakan dengan mulut kalian apa yang tidak kalian ketahui sedikit jua, dan kalian menganggapnya suatu yang ringan saja) sebagai sesuatu hal yang tidak berdosa. (Padahal dia pada sisi Allah adalah besar) dosanya.",[["إِذْ","Apabila"],["تَلَقَّوْنَهُۥ","kamu menerimanya"],["بِأَلْسِنَتِكُمْ","dengan lidah kamu"],["وَتَقُولُونَ","dan kamu berkata"],["بِأَفْوَاهِكُم","dengan mulut kamu"],["مَّا","apa"],["لَيْسَ","tidak"],["لَكُم","bagi kamu"],["بِهِۦ","daripadanya"],["عِلْمٌۭ","sebarang pengetahuan"],["وَتَحْسَبُونَهُۥ","dan kamu fikirkannya"],["هَيِّنًۭا","(adalah) tidak penting"],["وَهُوَ","semasa itu"],["عِندَ","(berada) dekat dengan Allah"],["ٱللَّهِ","(berada) dekat dengan Allah"],["عَظِيمٌۭ","yang besar"]]],"2807":["(Dan mengapa tidak, sewaktu) ketika (kalian mendengar berita bohong itu, kalian tidak mengatakan, \"Sekali-kali tidaklah pantas) maksudnya tidak layak (bagi kita memperkatakan ini. Maha Suci Engkau) lafal Subhaanaka menunjukkan makna Ta'ajjub (ini adalah dusta) bohong (yang besar.\")",[["وَلَوْلَآ","Dan kenapa tidak"],["إِذْ","apabila"],["سَمِعْتُمُوهُ","kamu mendengarnya"],["قُلْتُم","kamu kata"],["مَّا","Tidak"],["يَكُونُ","ia adalah"],["لَنَآ","bagi kami"],["أَن","bahawa"],["نَّتَكَلَّمَ","kita bercakap"],["بِهَـٰذَا","ini"],["سُبْحَـٰنَكَ","Maha Suci Engkau"],["هَـٰذَا","Ini"],["بُهْتَـٰنٌ","(adalah) fitnah"],["عَظِيمٌۭ","yang besar"]]],"2808":["(Allah memperingatkan kalian) yakni melarang kalian (agar jangan kembali memperbuat yang seperti itu selama-lamanya, jika kalian orang-orang yang beriman) yang mau mengambil pelajaran dari hal tersebut.",[["يَعِظُكُمُ","Allah memberi amaran kepada kamu"],["ٱللَّهُ","Allah memberi amaran kepada kamu"],["أَن","bahawa"],["تَعُودُوا۟","kamu balik"],["لِمِثْلِهِۦٓ","(kepada) seperti itu"],["أَبَدًا","pernah"],["إِن","jika"],["كُنتُم","kamu"],["مُّؤْمِنِينَ","orang yang beriman"]]],"2809":["(Dan Allah menerangkan ayat-ayat-Nya kepada kalian) mengenai perintah dan larangan. (Dan Allah Maha Mengetahui) tentang apa yang Dia perintahkan dan apa yang Dia larang (lagi Maha Bijaksana) dalam hal ini.",[["وَيُبَيِّنُ","Dan Allah menerangkan"],["ٱللَّهُ","Dan Allah menerangkan"],["لَكُمُ","kepada kamu"],["ٱلْـَٔايَـٰتِ ۚ","ayat-ayat"],["وَٱللَّهُ","Dan Allah"],["عَلِيمٌ","Maha Mengetahui"],["حَكِيمٌ","Maha Bijaksana"]]],"2810":["(Sesungguhnya orang-orang yang ingin agar berita perbuatan yang amat keji itu tersiar) dengan melalui mulut mereka (di kalangan orang-orang yang beriman) dengan menisbatkan perbuatan keji itu kepada mereka, yang dimaksud adalah segolongan dari kaum Mukmin (bagi mereka azab yang pedih di dunia) mendapat hukuman hudud menuduh berzina (dan di akhirat) oleh Allah dimasukkan ke dalam neraka. (Dan Allah Maha Mengetahui) ketiadaan perbuatan keji itu dari kalangan mereka (sedangkan kalian) hai golongan orang-orang yang melancarkan berita bohong, terhadap apa yang kalian katakan itu (tidak mengetahui) tentang adanya perbuatan keji di kalangan orang-orang yang beriman.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["يُحِبُّونَ","suka"],["أَن","bahawa"],["تَشِيعَ","(harus) merebak"],["ٱلْفَـٰحِشَةُ","maksiat itu"],["فِى","antara"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["لَهُمْ","bagi mereka"],["عَذَابٌ","(ialah) azab"],["أَلِيمٌۭ","yang pedih"],["فِى","dalam"],["ٱلدُّنْيَا","dunia"],["وَٱلْـَٔاخِرَةِ ۚ","dan akhirat"],["وَٱللَّهُ","Dan Allah"],["يَعْلَمُ","mengetahui"],["وَأَنتُمْ","sedangkan kamu"],["لَا","jangan"],["تَعْلَمُونَ","mengetahui"]]],"2811":["(Dan sekiranya tidaklah karena karunia Allah kepada kalian) hai orang-orang yang menuduh (dan rahmat-Nya, dan Allah Maha Penyantun lagi Maha Penyayang) kepada kalian, niscaya Dia akan menyegerakan hukuman-Nya kepada kalian.",[["وَلَوْلَا","Dan jika tidak"],["فَضْلُ","(untuk) rahmat Allah"],["ٱللَّهِ","(untuk) rahmat Allah"],["عَلَيْكُمْ","ke atas kamu"],["وَرَحْمَتُهُۥ","dan RahmatNya"],["وَأَنَّ","Dan bahawa"],["ٱللَّهَ","Allah"],["رَءُوفٌۭ","(adalah) Penuh Kebaikan"],["رَّحِيمٌۭ","Maha Mengasihani"]]],"2812":["(Hai orang-orang yang beriman! Janganlah kalian mengikuti langkah-langkah setan) mengikuti godaan-godaannya. (Barang siapa yang mengikuti langkah-langkah setan, sesungguhnya setan itu) yakni yang diikutinya itu (selalu menyuruh mengerjakan perbuatan yang keji) yakni perbuatan yang buruk (dan yang mungkar) menurut syariat, yaitu jika perbuatan itu diikuti (Sekiranya tidaklah karena karunia Allah dan rahmat-Nya kepada kamu sekalian, niscaya tidak seorang pun dari kalian bersih) hai orang-orang yang menuduh, disebabkan berita bohong yang kalian katakan itu (selama-lamanya) tidak akan menjadi baik dan tidak akan menjadi bersih dari dosa ini hanya dengan bertobat daripadanya (tetapi Allah membersihkan) menyucikan (siapa yang dikehendaki-Nya) dari dosa, yaitu dengan menerima tobatnya. (Dan Allah Maha Mendengar) tentang apa yang telah kalian katakan (lagi Maha Mengetahui) tentang apa yang kalian maksud.",[["۞ يَـٰٓأَيُّهَا","Wahai orang yang beriman"],["ٱلَّذِينَ","Wahai orang yang beriman"],["ءَامَنُوا۟","Wahai orang yang beriman"],["لَا","Jangan"],["تَتَّبِعُوا۟","ikut"],["خُطُوَٰتِ","(the) jejak kaki"],["ٱلشَّيْطَـٰنِ ۚ","(dari) syaitan"],["وَمَن","dan sesiapa"],["يَتَّبِعْ","mengikuti"],["خُطُوَٰتِ","(the) jejak kaki"],["ٱلشَّيْطَـٰنِ","(dari) syaitan"],["فَإِنَّهُۥ","maka sesungguhnya, dia"],["يَأْمُرُ","arahan"],["بِٱلْفَحْشَآءِ","maksiat itu"],["وَٱلْمُنكَرِ ۚ","dan kejahatan"],["وَلَوْلَا","Dan jika tidak"],["فَضْلُ","(untuk) rahmat Allah"],["ٱللَّهِ","(untuk) rahmat Allah"],["عَلَيْكُمْ","ke atas kamu"],["وَرَحْمَتُهُۥ","dan RahmatNya"],["مَا","tidak"],["زَكَىٰ","(akan) suci"],["مِنكُم","antara kamu"],["مِّنْ","sesiapa sahaja"],["أَحَدٍ","sesiapa sahaja"],["أَبَدًۭا","pernah"],["وَلَـٰكِنَّ","tetapi"],["ٱللَّهَ","Allah"],["يُزَكِّى","menyucikan"],["مَن","yang"],["يَشَآءُ ۗ","Dia kehendaki"],["وَٱللَّهُ","Dan Allah"],["سَمِيعٌ","(adalah) Yang Maha Mendengar"],["عَلِيمٌۭ","Maha Mengetahui"]]],"2813":["(Dan janganlah bersumpah orang-orang yang mempunyai kelebihan) yaitu orang-orang kaya (dan kelapangan di antara kalian, bahwa mereka) tidak (akan memberi bantuan kepada kaum kerabatnya, orang-orang yang miskin dan orang-orang yang berhijrah pada jalan Allah) ayat ini diturunkan berkenaan dengan sahabat Abu Bakar r. a, ia bersumpah tidak akan memberikan nafkah lagi kepada Misthah saudara sepupunya yang miskin lagi seorang Muhajir, padahal Misthah adalah sahabat yang ikut dalam perang Badar. Misthah terlibat dalam peristiwa berita bohong ini; maka sahabat Abu Bakar menghentikan nafkah yang biasa ia berikan kepadanya. Para sahabat lainnya telah bersumpah pula, bahwa mereka juga tidak akan memberikan nafkah lagi kepada seorang yang terlibat membicarakan masalah berita bohong tersebut (dan hendaklah mereka memaafkan dan berlapang dada) terhadap mereka yang terlibat, dengan mengembalikan keadaan seperti semula. (Apakah kalian tidak ingin bahwa Allah mengampuni kalian? Dan Allah adalah Maha Pengampun lagi Maha Penyayang) terhadap orang-orang yang beriman. Sahabat Abu Bakar r.a. berkata sesudah turunnya ayat ini, \"Tentu saja, aku menginginkan supaya Allah mengampuni aku\", lalu ia memberikan lagi bantuannya kepada Misthah sebagaimana biasanya.",[["وَلَا","Dan tidak"],["يَأْتَلِ","biar bersumpah"],["أُو۟لُوا۟","mereka yang berbudi"],["ٱلْفَضْلِ","mereka yang berbudi"],["مِنكُمْ","antara kamu"],["وَٱلسَّعَةِ","dan amplitud cara"],["أَن","bahawa"],["يُؤْتُوٓا۟","mereka memberi"],["أُو۟لِى","(kepada) kaum kerabat terdekat"],["ٱلْقُرْبَىٰ","(kepada) kaum kerabat terdekat"],["وَٱلْمَسَـٰكِينَ","dan yang memerlukan"],["وَٱلْمُهَـٰجِرِينَ","dan para pendatang"],["فِى","dalam"],["سَبِيلِ","jalan"],["ٱللَّهِ ۖ","(milik) Allah"],["وَلْيَعْفُوا۟","Dan biarkan mereka memaafkan"],["وَلْيَصْفَحُوٓا۟ ۗ","dan biarkan mereka terlepas pandang"],["أَلَا","Jangan"],["تُحِبُّونَ","kamu suka"],["أَن","bahawa"],["يَغْفِرَ","Allah harus mengampuni"],["ٱللَّهُ","Allah harus mengampuni"],["لَكُمْ ۗ","kamu"],["وَٱللَّهُ","Dan Allah"],["غَفُورٌۭ","Maha Pengampun"],["رَّحِيمٌ","Maha Mengasihani"]]],"2814":["(Sesungguhnya orang-orang yang menuduh) berzina (wanita-wanita yang baik-baik) terpelihara kehormatannya (yang lengah) dari perbuatan-perbuatan keji, seumpamanya dalam hati mereka tidak sedikit pun terbetik niat untuk melakukannya (lagi beriman) kepada Allah dan Rasul-Nya (mereka kena laknat di dunia dan akhirat, dan bagi mereka azab yang besar).",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["يَرْمُونَ","menuduh"],["ٱلْمُحْصَنَـٰتِ","wanita yang suci"],["ٱلْغَـٰفِلَـٰتِ","wanita yang tidak sedar"],["ٱلْمُؤْمِنَـٰتِ","(dan) wanita yang beriman"],["لُعِنُوا۟","dikutuk"],["فِى","dalam"],["ٱلدُّنْيَا","dunia"],["وَٱلْـَٔاخِرَةِ","dan akhirat"],["وَلَهُمْ","Dan untuk mereka"],["عَذَابٌ","(ialah) azab"],["عَظِيمٌۭ","yang besar"]]],"2815":["(Pada hari) yauma dinashabkan oleh lafal Istaqarra yang berta'alluq kepadanya, maksudnya pada hari yang telah ditetapkan bagi mereka (memberi kesaksian) dapat dibaca Tasyhadu dan Yasyhadu (lidah, tangan dan kaki mereka atas mereka terhadap apa yang dahulu mereka kerjakan) berupa perbuatan dan perkataan yang telah mereka kerjakan, yaitu pada hari kiamat.",[["يَوْمَ","(Pada a) Hari"],["تَشْهَدُ","akan menjadi saksi"],["عَلَيْهِمْ","terhadap mereka"],["أَلْسِنَتُهُمْ","lidah mereka"],["وَأَيْدِيهِمْ","dan tangan mereka"],["وَأَرْجُلُهُم","dan kaki mereka"],["بِمَا","bagi apa"],["كَانُوا۟","mereka gunakan"],["يَعْمَلُونَ","(untuk) melakukan"]]],"2816":["(Di hari itu, Allah akan memberi mereka balasan yang setimpal) Dia akan membalas mereka dengan pembalasan yang semestinya mereka terima (dan tahulah mereka bahwa Allahlah Yang Benar lagi Yang menjelaskan) karena Dia benar-benar membuktikan pembalasan-Nya yang selama ini mereka ragukan kebenarannya; di antara mereka yang mendapat pembalasan adalah Abdullah bin Ubay bin Salul. Yang dimaksud dengan wanita-wanita yang terpelihara kehormatannya adalah istri-istri Nabi saw. Adapun mengenai wanita-wanita yang disebutkan Qadzafnya dalam awal surah At-Taubah, yang dimaksud adalah wanita-wanita selain istri-istri Nabi.",[["يَوْمَئِذٍۢ","Hari itu"],["يُوَفِّيهِمُ","Allah akan membayar mereka sepenuhnya"],["ٱللَّهُ","Allah akan membayar mereka sepenuhnya"],["دِينَهُمُ","balasan mereka"],["ٱلْحَقَّ","yang sepatutnya"],["وَيَعْلَمُونَ","dan mereka akan tahu"],["أَنَّ","bahawa"],["ٱللَّهَ","Allah"],["هُوَ","Dia"],["ٱلْحَقُّ","(adalah) Kebenaran"],["ٱلْمُبِينُ","Manifest"]]],"2817":["(Wanita-wanita yang keji) baik perbuatannya maupun perkataannya (adalah untuk laki-laki yang keji) pula (dan laki-laki yang keji) di antara manusia (adalah buat wanita-wanita yang keji pula) sebagaimana yang sebelumnya tadi (dan wanita-wanita yang baik) baik perbuatan maupun perkataannya (adalah untuk laki-laki yang baik) di antara manusia (dan laki-laki yang baik) di antara mereka (adalah untuk wanita-wanita yang baik pula) baik perbuatan maupun perkataannya. Maksudnya, hal yang layak adalah orang yang keji berpasangan dengan orang yang keji, dan orang baik berpasangan dengan orang yang baik. (Mereka itu) yaitu kaum laki-laki yang baik dan kaum wanita yang baik, antara lain ialah Siti Aisyah dan Sofwan (bersih dari apa yang dituduhkan oleh mereka) yang keji dari kalangan kaum laki-laki dan wanita. (Bagi mereka) yakni laki-laki yang baik dan wanita yang baik itu (ampunan dan rezeki yang mulia) di surga. Siti Aisyah merasa puas dan bangga dengan beberapa hal yang ia peroleh, antara lain, ia diciptakan dalam keadaan baik, dan dijanjikan mendapat ampunan dari Allah, serta diberi rezeki yang mulia.",[["ٱلْخَبِيثَـٰتُ","Perempuan jahat"],["لِلْخَبِيثِينَ","(adalah) untuk orang-orang yang jahat"],["وَٱلْخَبِيثُونَ","dan orang jahat"],["لِلْخَبِيثَـٰتِ ۖ","(adalah) untuk perempuan-perempuan yang jahat"],["وَٱلطَّيِّبَـٰتُ","Dan wanita yang baik"],["لِلطَّيِّبِينَ","(adalah) untuk lelaki yang baik"],["وَٱلطَّيِّبُونَ","dan lelaki yang baik"],["لِلطَّيِّبَـٰتِ ۚ","(adalah) untuk wanita yang baik"],["أُو۟لَـٰٓئِكَ","Mereka itu"],["مُبَرَّءُونَ","(adalah) tidak bersalah"],["مِمَّا","tentang apa"],["يَقُولُونَ ۖ","mereka berkata"],["لَهُم","Untuk mereka"],["مَّغْفِرَةٌۭ","(ialah) pengampunan"],["وَرِزْقٌۭ","dan rezeki"],["كَرِيمٌۭ","mulia"]]],"2818":["(Hai orang-orang yang beriman! Janganlah kalian memasuki rumah yang bukan rumah kalian sebelum meminta izin) maksudnya sebelum kalian meminta izin kepada empunya (dan memberi salam kepada penghuninya). Seseorang jika mau memasuki rumah orang lain hendaknya ia mengucapkan, \"Assalaamu Alaikum, bolehkah aku masuk?\" demikianlah menurut tuntunan hadis. (Yang demikian itu lebih baik bagi kalian) daripada masuk tanpa izin (agar kalian selalu ingat) lafal Tadzakkaruuna dengan mengidgamkan huruf Ta kedua kepada huruf Dzal; maksudnya supaya kalian mengerti akan kebaikan meminta izin itu, kemudian kalian mengerjakannya.",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","yang"],["ءَامَنُوا۟","beriman"],["لَا","Jangan"],["تَدْخُلُوا۟","masuk"],["بُيُوتًا","rumah-rumah"],["غَيْرَ","selain daripada"],["بُيُوتِكُمْ","rumah-rumah kamu"],["حَتَّىٰ","sehingga"],["تَسْتَأْنِسُوا۟","kamu telah meminta izin"],["وَتُسَلِّمُوا۟","dan kamu telah memberi salam"],["عَلَىٰٓ","[pada]"],["أَهْلِهَا ۚ","penduduknya"],["ذَٰلِكُمْ","Itu"],["خَيْرٌۭ","(adalah) terbaik"],["لَّكُمْ","bagi kamu"],["لَعَلَّكُمْ","supaya kamu"],["تَذَكَّرُونَ","ambil iktibar"]]],"2819":["(Jika kalian tidak menemukan seorang pun di dalamnya) maksudnya orang yang mengizinkan kalian masuk (maka janganlah kalian masuk sebelum kalian mendapat izin. Dan jika dikatakan kepada kalian) sesudah kalian meminta izin (\"Kembalilah\" maka hendaklah kalian kembali. Itu) yakni kembali itu (lebih bersih) dan lebih baik (bagi kalian) daripada berdiam menunggu di pintu (dan Allah terhadap apa yang kalian kerjakan) yakni mengenai memasuki rumah orang lain dengan memakai izin atau tidak (Maha Mengetahui) Dia kelak akan membalasnya kepada kalian.",[["فَإِن","Tetapi jika"],["لَّمْ","tidak"],["تَجِدُوا۟","kamu dapati"],["فِيهَآ","di dalamnya"],["أَحَدًۭا","sesiapa sahaja"],["فَلَا","maka (buat) jangan"],["تَدْخُلُوهَا","masukkannya"],["حَتَّىٰ","sehingga"],["يُؤْذَنَ","kebenaran telah diberikan"],["لَكُمْ ۖ","kepada kamu"],["وَإِن","Dan jika"],["قِيلَ","dikatakan"],["لَكُمُ","kepada kamu"],["ٱرْجِعُوا۟","pergi balik"],["فَٱرْجِعُوا۟ ۖ","lepas tu balik"],["هُوَ","ia"],["أَزْكَىٰ","(adalah) lebih tulen"],["لَكُمْ ۚ","bagi kamu"],["وَٱللَّهُ","Dan Allah"],["بِمَا","tentang apa"],["تَعْمَلُونَ","kamu lakukan"],["عَلِيمٌۭ","Maha Mengetahui"]]],"2820":["(Tidak ada dosa atas kalian memasuki rumah yang tidak disediakan untuk didiami, yang di dalamnya ada keperluan) maksudnya, ada manfaat (bagi kalian) misalnya dijadikannya sebagai tempat tinggal sementara atau untuk keperluan yang lainnya, seperti rumah-rumah asrama dan lain sebagainya (dan Allah mengetahui apa yang kalian nyatakan) yakni semua apa yang kalian lahirkan (dan apa yang kalian sembunyikan) artinya yang kalian rahasiakan sewaktu kalian masuk ke dalam rumah yang bukan rumah kalian, termasuk maksud baik atau maksud-maksud lainnya. Pada pembahasan yang akan datang akan diceritakan, bahwa mereka para sahabat, jika mereka memasuki rumah mereka sendiri, mereka mengucapkan salam kepada diri mereka sendiri.",[["لَّيْسَ","Tidak"],["عَلَيْكُمْ","ke atas kamu"],["جُنَاحٌ","(adalah) sebarang kesalahan"],["أَن","bahawa"],["تَدْخُلُوا۟","kamu masuk"],["بُيُوتًا","rumah-rumah"],["غَيْرَ","tidak"],["مَسْكُونَةٍۢ","didiami"],["فِيهَا","di dalamnya"],["مَتَـٰعٌۭ","(adalah) rezeki"],["لَّكُمْ ۚ","bagi kamu"],["وَٱللَّهُ","Dan Allah"],["يَعْلَمُ","mengetahui"],["مَا","apa"],["تُبْدُونَ","kamu dedahkan"],["وَمَا","dan apa"],["تَكْتُمُونَ","kamu sembunyikan"]]],"2821":["(Katakanlah kepada orang laki-laki yang beriman, \"Hendaklah mereka menahan pandangannya) dari apa-apa yang tidak dihalalkan bagi mereka melihatnya. Huruf Min di sini adalah Zaidah (dan memelihara kemaluannya) daripada hal-hal yang tidak dihalalkan untuknya (yang demikian itu adalah lebih suci) adalah lebih baik (bagi mereka, sesungguhnya Allah Maha Mengetahui apa yang mereka perbuat\") melalui penglihatan dan kemaluan mereka, kelak Dia akan membalasnya kepada mereka.",[["قُل","Katakanlah"],["لِّلْمُؤْمِنِينَ","kepada lelaki yang beriman"],["يَغُضُّوا۟","mereka harus lebih rendah"],["مِنْ","pandangan mereka"],["أَبْصَـٰرِهِمْ","pandangan mereka"],["وَيَحْفَظُوا۟","dan mereka harus berjaga-jaga"],["فُرُوجَهُمْ ۚ","kesucian mereka"],["ذَٰلِكَ","Itu"],["أَزْكَىٰ","(adalah) lebih tulen"],["لَهُمْ ۗ","bagi mereka"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["خَبِيرٌۢ","(adalah) Maha Mengetahui"],["بِمَا","tentang apa"],["يَصْنَعُونَ","mereka lakukan"]]],"2822":["(Dan katakanlah kepada wanita yang beriman, \"Hendaklah mereka menahan pandangannya) daripada hal-hal yang tidak dihalalkan bagi mereka melihatnya (dan memelihara kemaluannya) dari hal-hal yang tidak dihalalkan untuknya (dan janganlah mereka menampakkan) memperlihatkan (perhiasannya, kecuali yang biasa tampak daripadanya) yaitu wajah dan dua telapak tangannya, maka kedua perhiasannya itu boleh dilihat oleh lelaki lain, jika tidak dikhawatirkan adanya fitnah. Demikianlah menurut pendapat yang membolehkannya. Akan tetapi menurut pendapat yang lain hal itu diharamkan secara mutlak, sebab merupakan sumber terjadinya fitnah. Pendapat yang kedua ini lebih kuat demi untuk menutup pintu fitnah. (Dan hendaklah mereka menutupkan kain kerudung ke dadanya) hendaknya mereka menutupi kepala, leher dan dada mereka dengan kerudung atau jilbabnya (dan janganlah menampakkan perhiasannya) perhiasan yang tersembunyi, yaitu selain dari wajah dan dua telapak tangan (kecuali kepada suami mereka) bentuk jamak dari lafal Ba'lun artinya suami (atau ayah mereka, atau ayah suami mereka, atau putra-putra mereka, atau putra-putra suami mereka, atau saudara-saudara mereka, atau putra-putra saudara-saudara mereka, atau putra-putra saudara-saudara perempuan mereka, atau wanita-wanita Islam atau budak-budak yang mereka miliki) diperbolehkan bagi mereka melihatnya kecuali anggota tubuh antara pusar dan lututnya, anggota tersebut haram untuk dilihat oleh mereka selain dari suaminya sendiri. Dikecualikan dari lafal Nisaaihinna, yaitu perempuan-perempuan yang kafir, bagi wanita Muslimat tidak boleh membuka aurat di hadapan mereka. Termasuk pula ke dalam pengertian Maa Malakat Aymaanuhunna, yaitu hamba sahaya laki-laki miliknya (atau pelayan-pelayan laki-laki) yakni pembantu-pembantu laki-laki (yang tidak) kalau dibaca Ghairi berarti menjadi sifat dan kalau dibaca Ghaira berarti menjadi Istitsna (mempunyai keinginan) terhadap wanita (dari kalangan kaum laki-laki) seumpamanya penis masing-masing tidak dapat bereaksi (atau anak-anak) lafal Ath-Thifl bermakna jamak sekalipun bentuk lafalnya tunggal (yang masih belum mengerti) belum memahami (tentang aurat wanita) belum mengerti persetubuhan, maka kaum wanita boleh menampakkan aurat mereka terhadap orang-orang tersebut selain antara pusar dan lututnya. (Dan janganlah mereka memukulkan kaki mereka agar diketahui perhiasan yang mereka sembunyikan) yaitu berupa gelang kaki, sehingga menimbulkan suara gemerincing. (Dan bertobatlah kamu sekalian kepada Allah, hai orang-orang yang beriman) dari apa yang telah kalian kerjakan, yaitu sehubungan dengan pandangan yang dilarang ini dan hal-hal lainnya yang dilarang (supaya kalian beruntung\") maksudnya selamat dari hal tersebut karena tobat kalian diterima. Pada ayat ini ungkapan Mudzakkar mendominasi atas Muannats.",[["وَقُل","Dan katakan"],["لِّلْمُؤْمِنَـٰتِ","kepada wanita yang beriman"],["يَغْضُضْنَ","(bahawa) mereka harus menurunkan"],["مِنْ","[daripada]"],["أَبْصَـٰرِهِنَّ","pandangan mereka"],["وَيَحْفَظْنَ","dan mereka harus berjaga-jaga"],["فُرُوجَهُنَّ","kesucian mereka"],["وَلَا","dan bukan"],["يُبْدِينَ","(untuk) memaparkan"],["زِينَتَهُنَّ","perhiasan mereka"],["إِلَّا","kecuali"],["مَا","apa"],["ظَهَرَ","adalah jelas"],["مِنْهَا ۖ","daripadanya"],["وَلْيَضْرِبْنَ","Dan biarkan mereka melukis"],["بِخُمُرِهِنَّ","penutup kepala mereka"],["عَلَىٰ","atas"],["جُيُوبِهِنَّ ۖ","dada mereka"],["وَلَا","dan bukan"],["يُبْدِينَ","(untuk) memaparkan"],["زِينَتَهُنَّ","perhiasan mereka"],["إِلَّا","kecuali"],["لِبُعُولَتِهِنَّ","kepada suami mereka"],["أَوْ","atau"],["ءَابَآئِهِنَّ","bapa mereka"],["أَوْ","atau"],["ءَابَآءِ","bapa-bapa"],["بُعُولَتِهِنَّ","(dari) suami mereka"],["أَوْ","atau"],["أَبْنَآئِهِنَّ","anak lelaki mereka"],["أَوْ","atau"],["أَبْنَآءِ","anak lelaki"],["بُعُولَتِهِنَّ","(dari) suami mereka"],["أَوْ","atau"],["إِخْوَٰنِهِنَّ","saudara mereka"],["أَوْ","atau"],["بَنِىٓ","anak lelaki"],["إِخْوَٰنِهِنَّ","(dari) saudara-saudara mereka"],["أَوْ","atau"],["بَنِىٓ","anak lelaki"],["أَخَوَٰتِهِنَّ","(dari) saudara perempuan mereka"],["أَوْ","atau"],["نِسَآئِهِنَّ","wanita mereka"],["أَوْ","atau"],["مَا","apa"],["مَلَكَتْ","memiliki"],["أَيْمَـٰنُهُنَّ","tangan kanan mereka"],["أَوِ","atau"],["ٱلتَّـٰبِعِينَ","para atendan"],["غَيْرِ","tidak mempunyai keinginan fizikal"],["أُو۟لِى","tidak mempunyai keinginan fizikal"],["ٱلْإِرْبَةِ","tidak mempunyai keinginan fizikal"],["مِنَ","antara"],["ٱلرِّجَالِ","[the] lelaki"],["أَوِ","atau"],["ٱلطِّفْلِ","[anak-anak]"],["ٱلَّذِينَ","yang"],["لَمْ","(adalah) tidak"],["يَظْهَرُوا۟","sedar"],["عَلَىٰ","daripada"],["عَوْرَٰتِ","aspek peribadi"],["ٱلنِّسَآءِ ۖ","(dari) wanita"],["وَلَا","Dan tidak"],["يَضْرِبْنَ","biar mereka cop"],["بِأَرْجُلِهِنَّ","kaki mereka"],["لِيُعْلَمَ","untuk diketahui"],["مَا","apa"],["يُخْفِينَ","mereka sembunyikan"],["مِن","daripada"],["زِينَتِهِنَّ ۚ","perhiasan mereka"],["وَتُوبُوٓا۟","Dan berpaling"],["إِلَى","kepada"],["ٱللَّهِ","Allah"],["جَمِيعًا","sama sekali"],["أَيُّهَ","Wahai orang yang beriman"],["ٱلْمُؤْمِنُونَ","Wahai orang yang beriman"],["لَعَلَّكُمْ","Supaya kamu boleh"],["تُفْلِحُونَ","berjaya"]]],"2823":["(Dan kawinkanlah orang-orang yang sendirian di antara kalian) lafal Ayaama adalah bentuk jamak dari lafal Ayyimun artinya wanita yang tidak mempunyai suami, baik perawan atau janda, dan laki-laki yang tidak mempunyai istri; hal ini berlaku untuk laki-laki dan perempuan yang merdeka (dan orang-orang yang layak kawin) yakni yang Mukmin (dari hamba-hamba sahaya kalian yang lelaki dan hamba-hamba sahaya kalian yang perempuan) lafal 'ibaadun adalah bentuk jamak dari lafal 'Abdun. (Jika mereka) yakni orang-orang yang merdeka itu (miskin Allah akan memampukan mereka) berkat adanya perkawinan itu (dengan karunia-Nya. Dan Allah Maha Luas) pemberian-Nya kepada makhluk-Nya (lagi Maha Mengetahui) mereka.",[["وَأَنكِحُوا۟","Dan berkahwin"],["ٱلْأَيَـٰمَىٰ","yang bujang"],["مِنكُمْ","antara kamu"],["وَٱلصَّـٰلِحِينَ","dan orang yang soleh"],["مِنْ","antara"],["عِبَادِكُمْ","hamba lelaki kamu"],["وَإِمَآئِكُمْ ۚ","dan hamba-hamba perempuan kamu"],["إِن","Jika"],["يَكُونُوا۟","mereka adalah"],["فُقَرَآءَ","miskin"],["يُغْنِهِمُ","Allah akan memperkayakan mereka"],["ٱللَّهُ","Allah akan memperkayakan mereka"],["مِن","daripada"],["فَضْلِهِۦ ۗ","Bounty-Nya"],["وَٱللَّهُ","Dan Allah"],["وَٰسِعٌ","(adalah) Merangkumi"],["عَلِيمٌۭ","Maha Mengetahui"]]],"2824":["(Dan orang-orang yang tidak mampu kawin hendaklah menjaga kesuciannya) maksudnya mereka yang tidak mempunyai mahar dan nafkah untuk kawin, hendaklah mereka memelihara kesuciannya dari perbuatan zina (sehingga Allah memampukan mereka) memberikan kemudahan kepada mereka (dengan karunia-Nya) hingga mereka mampu kawin. (Dan orang-orang yang menginginkan perjanjian) lafal Al Kitaaba bermakna Al Mukaatabah, yaitu perjanjian untuk memerdekakan diri (di antara budak-budak yang kalian miliki) baik hamba sahaya laki-laki maupun perempuan (maka hendaklah kalian buat perjanjian dengan mereka jika kalian mengetahui ada kebaikan pada mereka) artinya dapat dipercaya dan memiliki kemampuan untuk berusaha yang hasilnya kelak dapat membayar perjanjian kemerdekaan dirinya. Shighat atau teks perjanjian ini, misalnya seorang pemilik budak berkata kepada budaknya, \"Aku memukatabahkan kamu dengan imbalan dua ribu dirham, selama jangka waktu dua bulan. Jika kamu mampu membayarnya, berarti kamu menjadi orang yang merdeka.\" Kemudian budak yang bersangkutan menjawab, \"Saya menyanggupi dan mau menerimanya\" (dan berikanlah kepada mereka) perintah di sini ditujukan kepada para pemilik budak (sebagian dari harta Allah yang dikaruniakan-Nya kepada kalian) berupa apa-apa yang dapat membantu mereka untuk menunaikan apa yang mereka harus bayarkan kepada kalian. Di dalam lafal Al-Iitaa terkandung pengertian meringankan sebagian dari apa yang harus mereka bayarkan kepada kalian, yaitu dengan menganggapnya lunas. (Dan janganlah kalian paksakan budak-budak wanita kalian) yaitu sahaya wanita milik kalian (untuk melakukan pelacuran) berbuat zina (sedangkan mereka sendiri menginginkan kesucian) memelihara kehormatannya dari perbuatan zina. Adanya keinginan untuk memelihara kehormatan inilah yang menyebabkan dilarang memaksa, sedangkan syarath di sini tidak berfungsi sebagaimana mestinya lagi (karena kalian hendak mencari) melalui paksaan itu (keuntungan duniawi) ayat ini diturunkan berkenaan dengan Abdullah bin Ubay, karena dia memaksakan hamba-hamba sahaya perempuannya untuk berpraktek sebagai pelacur demi mencari keuntungan bagi dirinya. (Dan barang siapa memaksa mereka, maka sesungguhnya Allah kepada mereka yang telah dipaksa itu adalah Maha Pengampun) (lagi Maha Penyayang).",[["وَلْيَسْتَعْفِفِ","Dan biarlah suci"],["ٱلَّذِينَ","orang yang"],["لَا","jangan"],["يَجِدُونَ","cari"],["نِكَاحًا","(bermaksud untuk) perkahwinan"],["حَتَّىٰ","sehingga"],["يُغْنِيَهُمُ","Allah mengkayakan mereka"],["ٱللَّهُ","Allah mengkayakan mereka"],["مِن","daripada"],["فَضْلِهِۦ ۗ","Bounty-Nya"],["وَٱلَّذِينَ","Dan orang yang"],["يَبْتَغُونَ","mencari"],["ٱلْكِتَـٰبَ","tulisan itu"],["مِمَّا","daripada (mereka) yang"],["مَلَكَتْ","memiliki"],["أَيْمَـٰنُكُمْ","tangan kanan kamu"],["فَكَاتِبُوهُمْ","maka berikanlah kepada mereka tulisan itu"],["إِنْ","jika"],["عَلِمْتُمْ","kamu tahu"],["فِيهِمْ","dalam diri mereka"],["خَيْرًۭا ۖ","apa-apa kebaikan"],["وَءَاتُوهُم","dan berikan mereka"],["مِّن","daripada"],["مَّالِ","kekayaan Allah"],["ٱللَّهِ","kekayaan Allah"],["ٱلَّذِىٓ","yang"],["ءَاتَىٰكُمْ ۚ","Dia telah memberi kamu"],["وَلَا","Dan jangan"],["تُكْرِهُوا۟","memaksa"],["فَتَيَـٰتِكُمْ","budak perempuan kamu"],["عَلَى","kepada"],["ٱلْبِغَآءِ","pelacuran"],["إِنْ","jika"],["أَرَدْنَ","mereka inginkan"],["تَحَصُّنًۭا","kesucian"],["لِّتَبْتَغُوا۟","yang boleh kamu cari"],["عَرَضَ","keuntungan sementara"],["ٱلْحَيَوٰةِ","(dari) kehidupan"],["ٱلدُّنْيَا ۚ","dunia"],["وَمَن","Dan sesiapa"],["يُكْرِههُّنَّ","memaksa mereka"],["فَإِنَّ","maka sesungguhnya"],["ٱللَّهَ","Allah"],["مِنۢ","selepas"],["بَعْدِ","selepas"],["إِكْرَٰهِهِنَّ","paksaan mereka"],["غَفُورٌۭ","Maha Pengampun"],["رَّحِيمٌۭ","Maha Mengasihani"]]],"2825":["(Dan sesungguhnya Kami telah menurunkan kepada kalian ayat-ayat yang memberi penerangan) dapat dibaca Mubayyanatin dan Mubayyinatin. Artinya, telah dijelaskan di dalamnya hal-hal yang telah disebutkan tadi (dan contoh-contoh) yakni berita yang aneh, yaitu berita tentang Siti Aisyah (dari orang-orang yang terdahulu sebelum kalian) maksudnya sama jenisnya dengan berita-berita mereka dalam hal keanehannya, seperti kisah mengenai Nabi Yusuf dan Siti Maryam (dan pelajaran bagi orang-orang yang bertakwa) yaitu dalam firman-Nya, \"Dan janganlah belas kasihan kalian kepada keduanya mencegah kalian untuk menjalankan agama (hukum) Allah.\" (Q.S. An-Nur, 2) dan firman-Nya, \"Mengapa di waktu kalian mendengar berita bohong itu orang-orang Mukmin dan Mukminat tidak berprasangka baik\". (Q.S. An-Nur, 12). Dan firman-Nya, \"Dan mengapa kalian tidak berkata di waktu mendengar berita bohong itu...\" (Q.S. An-Nur, 16). Dan firman-Nya, \"Allah memperingatkan kalian agar jangan kembali memperbuat yang seperti itu...\" (Q.S. An-Nur, 17). Dalam ayat ini orang-orang yang bertakwa disebutkan secara khusus mengingat hanya merekalah yang dapat mengambil manfaat dari pelajaran yang terkandung di dalamnya.",[["وَلَقَدْ","Dan sesungguhnya"],["أَنزَلْنَآ","Kami telah menurunkan"],["إِلَيْكُمْ","kepada kamu"],["ءَايَـٰتٍۢ","ayat-ayat"],["مُّبَيِّنَـٰتٍۢ","yang nyata"],["وَمَثَلًۭا","dan contoh"],["مِّنَ","daripada"],["ٱلَّذِينَ","orang yang"],["خَلَوْا۟","meninggal dunia"],["مِن","sebelum kamu"],["قَبْلِكُمْ","sebelum kamu"],["وَمَوْعِظَةًۭ","dan teguran"],["لِّلْمُتَّقِينَ","bagi orang-orang yang takut (kepada Allah)"]]],"2826":["(Allah cahaya langit dan bumi) yakni pemberi cahaya langit dan bumi dengan matahari dan bulan. (Perumpamaan cahaya Allah) sifat cahaya Allah di dalam kalbu orang Mukmin (adalah seperti misykat yang di dalamnya ada pelita besar. Pelita itu di dalam kaca) yang dinamakan lampu lentera atau Qandil. Yang dimaksud Al Mishbah adalah lampu atau sumbu yang dinyalakan. Sedangkan Al Misykaat artinya sebuah lubang yang tidak tembus. Sedangkan pengertian pelita di dalam kaca, maksudnya lampu tersebut berada di dalamnya (kaca itu seakan-akan) cahaya yang terpancar darinya (bintang yang bercahaya seperti mutiara) kalau dibaca Diriyyun atau Duriyyun berarti berasal dari kata Ad Dar'u yang artinya menolak atau menyingkirkan, dikatakan demikian karena dapat mengusir kegelapan, maksudnya bercahaya. Jika dibaca Durriyyun dengan mentasydidkan huruf Ra, berarti mutiara, maksudnya cahayanya seperti mutiara (yang dinyalakan) kalau dibaca Tawaqqada dalam bentuk Fi'il Madhi, artinya lampu itu menyala. Menurut suatu qiraat dibaca dalam bentuk Fi'il Mudhari' yaitu Tuuqidu, menurut qiraat lainnya dibaca Yuuqadu, dan menurut qiraat yang lainnya lagi dapat dibaca Tuuqadu, artinya kaca itu seolah-olah dinyalakan (dengan) minyak (dari pohon yang banyak berkahnya, yaitu pohon zaitun yang tumbuh tidak di sebelah Timur dan pula tidak di sebelah Barat) akan tetapi tumbuh di antara keduanya, sehingga tidak terkena panas atau dingin yang dapat merusaknya (yang minyaknya saja hampir-hampir menerangi, walaupun tidak disentuh api) mengingat jernihnya minyak itu. (Cahaya) yang disebabkannya (di atas cahaya) api dari pelita itu. Makna yang dimaksud dengan cahaya Allah adalah petunjuk-Nya kepada orang Mukmin, maksudnya hal itu adalah cahaya di atas cahaya iman (Allah membimbing kepada cahaya-Nya) yaitu kepada agama Islam (siapa yang Dia kehendaki, dan Allah memperbuat) yakni menjelaskan (perumpamaan-perumpamaan bagi manusia) supaya dapat dicerna oleh pemahaman mereka, kemudian supaya mereka mengambil pelajaran daripadanya, sehingga mereka mau beriman (dan Allah Maha Mengetahui segala sesuatu) antara lain ialah membuat perumpamaan-perumpamaan ini.",[["۞ ٱللَّهُ","Allah"],["نُورُ","(ialah) Cahaya"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۚ","dan bumi"],["مَثَلُ","(The) contoh"],["نُورِهِۦ","(dari) Cahaya-Nya"],["كَمِشْكَوٰةٍۢ","(adalah) seperti niche"],["فِيهَا","di dalamnya"],["مِصْبَاحٌ ۖ","(ialah) lampu"],["ٱلْمِصْبَاحُ","lampu itu"],["فِى","(berada) dalam"],["زُجَاجَةٍ ۖ","segelas"],["ٱلزُّجَاجَةُ","kaca itu"],["كَأَنَّهَا","seolah-olah ia adalah"],["كَوْكَبٌۭ","sebuah bintang"],["دُرِّىٌّۭ","cemerlang"],["يُوقَدُ","(yang) menyala"],["مِن","daripada"],["شَجَرَةٍۢ","pokok"],["مُّبَـٰرَكَةٍۢ","diberkati"],["زَيْتُونَةٍۢ","sebiji buah zaitun"],["لَّا","tidak"],["شَرْقِيَّةٍۢ","(dari) timur"],["وَلَا","dan bukan"],["غَرْبِيَّةٍۢ","(dari) barat"],["يَكَادُ","akan hampir"],["زَيْتُهَا","minyaknya"],["يُضِىٓءُ","bercahaya"],["وَلَوْ","walaupun"],["لَمْ","tidak"],["تَمْسَسْهُ","menyentuhnya"],["نَارٌۭ ۚ","kebakaran"],["نُّورٌ","Cahaya"],["عَلَىٰ","ke atas"],["نُورٍۢ ۗ","Cahaya"],["يَهْدِى","Allah memberi petunjuk"],["ٱللَّهُ","Allah memberi petunjuk"],["لِنُورِهِۦ","kepada CahayaNya"],["مَن","yang"],["يَشَآءُ ۚ","Dia kehendaki"],["وَيَضْرِبُ","Dan Allah menetapkan"],["ٱللَّهُ","Dan Allah menetapkan"],["ٱلْأَمْثَـٰلَ","contoh-contohnya"],["لِلنَّاسِ ۗ","untuk umat manusia"],["وَٱللَّهُ","Dan Allah"],["بِكُلِّ","daripada setiap"],["شَىْءٍ","perkara"],["عَلِيمٌۭ","Maha Mengetahui"]]],"2827":["(Di rumah-rumah Allah) maksudnya mesjid-mesjid, lafal Fii Buyuutin berta'alluq kepada lafal Yusabbihu yang akan disebutkan nanti. (Yang Allah telah memerintahkan supaya dimuliakan) yakni diagungkan (dan disebut nama-Nya di dalamnya) dengan mentauhidkan-Nya (bertasbihlah) dapat dibaca Yusabbahu artinya dibacakan tasbih dalam salat. Dapat pula dibaca Yusabbihu, artinya membaca tasbih dalam salat (kepada Allah di dalamnya, pada waktu pagi) lafal Al-Ghuduwwi adalah Mashdar yang maknanya Al-Ghadwaati, artinya pagi hari (dan waktu petang) waktu sore sesudah matahari tergelincir.",[["فِى","Dalam"],["بُيُوتٍ","rumah-rumah"],["أَذِنَ","(yang) diperintahkan Allah"],["ٱللَّهُ","(yang) diperintahkan Allah"],["أَن","bahawa"],["تُرْفَعَ","mereka dibesarkan"],["وَيُذْكَرَ","dan disebut"],["فِيهَا","dalam diri mereka"],["ٱسْمُهُۥ","nama dia"],["يُسَبِّحُ","bertasbih"],["لَهُۥ","[kepada] Dia"],["فِيهَا","dalam diri mereka"],["بِٱلْغُدُوِّ","pada waktu pagi"],["وَٱلْـَٔاصَالِ","dan (pada) petang"]]],"2828":["(Laki-laki) menjadi Fa'il atau subyek daripada Fi'il Yusabbihu, jika dibaca Yusabbahu berkedudukan menjadi Naibul Fa'il. Lafal Rijaalun adalah Fa'il dari Fi'il atau kata kerja yang diperkirakan keberadaannya sebagai jawab dari soal yang diperkirakan pula. Jadi seolah-olah dikatakan, siapakah yang melakukan tasbih kepada-Nya itu, jawabnya adalah laki-laki (yang tidak dilalaikan oleh perniagaan) perdagangan (dan tidak pula oleh jual beli dari mengingat Allah dan dari mendirikan salat) huruf Ha lafal Iqaamatish Shalaati dibuang demi untuk meringankan bacaan sehingga jadilah Iqaamish Shalaati (dan dari membayar zakat. Mereka takut kepada suatu hari yang di hari itu menjadi guncang) yakni panik (hati dan penglihatan) karena merasa khawatir, apakah dirinya selamat atau binasa, dan penglihatan jelalatan ke kanan dan ke kiri karena ngeri melihat pemandangan azab pada saat itu, yaitu hari kiamat.",[["رِجَالٌۭ","Lelaki"],["لَّا","tidak"],["تُلْهِيهِمْ","mengalihkan perhatian mereka"],["تِجَـٰرَةٌۭ","perdagangan"],["وَلَا","dan bukan"],["بَيْعٌ","jualan"],["عَن","daripada"],["ذِكْرِ","(yang) mengingati Allah"],["ٱللَّهِ","(yang) mengingati Allah"],["وَإِقَامِ","dan (daripada) mendirikan"],["ٱلصَّلَوٰةِ","solat"],["وَإِيتَآءِ","dan memberi"],["ٱلزَّكَوٰةِ ۙ","zakat"],["يَخَافُونَ","Mereka takut"],["يَوْمًۭا","sehari"],["تَتَقَلَّبُ","akan berpusing"],["فِيهِ","di dalamnya"],["ٱلْقُلُوبُ","hati"],["وَٱلْأَبْصَـٰرُ","dan mata"]]],"2829":["(Dengan harapan supaya Allah memberi balasan kepada mereka dengan balasan yang lebih baik dari apa yang telah mereka kerjakan) maksudnya pahala yang baik, karena lafal Ahsan bermakna Hasan (dan supaya Allah menambah karunia-Nya kepada mereka. Dan Allah memberi rezeki kepada siapa yang dikehendaki-Nya tanpa batas) jika dikatakan, Fulaanun Yunfiqu Bighairi Hisabin, maka artinya, dia membelanjakan harta tanpa perhitungan lagi.",[["لِيَجْزِيَهُمُ","Supaya Allah memberi ganjaran kepada mereka"],["ٱللَّهُ","Supaya Allah memberi ganjaran kepada mereka"],["أَحْسَنَ","(dengan) yang terbaik"],["مَا","apa"],["عَمِلُوا۟","mereka lakukan"],["وَيَزِيدَهُم","dan meningkatkan mereka"],["مِّن","daripada"],["فَضْلِهِۦ ۗ","Bounty-Nya"],["وَٱللَّهُ","Dan Allah"],["يَرْزُقُ","memberi rezeki kepada"],["مَن","yang"],["يَشَآءُ","Dia kehendaki"],["بِغَيْرِ","tanpa"],["حِسَابٍۢ","mengukur"]]],"2830":["(Dan orang-orang yang kafir amal-amal mereka adalah laksana fatamorgana di tanah yang datar) lafal Qii'ah adalah bentuk jamak dari lafal Qaa'un, yakni padang sahara yang datar. Yang dimaksud dengan lafal Saraabun adalah pemandangan yang tampak di kala matahari sedang terik-teriknya yang rupanya mirip seperti air yang mengalir, atau lazim disebut fatamorgana (ia disangka) diduga (oleh orang yang kehausan) yaitu orang yang dahaga (air, tetapi bila didatanginya air itu dia tidak mendapatinya sesuatu apa pun) apa yang disangkanya itu, demikian pula halnya orang kafir, ia menduga bahwa amal kebaikannya seperti sedekah, yang ia sangka bermanfaat bagi dirinya, tetapi bila ia mati kemudian ia menghadap kepada Rabbnya, maka ia tidak mendapati amal kebaikannya itu. Atau dengan kata lain amalnya itu tidak memberi manfaat kepada dirinya. (Dan ia mendapatkan Allah di sisinya) yakni di sisi amalnya (lalu Allah memberikan kepadanya perhitungan amal-amal dengan cukup) Allah memberikan balasan amal perbuatannya itu hanya di dunia (dan Allah adalah sangat cepat perhitungan-Nya) di dalam memberikan balasan-Nya.",[["وَٱلَّذِينَ","Tetapi mereka yang"],["كَفَرُوٓا۟","kufur"],["أَعْمَـٰلُهُمْ","perbuatan mereka"],["كَسَرَابٍۭ","(adalah) seperti fatamorgana"],["بِقِيعَةٍۢ","di tanah pamah"],["يَحْسَبُهُ","memikirkannya"],["ٱلظَّمْـَٔانُ","yang dahaga"],["مَآءً","(menjadi) air"],["حَتَّىٰٓ","sehingga"],["إِذَا","apabila"],["جَآءَهُۥ","dia datang kepadanya"],["لَمْ","tidak"],["يَجِدْهُ","dia menjumpainya"],["شَيْـًۭٔا","(menjadi) apa sahaja"],["وَوَجَدَ","tetapi dia dapati"],["ٱللَّهَ","Allah"],["عِندَهُۥ","sebelum dia"],["فَوَفَّىٰهُ","Dia akan membayarnya sepenuhnya"],["حِسَابَهُۥ ۗ","haknya"],["وَٱللَّهُ","Dan Allah"],["سَرِيعُ","(adalah) pantas"],["ٱلْحِسَابِ","(dalam) akaun"]]],"2831":["(Atau) amal perbuatan orang-orang kafir yang buruk (seperti gelap-gulita di lautan yang dalam) yakni laut yang amat dalam (yang diliputi oleh ombak di atasnya) di atas ombak itu (ada ombak pula, di atasnya lagi) maksudnya di atas ombak yang kedua itu (awan) yang mendung dan gelap; ini adalah (gelap-gulita yang tindih-menindih) yakni gelapnya laut, gelapnya ombak yang pertama, gelapnya ombak yang kedua, dan gelapnya mendung (apabila dia mengeluarkan) yakni orang yang melihatnya (tangannya) di dalam gelap-gulita yang sangat ini (tiadalah dia dapat melihatnya) artinya hampir saja ia tidak dapat melihat tangannya sendiri (dan barang siapa yang tiada diberi cahaya oleh Allah tiadalah dia mempunyai cahaya sedikit pun) maksudnya barang siapa yang tidak diberi petunjuk oleh Allah, niscaya ia tidak akan mendapatkan petunjuk.",[["أَوْ","Atau"],["كَظُلُمَـٰتٍۢ","(adalah) seperti (the) kegelapan[es]"],["فِى","dalam"],["بَحْرٍۢ","sebuah laut"],["لُّجِّىٍّۢ","dalam"],["يَغْشَىٰهُ","meliputinya"],["مَوْجٌۭ","gelombang"],["مِّن","di atasnya"],["فَوْقِهِۦ","di atasnya"],["مَوْجٌۭ","gelombang"],["مِّن","di atasnya"],["فَوْقِهِۦ","di atasnya"],["سَحَابٌۭ ۚ","awan"],["ظُلُمَـٰتٌۢ","kegelapan[es]"],["بَعْضُهَا","sebahagian daripadanya"],["فَوْقَ","pada"],["بَعْضٍ","yang lain"],["إِذَآ","Apabila"],["أَخْرَجَ","dia keluarkan"],["يَدَهُۥ","tangannya"],["لَمْ","hampir tidak"],["يَكَدْ","hampir tidak"],["يَرَىٰهَا ۗ","dia (boleh) melihatnya"],["وَمَن","Dan (untuk) siapa"],["لَّمْ","tidak"],["يَجْعَلِ","Allah (telah) menjadikan"],["ٱللَّهُ","Allah (telah) menjadikan"],["لَهُۥ","baginya"],["نُورًۭا","sebuah cahaya"],["فَمَا","maka tidak"],["لَهُۥ","baginya"],["مِن","(adalah) mana-mana"],["نُّورٍ","ringan"]]],"2832":["(Tidakkah kamu melihat, bahwasanya Allah kepada-Nya bertasbih apa yang di langit dan di bumi) dan termasuk ke dalam pengertian bertasbih adalah salat (dan juga burung-burung) lafal Thair adalah bentuk jamak dari lafal Ath Thaair, yakni makhluk yang terbang antara bumi dan langit (dengan mengembangkan sayapnya) lafal Shaaffaatin adalah Hal atau kata keterangan keadaan dari burung-burung tadi, yaitu burung-burung itu membaca tasbih dengan mengembangkan sayapnya. (Masing-masingnya telah diketahui) oleh Allah (cara salat dan bertasbihnya, dan Allah Maha Mengetahui apa yang mereka kerjakan). Di dalam ungkapan ini, semuanya dianggap sebagai makhluk yang berakal.",[["أَلَمْ","Jangan"],["تَرَ","kamu lihat"],["أَنَّ","bahawa"],["ٱللَّهَ","Allah"],["يُسَبِّحُ","bertasbih"],["لَهُۥ","Dia"],["مَن","sesiapa sahaja"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["وَٱلطَّيْرُ","dan burung"],["صَـٰٓفَّـٰتٍۢ ۖ","(dengan) sayap terbentang"],["كُلٌّۭ","setiap satu"],["قَدْ","sesungguhnya"],["عَلِمَ","mengetahui"],["صَلَاتَهُۥ","doanya"],["وَتَسْبِيحَهُۥ ۗ","dan pengagungannya"],["وَٱللَّهُ","Dan Allah"],["عَلِيمٌۢ","Maha Mengetahui"],["بِمَا","tentang apa"],["يَفْعَلُونَ","mereka lakukan"]]],"2833":["(Dan kepunyaan Allahlah kerajaan langit dan bumi) maksudnya perbendaharaan-perbendaharaan hujan, rezeki dan tumbuh-tumbuhan (dan kepada Allahlah kembali) semua makhluk.",[["وَلِلَّهِ","Dan kepunyaan Allah"],["مُلْكُ","(kekuasaan)."],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۖ","dan bumi"],["وَإِلَى","Dan kepada"],["ٱللَّهِ","Allah"],["ٱلْمَصِيرُ","(adalah) destinasi"]]],"2834":["(Tidaklah kamu melihat bahwa Allah mengarak awan) menggiringnya secara lembut (kemudian mengumpulkan antara bagian-bagiannya) dengan menghimpun sebagiannya dengan sebagian yang lain, sehingga yang tadinya tersebar kini menjadi satu kumpulan (kemudian menjadikannya bertindih-tindih) yakni sebagiannya di atas sebagian yang lain (maka kelihatanlah olehmu air) hujan (keluar dari celah-celahnya) yakni melalui celah-celahnya (dan Allah juga menurunkan dari langit). Huruf Min yang kedua ini berfungsi menjadi Shilah atau kata penghubung (yakni dari gunung-gunung yang menjulang padanya) menjulang ke langit; Min Jibaalin menjadi Badal daripada lafal Minas Samaa-i dengan mengulangi huruf Jarrnya (berupa es) sebagiannya terdiri dari es (maka ditimpakannya es tersebut kepada siapa yang dikehendaki-Nya dan dipalingkan-Nya dari siapa yang dikehendaki-Nya. Hampir-hampir) hampir saja (kilauan kilat awan itu) yakni cahayanya yang berkilauan (menghilangkan penglihatan) mata yang memandangnya, karena silau olehnya.",[["أَلَمْ","Jangan"],["تَرَ","kamu lihat"],["أَنَّ","bahawa"],["ٱللَّهَ","Allah"],["يُزْجِى","memandu"],["سَحَابًۭا","awan"],["ثُمَّ","kemudian"],["يُؤَلِّفُ","menyertai"],["بَيْنَهُۥ","antara mereka"],["ثُمَّ","kemudian"],["يَجْعَلُهُۥ","menjadikan mereka"],["رُكَامًۭا","(menjadi) jisim"],["فَتَرَى","kemudian kamu lihat"],["ٱلْوَدْقَ","hujan"],["يَخْرُجُ","keluar"],["مِنْ","daripada"],["خِلَـٰلِهِۦ","tengah-tengah mereka"],["وَيُنَزِّلُ","Dan Dia menurunkan"],["مِنَ","daripada"],["ٱلسَّمَآءِ","(langit)."],["مِن","[dari]"],["جِبَالٍۢ","pergunungan"],["فِيهَا","di dalamnya"],["مِنۢ","[daripada]"],["بَرَدٍۢ","(ialah) hujan batu"],["فَيُصِيبُ","dan Dia menyerang"],["بِهِۦ","dengannya"],["مَن","yang"],["يَشَآءُ","Dia kehendaki"],["وَيَصْرِفُهُۥ","dan mengelakkannya"],["عَن","daripada"],["مَّن","yang"],["يَشَآءُ ۖ","Dia kehendaki"],["يَكَادُ","hampir"],["سَنَا","(the) kilat"],["بَرْقِهِۦ","(daripada) pencahayaannya"],["يَذْهَبُ","membawa pergi"],["بِٱلْأَبْصَـٰرِ","penglihatan itu"]]],"2835":["(Allah mempergantikan malam dan siang) mendatangkan masing-masingnya sebagai pengganti dari yang lain. (sesungguhnya pada yang demikian itu) yakni pergantian ini (terdapat pelajaran) yang menunjukkan kebesaran-Nya (bagi orang-orang yang mempunyai penglihatan) bagi mereka yang memiliki penglihatan memandang kekuasaan Allah swt.",[["يُقَلِّبُ","Allah silih berganti"],["ٱللَّهُ","Allah silih berganti"],["ٱلَّيْلَ","malam"],["وَٱلنَّهَارَ ۚ","dan hari"],["إِنَّ","Sesungguhnya"],["فِى","dalam"],["ذَٰلِكَ","bahawa"],["لَعِبْرَةًۭ","pasti menjadi pengajaran"],["لِّأُو۟لِى","bagi mereka yang mempunyai penglihatan"],["ٱلْأَبْصَـٰرِ","bagi mereka yang mempunyai penglihatan"]]],"2836":["(Dan Allah telah menciptakan semua jenis hewan) maksudnya makhluk hidup (dari air) yakni air mani (maka sebagian dari hewan itu ada yang berjalan di atas perutnya) seperti ulat dan binatang melata lainnya (dan sebagian berjalan dengan dua kaki) seperti manusia dan burung (sedangkan sebagian yang lain berjalan dengan empat kaki) seperti hewan liar dan hewan ternak. (Allah menciptakan apa yang dikehendaki-Nya, sesungguhnya Allah Maha Kuasa atas segala sesuatu).",[["وَٱللَّهُ","Dan Allah"],["خَلَقَ","dicipta"],["كُلَّ","setiap"],["دَآبَّةٍۢ","makhluk bergerak"],["مِّن","daripada"],["مَّآءٍۢ ۖ","air"],["فَمِنْهُم","Daripada mereka"],["مَّن","(adalah sejenis) siapa"],["يَمْشِى","berjalan-jalan"],["عَلَىٰ","pada"],["بَطْنِهِۦ","perutnya"],["وَمِنْهُم","dan daripada mereka"],["مَّن","(adalah sejenis) siapa"],["يَمْشِى","berjalan-jalan"],["عَلَىٰ","pada"],["رِجْلَيْنِ","dua kaki"],["وَمِنْهُم","dan daripada mereka"],["مَّن","(adalah sejenis) siapa"],["يَمْشِى","berjalan-jalan"],["عَلَىٰٓ","pada"],["أَرْبَعٍۢ ۚ","empat"],["يَخْلُقُ","Allah mencipta"],["ٱللَّهُ","Allah mencipta"],["مَا","apa"],["يَشَآءُ ۚ","Dia kehendaki"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["عَلَىٰ","pada"],["كُلِّ","setiap"],["شَىْءٍۢ","perkara"],["قَدِيرٌۭ","(adalah) Maha Kuasa"]]],"2837":["(Sesungguhnya Kami telah menurunkan ayat-ayat yang menjelaskan) yaitu Alquran. (Dan Allah memimpin siapa yang dikehendaki-Nya kepada jalan) yakni tuntunan (yang lurus) yaitu agama Islam.",[["لَّقَدْ","Sesungguhnya"],["أَنزَلْنَآ","Kami telah menurunkan"],["ءَايَـٰتٍۢ","ayat-ayat"],["مُّبَيِّنَـٰتٍۢ ۚ","yang nyata"],["وَٱللَّهُ","Dan Allah"],["يَهْدِى","panduan"],["مَن","yang"],["يَشَآءُ","Dia kehendaki"],["إِلَىٰ","kepada"],["صِرَٰطٍۢ","satu laluan"],["مُّسْتَقِيمٍۢ","lurus"]]],"2838":["(Dan mereka berkata) maksudnya orang-orang munafik, (\"Kami telah beriman) Kami telah percaya (kepada Allah) dengan mengesakan-Nya (dan Rasul) yaitu Nabi Muhammad (dan Kami menaati\") apa yang telah ditetapkan oleh Allah dan Rasul-Nya. (Kemudian berpalinglah) memalingkan diri (sebagian dari mereka sesudah itu) dari apa yang telah ditetapkan oleh Allah dan Rasul-Nya (sekali-kali mereka itu bukanlah) orang-orang yang berpaling itu (orang-orang yang beriman) sejati, yang hati dan lisan mereka bersesuaian.",[["وَيَقُولُونَ","Dan mereka berkata"],["ءَامَنَّا","Kami beriman"],["بِٱللَّهِ","kepada Allah"],["وَبِٱلرَّسُولِ","dan dalam Rasul"],["وَأَطَعْنَا","dan kami patuh"],["ثُمَّ","Kemudian"],["يَتَوَلَّىٰ","berpaling"],["فَرِيقٌۭ","sebuah parti"],["مِّنْهُم","daripada mereka"],["مِّنۢ","selepas"],["بَعْدِ","selepas"],["ذَٰلِكَ ۚ","bahawa"],["وَمَآ","Dan tidak"],["أُو۟لَـٰٓئِكَ","mereka"],["بِٱلْمُؤْمِنِينَ","(adalah) orang yang beriman"]]],"2839":["(Dan apabila mereka dipanggil kepada Allah dan Rasul-Nya) yang menyampaikan kepada mereka (agar Rasul menghukum/mengadili di antara mereka, tiba-tiba sebagian dari mereka berpaling) menolak untuk datang memenuhi seruan Rasul.",[["وَإِذَا","Dan apabila"],["دُعُوٓا۟","mereka dipanggil"],["إِلَى","kepada"],["ٱللَّهِ","Allah"],["وَرَسُولِهِۦ","dan Rasul-Nya"],["لِيَحْكُمَ","untuk menilai"],["بَيْنَهُمْ","antara mereka"],["إِذَا","lihatlah"],["فَرِيقٌۭ","sebuah parti"],["مِّنْهُم","daripada mereka"],["مُّعْرِضُونَ","(adalah) enggan"]]],"2840":["(Tetapi jika keputusan itu untuk kemaslahatan mereka, mereka mau datang kepada Rasul dengan patuh) dengan segera dan penuh ketaatan.",[["وَإِن","Tetapi jika"],["يَكُن","ialah"],["لَّهُمُ","bersama mereka"],["ٱلْحَقُّ","kebenaran"],["يَأْتُوٓا۟","mereka datang"],["إِلَيْهِ","kepadanya"],["مُذْعِنِينَ","(sebagai) patuh segera"]]],"2841":["(Apakah di dalam hati mereka ada penyakit) yakni kekafiran (atau karena mereka ragu-ragu) mereka meragukan kenabiannya (ataukah karena mereka takut kalau-kalau Allah dan Rasul-Nya berlaku zalim kepada mereka?) di dalam peradilan, yakni mereka diperlakukan secara aniaya di dalamnya. Tidak (sebenarnya, mereka itulah orang-orang yang zalim) karena mereka berpaling dari peradilan itu.",[["أَفِى","Adakah (ada) dalam"],["قُلُوبِهِم","hati mereka"],["مَّرَضٌ","suatu penyakit"],["أَمِ","atau"],["ٱرْتَابُوٓا۟","adakah mereka ragu-ragu"],["أَمْ","atau"],["يَخَافُونَ","mereka takut"],["أَن","bahawa"],["يَحِيفَ","Allah akan berlaku zalim"],["ٱللَّهُ","Allah akan berlaku zalim"],["عَلَيْهِمْ","kepada mereka"],["وَرَسُولُهُۥ ۚ","dan Rasul-Nya"],["بَلْ","Bahkan"],["أُو۟لَـٰٓئِكَ","mereka"],["هُمُ","[mereka]"],["ٱلظَّـٰلِمُونَ","(adalah) orang-orang yang zalim"]]],"2842":["(Sesungguhnya jawaban orang-orang Mukmin, bila mereka dipanggil kepada Allah dan Rasul-Nya agar Rasul mengadili di antara mereka) maka jawaban yang pantas mereka katakan (ialah ucapan, \"Kami mendengar dan Kami patuh\") yakni mengiakan secara spontan. (Dan mereka) sejak saat itu (adalah orang-orang yang beruntung) artinya orang-orang yang selamat di dunia dan akhirat.",[["إِنَّمَا","Hanya"],["كَانَ","ialah"],["قَوْلَ","(pernyataan)."],["ٱلْمُؤْمِنِينَ","(dari) orang-orang yang beriman"],["إِذَا","apabila"],["دُعُوٓا۟","mereka dipanggil"],["إِلَى","kepada"],["ٱللَّهِ","Allah"],["وَرَسُولِهِۦ","dan Rasul-Nya"],["لِيَحْكُمَ","untuk menilai"],["بَيْنَهُمْ","antara mereka"],["أَن","(ialah) itu"],["يَقُولُوا۟","mereka berkata"],["سَمِعْنَا","Kita dengar"],["وَأَطَعْنَا ۚ","dan kami patuh"],["وَأُو۟لَـٰٓئِكَ","Dan mereka"],["هُمُ","[mereka]"],["ٱلْمُفْلِحُونَ","(adalah) orang yang berjaya"]]],"2843":["(Dan barang siapa yang taat kepada Allah dan Rasul-Nya dan takut kepada Allah) merasa takut kepada-Nya (dan bertakwa kepada-Nya) dapat dibaca Wayattaqih dan Wayattaqhi, yakni dengan menaati-Nya (maka mereka adalah orang-orang yang mendapat kemenangan) yaitu mendapat surga.",[["وَمَن","Dan sesiapa"],["يُطِعِ","patuh"],["ٱللَّهَ","Allah"],["وَرَسُولَهُۥ","dan Rasul-Nya"],["وَيَخْشَ","dan ketakutan"],["ٱللَّهَ","Allah"],["وَيَتَّقْهِ","dan (bertakwa) kepada-Nya"],["فَأُو۟لَـٰٓئِكَ","kemudian mereka"],["هُمُ","[mereka]"],["ٱلْفَآئِزُونَ","(adalah) orang-orang yang berjaya"]]],"2844":["(Dan mereka bersumpah dengan nama Allah sekuat-kuat sumpah) dengan sekuatnya (jika kalian suruh mereka) untuk pergi berjihad (pastilah mereka akan pergi. Katakanlah!) kepada mereka (\"Janganlah kalian bersumpah, karena ketaatan yang diminta ialah ketaatan yang sebenarnya) maksudnya taat yang sebenarnya kepada Nabi adalah lebih baik daripada sumpah kalian yang tidak kalian tunaikan. (Sesungguhnya Allah Maha Mengetahui apa yang kalian kerjakan\") berupa ketaatan kalian secara lisan, padahal kalian bertentangan dalam prakteknya.",[["۞ وَأَقْسَمُوا۟","Dan mereka bersumpah"],["بِٱللَّهِ","oleh Allah"],["جَهْدَ","kuat"],["أَيْمَـٰنِهِمْ","sumpah mereka"],["لَئِنْ","bahawa jika"],["أَمَرْتَهُمْ","kamu memerintahkan mereka"],["لَيَخْرُجُنَّ ۖ","sesungguhnya mereka (akan) pergi"],["قُل","Katakanlah"],["لَّا","Jangan"],["تُقْسِمُوا۟ ۖ","bersumpah"],["طَاعَةٌۭ","Ketaatan"],["مَّعْرُوفَةٌ ۚ","(adalah) diketahui"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["خَبِيرٌۢ","(adalah) Maha Mengetahui"],["بِمَا","tentang apa"],["تَعْمَلُونَ","kamu lakukan"]]],"2845":["(Katakanlah! \"Taatlah kepada Allah dan taatlah kepada Rasul dan jika kalian berpaling) dari taat kepadanya. Lafal Tawallau asalnya adalah Tatawallau; maksudnya pembicaraan ini ditujukan kepada mereka (maka sesungguhnya kewajiban Rasul itu adalah apa yang dibebankan kepadanya) yaitu menyampaikan risalah (dan kewajiban kamu sekalian adalah semata-mata apa yang dibebankan kepada kalian) yakni untuk taat kepadanya (dan jika kalian taat kepadanya, niscaya kalian mendapat petunjuk. Dan tidak lain kewajiban Rasul itu melainkan menyampaikan amanat Allah dengan terang\") yaitu secara jelas dan gamblang.",[["قُلْ","Katakanlah"],["أَطِيعُوا۟","Patuh"],["ٱللَّهَ","Allah"],["وَأَطِيعُوا۟","dan taat"],["ٱلرَّسُولَ ۖ","Rasul"],["فَإِن","tetapi jika"],["تَوَلَّوْا۟","kamu berpaling"],["فَإِنَّمَا","kemudian sahaja"],["عَلَيْهِ","atasnya"],["مَا","(ialah) apa"],["حُمِّلَ","(adalah) diletakkan ke atasnya"],["وَعَلَيْكُم","dan pada kamu"],["مَّا","(ialah) apa"],["حُمِّلْتُمْ ۖ","(adalah) diletakkan pada kamu"],["وَإِن","Dan jika"],["تُطِيعُوهُ","kamu taat kepadanya"],["تَهْتَدُوا۟ ۚ","kamu akan dibimbing"],["وَمَا","Dan tidak"],["عَلَى","(berada) di atas"],["ٱلرَّسُولِ","Rasul"],["إِلَّا","kecuali"],["ٱلْبَلَـٰغُ","pengangkutan itu"],["ٱلْمُبِينُ","[yang] jelas"]]],"2846":["(Dan Allah telah menjanjikan kepada orang-orang yang beriman di antara kalian dan mengerjakan amal-amal yang saleh, bahwa Dia sungguh-sungguh akan menjadikan mereka berkuasa di bumi) sebagai ganti dari orang-orang kafir (sebagaimana Dia telah menjadikan berkuasa) dapat dibaca Kamastakhlafa dan Kamastukhlifa (orang-orang yang sebelum mereka) sebagaimana yang dialami oleh kaum Bani Israel sebagai pengganti dari orang-orang yang lalim dan angkara murka (dan sungguh Dia akan meneguhkan bagi mereka agama yang telah diridai-Nya untuk mereka) yaitu agama Islam; seumpamanya Dia akan memenangkannya di atas agama-agama yang lain, kemudian Dia meluaskan bagi mereka daerah-daerah mereka dan mereka menjadi para pemiliknya (dan Dia benar-benar akan menukar keadaan mereka) dapat dibaca Takhfif yaitu menjadi walayubdilannahum, dapat pula dibaca Tasydid yaitu menjadi Walayubaddilannahum (sesudah mereka berada dalam ketakutan) dari perlakuan orang-orang kafir (menjadi aman sentosa) dan Allah telah menunaikan janji-Nya kepada mereka, yaitu memberikan kepada mereka apa yang telah disebutkan tadi, kemudian Dia memuji mereka melalui firman-Nya, (Mereka tetap menyembah-Ku dengan tiada mempersekutukan sesuatu apa pun dengan Aku) ayat ini merupakan jumlah Isti'naf atau kalimat baru, akan tetapi statusnya disamakan sebagai Illat. (Dan barang siapa yang tetap kafir sesudah janji itu) sesudah pemberian nikmat kepada mereka, yaitu keamanan tadi (maka mereka itulah orang-orang yang fasik) dan orang-orang yang mula-mula kafir sesudah itu adalah para pembunuh Khalifah Usman r.a. kemudian mereka menjadi orang-orang yang saling membunuh padahal sebelumnya mereka berteman.",[["وَعَدَ","Allah (telah) berjanji"],["ٱللَّهُ","Allah (telah) berjanji"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["مِنكُمْ","antara kamu"],["وَعَمِلُوا۟","dan melakukan"],["ٱلصَّـٰلِحَـٰتِ","amal soleh"],["لَيَسْتَخْلِفَنَّهُمْ","nescaya Dia akan menggantikan mereka"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["كَمَا","seperti"],["ٱسْتَخْلَفَ","Dia memberi penggantian"],["ٱلَّذِينَ","kepada mereka yang"],["مِن","(ada) sebelum mereka"],["قَبْلِهِمْ","(ada) sebelum mereka"],["وَلَيُمَكِّنَنَّ","dan sesungguhnya Dia akan meneguhkan"],["لَهُمْ","bagi mereka"],["دِينَهُمُ","agama mereka"],["ٱلَّذِى","yang"],["ٱرْتَضَىٰ","Dia telah meluluskan"],["لَهُمْ","bagi mereka"],["وَلَيُبَدِّلَنَّهُم","dan sesungguhnya Dia akan berubah untuk mereka"],["مِّنۢ","selepas"],["بَعْدِ","selepas"],["خَوْفِهِمْ","ketakutan mereka"],["أَمْنًۭا ۚ","keselamatan"],["يَعْبُدُونَنِى","(kerana) mereka menyembah-Ku"],["لَا","tidak"],["يُشْرِكُونَ","mereka bergaul"],["بِى","dengan Aku"],["شَيْـًۭٔا ۚ","sesuatu"],["وَمَن","Tetapi siapa pun"],["كَفَرَ","kufur"],["بَعْدَ","selepas"],["ذَٰلِكَ","bahawa"],["فَأُو۟لَـٰٓئِكَ","kemudian mereka"],["هُمُ","[mereka]"],["ٱلْفَـٰسِقُونَ","(adalah) orang-orang yang durhaka"]]],"2847":["(Dan dirikanlah salat, tunaikanlah zakat, dan taatlah kepada Rasul, supaya kalian diberi rahmat) mudah-mudahan kalian diberi rahmat.",[["وَأَقِيمُوا۟","Dan dirikanlah"],["ٱلصَّلَوٰةَ","solat"],["وَءَاتُوا۟","dan memberi"],["ٱلزَّكَوٰةَ","zakat"],["وَأَطِيعُوا۟","dan taat"],["ٱلرَّسُولَ","Rasul"],["لَعَلَّكُمْ","supaya kamu"],["تُرْحَمُونَ","mendapat rahmat"]]],"2848":["(Janganlah kamu kira) dapat dibaca Tahsabanna dan Yahsabanna, yang menjadi Fa'il atau subyeknya adalah Rasulullah (bahwa orang-orang yang kafir itu dapat melemahkan) Kami (di bumi ini) yakni selamat dari azab Kami (sedangkan tempat tinggal mereka) yaitu tempat mereka kembali (adalah neraka. Dan sungguh sejelek-jelek tempat kembali adalah neraka) maksudnya tempat kembali yang paling buruk.",[["لَا","Jangan"],["تَحْسَبَنَّ","fikir"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["مُعْجِزِينَ","(boleh) melarikan diri"],["فِى","dalam"],["ٱلْأَرْضِ ۚ","bumi"],["وَمَأْوَىٰهُمُ","Dan tempat tinggal mereka"],["ٱلنَّارُ ۖ","(akan menjadi) Neraka"],["وَلَبِئْسَ","dan celaka adalah"],["ٱلْمَصِيرُ","destinasi"]]],"2849":["(Hai orang-orang yang beriman, hendaklah meminta izin kepada kalian budak-budak yang kalian miliki) baik yang laki-laki maupun yang perempuan (dan orang-orang yang belum balig di antara kalian) maksudnya dari kalangan orang-orang yang merdeka dan belum mengetahui perihal kaum wanita (sebanyak tiga kali) yaitu dalam tiga waktu untuk seharinya (yaitu sebelum salat subuh dan ketika kalian menanggalkan pakaian luar kalian di tengah hari) yakni waktu salat Zuhur (dan sesudah salat Isyak. Itulah tiga aurat bagi kalian) kalau dibaca Rafa' menjadi Tsalaatsu 'Auraatin, berarti menjadi Khabar dari Mubtada yang diperkirakan keberadaannya, dan sebelum Khabar terdapat Mudhaf, kemudian kedudukan Mudhaf yang diperkirakan itu diganti oleh Mudhaf ilaih yaitu lafal Tsalaatsun itu sendiri. Makna selengkapnya ialah, Ketentuan tersebut adalah tiga waktu yang ketiga-tiganya merupakan aurat bagi kalian. Jika dibaca Nashab menjadi Tsalaatsa Auraatin Lakum, dengan memperkirakan adanya lafal Auraatin yang dinashabkan, juga karena menjadi Badal secara Mahal dari lafal sebelumnya, kemudian Mudhaf ilaih menggantikan kedudukannya. Dikatakan demikian karena pada saat-saat tersebut, yaitu ketiga waktu itu, orang-orang membuka pakaian luar mereka untuk istirahat sehingga auratnya kelihatan. (Tidak ada atas kalian dan tidak pula atas mereka) atas budak-budak yang kalian miliki dan anak-anak kecil (dosa) untuk masuk menemui kalian tanpa izin (selain dari tiga waktu itu) yakni sesudah ketiga waktu tadi, sedangkan mereka (melayani kalian) meladeni kalian (sebagian kalian) yakni pelayan itu mempunyai keperluan (kepada sebagian yang lain) kalimat ini berkedudukan mengukuhkan makna sebelumnya. (Demikianlah) sebagaimana apa yang telah disebutkan tadi (Allah menjelaskan ayat-ayat bagi kalian) yakni menjelaskan hukum-hukum-Nya. (Dan Allah Maha Mengetahui) tentang semua urusan makhluk-Nya (lagi Maha Bijaksana) di dalam mengatur kepentingan mereka. Ayat yang menyangkut masalah meminta izin ini menurut suatu pendapat telah dinasakh. Akan tetapi menurut pendapat yang lain tidak dinasakh, hanya saja orang-orang meremehkan masalah meminta izin ini, sehingga banyak dari mereka yang tidak memakainya lagi.",[["يَـٰٓأَيُّهَا","Wahai orang yang beriman"],["ٱلَّذِينَ","Wahai orang yang beriman"],["ءَامَنُوا۟","Wahai orang yang beriman"],["لِيَسْتَـْٔذِنكُمُ","Minta izin kamu"],["ٱلَّذِينَ","mereka yang"],["مَلَكَتْ","memiliki"],["أَيْمَـٰنُكُمْ","tangan kanan kamu"],["وَٱلَّذِينَ","dan orang yang"],["لَمْ","(mempunyai) tidak"],["يَبْلُغُوا۟","dicapai"],["ٱلْحُلُمَ","akil baligh"],["مِنكُمْ","antara kamu"],["ثَلَـٰثَ","(pada) tiga"],["مَرَّٰتٍۢ ۚ","kali"],["مِّن","sebelum"],["قَبْلِ","sebelum"],["صَلَوٰةِ","(yang) solat"],["ٱلْفَجْرِ","(dari) subuh"],["وَحِينَ","dan apabila"],["تَضَعُونَ","kamu ketepikan"],["ثِيَابَكُم","pakaian kamu"],["مِّنَ","di"],["ٱلظَّهِيرَةِ","tengah hari"],["وَمِنۢ","dan selepas"],["بَعْدِ","dan selepas"],["صَلَوٰةِ","(yang) solat"],["ٱلْعِشَآءِ ۚ","(dari) malam"],["ثَلَـٰثُ","(Ini) tiga"],["عَوْرَٰتٍۢ","(adalah) masa privasi"],["لَّكُمْ ۚ","bagi kamu"],["لَيْسَ","Tidak"],["عَلَيْكُمْ","pada kamu"],["وَلَا","dan bukan"],["عَلَيْهِمْ","ke atas mereka"],["جُنَاحٌۢ","sebarang kesalahan"],["بَعْدَهُنَّ ۚ","selepas itu"],["طَوَّٰفُونَ","(sebagai) bergerak"],["عَلَيْكُم","antara kamu"],["بَعْضُكُمْ","sebahagian daripada kamu"],["عَلَىٰ","antara"],["بَعْضٍۢ ۚ","yang lain"],["كَذَٰلِكَ","Demikianlah"],["يُبَيِّنُ","Allah jelaskan"],["ٱللَّهُ","Allah jelaskan"],["لَكُمُ","bagi kamu"],["ٱلْـَٔايَـٰتِ ۗ","ayat-ayat"],["وَٱللَّهُ","dan Allah"],["عَلِيمٌ","Maha Mengetahui"],["حَكِيمٌۭ","Maha Bijaksana"]]],"2850":["(Dan apabila anak-anak kalian telah sampai) hai orang-orang yang merdeka (kepada usia balig, maka hendaklah mereka meminta izin) dalam semua waktu (seperti orang-orang yang sebelum mereka meminta izin) yakni orang-orang dewasa yang merdeka. (Demikianlah Allah menjelaskan ayat-ayat-Nya bagi kalian. Dan Allah Maha mengetahui lagi Maha Bijaksana).",[["وَإِذَا","Dan apabila"],["بَلَغَ","capai"],["ٱلْأَطْفَـٰلُ","anak-anak"],["مِنكُمُ","antara kamu"],["ٱلْحُلُمَ","akil baligh"],["فَلْيَسْتَـْٔذِنُوا۟","maka hendaklah mereka meminta izin"],["كَمَا","seperti"],["ٱسْتَـْٔذَنَ","minta izin"],["ٱلَّذِينَ","orang yang"],["مِن","(ada) sebelum mereka"],["قَبْلِهِمْ ۚ","(ada) sebelum mereka"],["كَذَٰلِكَ","Demikianlah"],["يُبَيِّنُ","Allah jelaskan"],["ٱللَّهُ","Allah jelaskan"],["لَكُمْ","bagi kamu"],["ءَايَـٰتِهِۦ ۗ","Ayat-ayatNya"],["وَٱللَّهُ","Dan Allah"],["عَلِيمٌ","Maha Mengetahui"],["حَكِيمٌۭ","Maha Bijaksana"]]],"2851":["(Dan perempuan-perempuan tua yang telah terhenti) dari haid dan dari mempunyai anak disebabkan telah lanjut umurnya (yang tiada ingin kawin lagi) bagi yang demikian itu (tiadalah atas mereka dosa menanggalkan pakaian mereka) yakni jilbab mereka, atau selendang mereka, atau penutup yang ada di atas kerudung mereka (dengan tidak bermaksud menampakkan) yakni menonjolkan (perhiasan)-nya yang tersembunyi seperti kalung, gelang tangan dan gelang kaki (dan berlaku terhormat) tidak melepaskannya (adalah lebih baik bagi mereka. Dan Allah Maha Mendengar) perkataan kalian (lagi Maha Mengetahui) apa yang tersimpan di dalam kalbu kalian.",[["وَٱلْقَوَٰعِدُ","Dan selepas menopaus"],["مِنَ","antara"],["ٱلنِّسَآءِ","kaum wanita"],["ٱلَّـٰتِى","yang"],["لَا","jangan"],["يَرْجُونَ","mempunyai keinginan"],["نِكَاحًۭا","(untuk) perkahwinan"],["فَلَيْسَ","maka bukan"],["عَلَيْهِنَّ","ke atas mereka"],["جُنَاحٌ","sebarang kesalahan"],["أَن","bahawa"],["يَضَعْنَ","mereka ketepikan"],["ثِيَابَهُنَّ","pakaian (luar) mereka"],["غَيْرَ","tidak"],["مُتَبَرِّجَـٰتٍۭ","memaparkan"],["بِزِينَةٍۢ ۖ","perhiasan mereka"],["وَأَن","Dan bahawa"],["يَسْتَعْفِفْنَ","mereka dengan sederhana menahan diri"],["خَيْرٌۭ","(lebih) baik"],["لَّهُنَّ ۗ","bagi mereka"],["وَٱللَّهُ","Dan Allah"],["سَمِيعٌ","(adalah) Yang Maha Mendengar"],["عَلِيمٌۭ","Maha Mengetahui"]]],"2852":["(Tidak ada dosa bagi orang buta, tidak pula bagi orang pincang, dan tidak pula bagi orang sakit) untuk makan bersama dengan orang-orang selain mereka (dan tidak pula) dosa (bagi diri kalian sendiri untuk makan bersama mereka di rumah kalian sendiri) yaitu di rumah anak-anak kalian (atau rumah bapak-bapak kalian, di rumah ibu-ibu kalian, di rumah saudara-saudara kalian yang laki-laki, di rumah saudara-saudara kalian yang perempuan, di rumah saudara-saudara bapak kalian yang laki-laki, di rumah saudara-saudara bapak kalian yang perempuan, di rumah saudara-saudara ibu kalian yang laki-laki, di rumah saudara-saudara ibu kalian yang perempuan, di rumah yang kalian miliki kuncinya) yang khusus kalian sediakan buat orang lain (atau - di rumah - kawan-kawan kalian) yang dimaksud dengan kawan adalah orang-orang yang benar-benar setia kepada kalian. Makna ayat ini ialah, bahwa kalian diperbolehkan makan dari rumah-rumah orang-orang yang telah disebutkan tadi, sekalipun para pemiliknya tidak hadir atau sedang tidak ada di rumah, jika memang kalian telah yakin akan kerelaan mereka terhadap sikap kalian itu (Tidak ada dosa bagi kalian makan bersama-sama mereka) yakni berbarengan dengan mereka (atau sendirian) tidak bersama-sama. Lafal Asytaatan ini adalah bentuk jamak dari kata Syatta, artinya sendiri-sendiri atau berpisah-pisah. Ayat ini diturunkan berkenaan dengan seseorang yang merasa berdosa jika ia makan sendirian. Jika ia tidak menemukan seseorang yang mau makan bersamanya, maka ia tidak mau memakan makanannya (maka apabila kalian memasuki rumah-rumah) milik kalian sendiri yang tidak ada penghuninya (hendaklah kalian memberi salam kepada diri kalian sendiri) katakanlah! \"Assalaamu 'Alainaa Wa Alaa `Ibaadillaahish Shaalihiin\" yang artinya, \"Keselamatan semoga dilimpahkan kepada diri kami dan hamba-hamba Allah yang saleh\". Karena sesungguhnya para Malaikatlah yang akan menjawab salam kalian itu. Jika ternyata di dalam rumah-rumah itu terdapat penghuninya, maka berilah salam kepada mereka (sebagai salam) lafal Tahiyyatan menjadi Mashdar artinya sebagai penghormatan (yang ditetapkan di sisi Allah, yang diberkati lagi baik) yakni diberi pahala bagi orang yang mengucapkannya. (Demikianlah Allah menjelaskan ayat-ayat-Nya bagi kalian) Dia merincikan tanda-tanda agama kalian (agar kalian memahaminya) supaya kalian mengerti hal tersebut.",[["لَّيْسَ","bukan"],["عَلَى","pada"],["ٱلْأَعْمَىٰ","yang buta"],["حَرَجٌۭ","sebarang kesalahan"],["وَلَا","dan bukan"],["عَلَى","pada"],["ٱلْأَعْرَجِ","yang lumpuh"],["حَرَجٌۭ","sebarang kesalahan"],["وَلَا","dan bukan"],["عَلَى","pada"],["ٱلْمَرِيضِ","yang sakit"],["حَرَجٌۭ","sebarang kesalahan"],["وَلَا","dan bukan"],["عَلَىٰٓ","pada"],["أَنفُسِكُمْ","kamu sendiri"],["أَن","bahawa"],["تَأْكُلُوا۟","kamu makan"],["مِنۢ","daripada"],["بُيُوتِكُمْ","rumah-rumah kamu"],["أَوْ","atau"],["بُيُوتِ","rumah-rumah"],["ءَابَآئِكُمْ","(dari) bapa-bapa kamu"],["أَوْ","atau"],["بُيُوتِ","rumah-rumah"],["أُمَّهَـٰتِكُمْ","(dari) ibu kamu"],["أَوْ","atau"],["بُيُوتِ","rumah-rumah"],["إِخْوَٰنِكُمْ","(dari) saudara-saudaramu"],["أَوْ","atau"],["بُيُوتِ","rumah-rumah"],["أَخَوَٰتِكُمْ","(daripada) saudara perempuan kamu"],["أَوْ","atau"],["بُيُوتِ","rumah-rumah"],["أَعْمَـٰمِكُمْ","(daripada) bapa saudara sebelah bapa kamu"],["أَوْ","atau"],["بُيُوتِ","rumah-rumah"],["عَمَّـٰتِكُمْ","(daripada) ibu saudara sebelah bapa kamu"],["أَوْ","atau"],["بُيُوتِ","rumah-rumah"],["أَخْوَٰلِكُمْ","(daripada) bapa saudara sebelah ibu kamu"],["أَوْ","atau"],["بُيُوتِ","rumah-rumah"],["خَـٰلَـٰتِكُمْ","(daripada) ibu saudara sebelah ibu kamu"],["أَوْ","atau"],["مَا","apa"],["مَلَكْتُم","kamu miliki"],["مَّفَاتِحَهُۥٓ","kuncinya"],["أَوْ","atau"],["صَدِيقِكُمْ ۚ","kawan kamu"],["لَيْسَ","bukan"],["عَلَيْكُمْ","pada kamu"],["جُنَاحٌ","sebarang kesalahan"],["أَن","bahawa"],["تَأْكُلُوا۟","kamu makan"],["جَمِيعًا","bersama-sama"],["أَوْ","atau"],["أَشْتَاتًۭا ۚ","secara berasingan"],["فَإِذَا","Tetapi apabila"],["دَخَلْتُم","kamu masuk"],["بُيُوتًۭا","rumah-rumah"],["فَسَلِّمُوا۟","kemudian memberi salam"],["عَلَىٰٓ","[pada]"],["أَنفُسِكُمْ","kamu sendiri"],["تَحِيَّةًۭ","salam"],["مِّنْ","daripada"],["عِندِ","daripada"],["ٱللَّهِ","Allah"],["مُبَـٰرَكَةًۭ","diberkati"],["طَيِّبَةًۭ ۚ","(dan) baik"],["كَذَٰلِكَ","Demikianlah"],["يُبَيِّنُ","Allah jelaskan"],["ٱللَّهُ","Allah jelaskan"],["لَكُمُ","bagi kamu"],["ٱلْـَٔايَـٰتِ","ayat-ayat"],["لَعَلَّكُمْ","supaya kamu"],["تَعْقِلُونَ","faham"]]],"2853":["(Orang-orang Mukmin yang sesungguhnya itu tidak lain hanyalah orang-orang yang beriman kepada Allah dan Rasul-Nya, dan apabila mereka berada bersama-sama dengannya) dengan Rasulullah (dalam sesuatu urusan yang memerlukan pertemuan) seperti khutbah Jumat (mereka tidak meninggalkan) Rasulullah karena hal-hal mendadak yang dialami mereka, dalam hal ini mereka dimaafkan (sebelum meminta izin kepadanya. Sesungguhnya orang-orang yang meminta izin kepadamu, mereka itulah orang-orang yang beriman kepada Allah dan Rasul-Nya, maka apabila mereka meminta izin kepadamu karena sesuatu keperluan mereka) karena mereka mempunyai urusan penting (berilah izin kepada siapa yang kamu kehendaki di antara mereka) untuk pergi (dan mohonkanlah ampunan untuk mereka kepada Allah. Sesungguhnya Allah Maha Pengampun lagi Maha Penyayang).",[["إِنَّمَا","Hanya"],["ٱلْمُؤْمِنُونَ","orang yang beriman"],["ٱلَّذِينَ","(adalah) mereka yang"],["ءَامَنُوا۟","beriman"],["بِٱللَّهِ","kepada Allah"],["وَرَسُولِهِۦ","dan Rasul-Nya"],["وَإِذَا","dan apabila"],["كَانُوا۟","mereka adalah"],["مَعَهُۥ","dengan dia"],["عَلَىٰٓ","bagi"],["أَمْرٍۢ","sesuatu perkara"],["جَامِعٍۢ","(dari) tindakan kolektif"],["لَّمْ","tidak"],["يَذْهَبُوا۟","mereka pergi"],["حَتَّىٰ","sehingga"],["يَسْتَـْٔذِنُوهُ ۚ","mereka (telah) meminta izinnya"],["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["يَسْتَـْٔذِنُونَكَ","minta izin kamu"],["أُو۟لَـٰٓئِكَ","mereka"],["ٱلَّذِينَ","[mereka yang]"],["يُؤْمِنُونَ","beriman"],["بِٱللَّهِ","kepada Allah"],["وَرَسُولِهِۦ ۚ","dan Rasul-Nya"],["فَإِذَا","Maka apabila"],["ٱسْتَـْٔذَنُوكَ","mereka meminta izin kamu"],["لِبَعْضِ","bagi sesetengah orang"],["شَأْنِهِمْ","urusan mereka"],["فَأْذَن","kemudian beri izin"],["لِّمَن","kepada siapa"],["شِئْتَ","kamu akan"],["مِنْهُمْ","antara mereka"],["وَٱسْتَغْفِرْ","dan memohon ampun"],["لَهُمُ","bagi mereka"],["ٱللَّهَ ۚ","(milik) Allah"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["غَفُورٌۭ","Maha Pengampun"],["رَّحِيمٌۭ","Maha Mengasihani"]]],"2854":["(Janganlah kalian jadikan panggilan Rasul di antara kalian seperti panggilan sebagian kalian kepada sebagian yang lain) umpamanya kalian mengatakan, \"Hai Muhammad!\" Tetapi ucapkanlah, \"Hai Nabi Allah, hai Rasulullah!\" Dengan suara yang lemah lembut dan penuh rendah diri. (Sesungguhnya Allah telah mengetahui orang-orang yang diam-diam pergi di antara kalian dengan sembunyi-sembunyi) mereka keluar dari mesjid pada waktu Nabi mengucapkan khutbahnya tanpa terlebih dahulu meminta izin kepadanya, secara diam-diam sambil menyembunyikan diri di balik sesuatu. Huruf Qad di sini menunjukkan makna Tahqiq yang artinya sesungguhnya (maka hendaklah orang-orang yang menyalahi perintah-Nya merasa takut) menyalahi perintah Allah dan Rasul-Nya (akan ditimpa cobaan) malapetaka (atau ditimpa azab yang pedih) di akhirat kelak.",[["لَّا","Jangan"],["تَجْعَلُوا۟","buat"],["دُعَآءَ","(yang) memanggil"],["ٱلرَّسُولِ","(dari) Rasul"],["بَيْنَكُمْ","antara kamu"],["كَدُعَآءِ","sebagai (seruan)."],["بَعْضِكُم","(dari) sebahagian kamu"],["بَعْضًۭا ۚ","(kepada) orang lain"],["قَدْ","Sesungguhnya"],["يَعْلَمُ","Allah tahu"],["ٱللَّهُ","Allah tahu"],["ٱلَّذِينَ","orang yang"],["يَتَسَلَّلُونَ","terlepas"],["مِنكُمْ","antara kamu"],["لِوَاذًۭا ۚ","di bawah perlindungan"],["فَلْيَحْذَرِ","Jadi berhati-hatilah"],["ٱلَّذِينَ","orang yang"],["يُخَالِفُونَ","menentang"],["عَنْ","[dari]"],["أَمْرِهِۦٓ","perintahnya"],["أَن","jangan-jangan"],["تُصِيبَهُمْ","menimpa mereka"],["فِتْنَةٌ","perbicaraan"],["أَوْ","atau"],["يُصِيبَهُمْ","menimpa mereka"],["عَذَابٌ","azab"],["أَلِيمٌ","yang pedih"]]],"2855":["(Ketahuilah, sesungguhnya kepunyaan Allahlah apa yang di langit dan di bumi) sebagai milik, makhluk dan hamba-Nya. (Sesungguhnya Dia mengetahui keadaan yang kalian) hai orang-orang Mukallaf (berada di dalamnya) apakah kalian beriman atau munafik. (Dan) Dia mengetahui pula (hari manusia dikembalikan kepada-Nya) di dalam ungkapan ini terdapat iltifat dari mukhatab ke ghaib. Maksudnya, bila hal itu akan terjadi (lalu diterangkan-Nya kepada mereka) pada hari itu (apa yang telah mereka kerjakan) yaitu perbuatan baik dan perbuatan buruk yang telah mereka perbuat (Dan Allah terhadap segala sesuatu) terhadap semua perbuatan kalian dan selainnya (Maha Mengetahui.)",[["أَلَآ","Tidak syak lagi"],["إِنَّ","Sesungguhnya"],["لِلَّهِ","kepada Allah (milik)"],["مَا","apa sahaja"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۖ","dan bumi"],["قَدْ","Sesungguhnya"],["يَعْلَمُ","Dia tahu"],["مَآ","apa"],["أَنتُمْ","kamu"],["عَلَيْهِ","(ada) pada [itu]"],["وَيَوْمَ","Dan (hari) itu"],["يُرْجَعُونَ","mereka akan dikembalikan"],["إِلَيْهِ","kepada-Nya"],["فَيُنَبِّئُهُم","kemudian Dia akan memberitahu mereka"],["بِمَا","tentang apa"],["عَمِلُوا۟ ۗ","mereka lakukan"],["وَٱللَّهُ","Dan Allah"],["بِكُلِّ","daripada setiap"],["شَىْءٍ","perkara"],["عَلِيمٌۢ","Maha Mengetahui"]]],"2856":["(Maha Suci) Allah swt. (yang telah menurunkan Alfurqan) yakni Alquran, ia dinamakan Alfurqan karena kandungannya membedakan antara perkara yang hak dan perkara yang batil (kepada hamba-Nya) yakni Nabi Muhammad (agar dia menyampaikannya kepada seluruh alam) yaitu kepada bangsa manusia dan bangsa jin, selain bangsa malaikat (sebagai pemberi peringatan) kepada mereka, dengan memperingatkan mereka akan azab Allah.",[["تَبَارَكَ","Diberkati Dia"],["ٱلَّذِى","Siapa"],["نَزَّلَ","diturunkan"],["ٱلْفُرْقَانَ","Kriteria"],["عَلَىٰ","ke atas"],["عَبْدِهِۦ","hambanya"],["لِيَكُونَ","bahawa dia mungkin"],["لِلْعَـٰلَمِينَ","kepada dunia"],["نَذِيرًا","seorang pemberi amaran"]]],"2857":["(Yang kepunyaan-Nyalah kerajaan langit dan bumi, dan Dia tidak mempunyai anak, dan tidak ada sekutu bagi-Nya dalam kekuasaan-Nya, dan Dia telah menciptakan segala sesuatu) karena hanya Dialah yang mampu menciptakan kesemuanya itu (dan Dia menetapkan ukuran-ukurannya dengan serapi-rapinya) secara tepat dan sempurna.",[["ٱلَّذِى","Dia yang"],["لَهُۥ","kepada-Nya (milik)"],["مُلْكُ","(kekuasaan)."],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["وَلَمْ","dan bukan"],["يَتَّخِذْ","Dia telah mengambil"],["وَلَدًۭا","seorang anak lelaki"],["وَلَمْ","dan bukan"],["يَكُن","Dia ada"],["لَّهُۥ","untuk Dia"],["شَرِيكٌۭ","pasangan"],["فِى","dalam"],["ٱلْمُلْكِ","kekuasaan itu"],["وَخَلَقَ","dan Dia (telah) menciptakan"],["كُلَّ","setiap"],["شَىْءٍۢ","perkara"],["فَقَدَّرَهُۥ","dan menentukannya"],["تَقْدِيرًۭا","(dengan) keazaman"]]],"2858":["(Kemudian mereka mengambil) yang dimaksud adalah orang-orang kafir (selain daripada-Nya) selain Allah swt. (sebagai tuhan-tuhan) berupa berhala-berhala (yang mereka tidak menciptakan apa pun, bahkan mereka sendiri diciptakan dan tidak kuasa untuk menolak sesuatu kemudaratan dari dirinya) tidak akan mampu menolak bahaya yang mengancam dirinya (dan tidak pula untuk mengambil suatu manfaat pun) artinya tidak dapat menghasilkan manfaat bagi dirinya (dan juga tidak kuasa mematikan, menghidupkan) yakni tidak mampu mematikan seseorang dan tidak pula mampu menghidupkannya (dan tidak pula membangkitkan) tidak mampu membangkitkan orang-orang yang mati untuk dapat hidup kembali.",[["وَٱتَّخَذُوا۟","Namun mereka telah mengambil"],["مِن","selain Dia"],["دُونِهِۦٓ","selain Dia"],["ءَالِهَةًۭ","tuhan"],["لَّا","tidak"],["يَخْلُقُونَ","mereka cipta"],["شَيْـًۭٔا","sesuatu"],["وَهُمْ","sedangkan mereka"],["يُخْلَقُونَ","dicipta"],["وَلَا","dan bukan"],["يَمْلِكُونَ","mereka miliki"],["لِأَنفُسِهِمْ","untuk diri mereka sendiri"],["ضَرًّۭا","sebarang kemudaratan"],["وَلَا","dan bukan"],["نَفْعًۭا","sebarang faedah"],["وَلَا","dan bukan"],["يَمْلِكُونَ","mereka mengawal"],["مَوْتًۭا","kematian"],["وَلَا","dan bukan"],["حَيَوٰةًۭ","kehidupan"],["وَلَا","dan bukan"],["نُشُورًۭا","kebangkitan"]]],"2859":["(Dan orang-orang kafir berkata, \"Sesungguhnya ini) Alquran ini (tidak lain hanyalah kebohongan-kebohongan) yakni kedustaan (yang diada-adakan olehnya) oleh Muhammad sendiri (dan dia dibantu oleh kaum yang lain) yakni oleh sebagian dari orang-orang ahli kitab. Allah berfirman: (Maka sesungguhnya mereka telah berbuat suatu kelaliman dan dusta yang besar\") yakni kekafiran dan kedustaan.",[["وَقَالَ","Dan katakan"],["ٱلَّذِينَ","orang yang"],["كَفَرُوٓا۟","kufur"],["إِنْ","Tidak"],["هَـٰذَآ","ini"],["إِلَّآ","(adalah) tetapi"],["إِفْكٌ","satu pembohongan"],["ٱفْتَرَىٰهُ","dia menciptanya"],["وَأَعَانَهُۥ","dan menolongnya"],["عَلَيْهِ","padanya"],["قَوْمٌ","orang ramai"],["ءَاخَرُونَ ۖ","lain"],["فَقَدْ","Tetapi sesungguhnya"],["جَآءُو","mereka (telah) menghasilkan"],["ظُلْمًۭا","suatu ketidakadilan"],["وَزُورًۭا","dan pembohongan"]]],"2860":["(Dan mereka berkata,) pula bahwa Alquran itu (\"Dongengan-dongengan orang-orang dahulu) yakni kedustaan-kedustaan mereka. Lafal Asaathiir adalah bentuk jamak dari lafal Usthuurah (dimintanya supaya dituliskan) telah menukilnya dari kaum tersebut melalui orang lain (maka dibacakanlah dongengan itu kepadanya) supaya ia hafal (setiap pagi dan petang.\") Kemudian Allah berfirman menyanggah ucapan mereka:",[["وَقَالُوٓا۟","Dan mereka berkata"],["أَسَـٰطِيرُ","Tales"],["ٱلْأَوَّلِينَ","(dari) orang-orang dahulu"],["ٱكْتَتَبَهَا","yang telah ditulisnya"],["فَهِىَ","dan mereka"],["تُمْلَىٰ","adalah didikte"],["عَلَيْهِ","kepadanya"],["بُكْرَةًۭ","pagi"],["وَأَصِيلًۭا","dan petang"]]],"2861":["(Katakanlah! \"Alquran ini diturunkan oleh Allah yang mengetahui rahasia) hal-hal yang gaib (di langit dan di bumi. Sesungguhnya Dia adalah Maha Pengampun) kepada orang-orang yang beriman (lagi Maha Penyayang\") kepada mereka.",[["قُلْ","Katakanlah"],["أَنزَلَهُ","Telah menurunkannya"],["ٱلَّذِى","yang Esa"],["يَعْلَمُ","mengetahui"],["ٱلسِّرَّ","rahsia"],["فِى","dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۚ","dan bumi"],["إِنَّهُۥ","Sesungguhnya Dia"],["كَانَ","ialah"],["غَفُورًۭا","Selalu Memaafkan"],["رَّحِيمًۭا","Maha Mengasihani"]]],"2862":["(Dan mereka berkata, \"Mengapa Rasul ini memakan makanan dan berjalan di pasar-pasar? Mengapa tidak) (diturunkan kepadanya Malaikat, agar Malaikat itu memberikan peringatan bersama dengan dia?) maksudnya yang membenarkan kerasulannya.",[["وَقَالُوا۟","Dan mereka berkata"],["مَالِ","Mengapa begitu"],["هَـٰذَا","ini"],["ٱلرَّسُولِ","Utusan"],["يَأْكُلُ","makan"],["ٱلطَّعَامَ","[the] makanan"],["وَيَمْشِى","dan berjalan"],["فِى","dalam"],["ٱلْأَسْوَاقِ ۙ","pasaran-pasaran"],["لَوْلَآ","kenapa tidak"],["أُنزِلَ","diturunkan"],["إِلَيْهِ","kepadanya"],["مَلَكٌۭ","seorang Malaikat"],["فَيَكُونَ","maka jadilah dia"],["مَعَهُۥ","dengan dia"],["نَذِيرًا","seorang pemberi amaran"]]],"2863":["(Atau mengapa tidak diturunkan kepadanya perbendaharaan) dari langit yang kemudian ia membelanjakannya, sehingga ia tidak usah berjalan-jalan di pasar lagi untuk mencari penghidupan (atau mengapa tidak ada kebun baginya) yaitu ladang yang menjadi miliknya (yang dapat dia makan dari hasilnya\") buah-buahannya, sehingga hal itu menjadi kecukupan baginya. Menurut qiraat yang lain dibaca Na'kulu Minhaa, artinya; yang kami dapat ikut makan dari kebunnya. Maksudnya, supaya memiliki kelebihan di atas kami. (Dan orang-orang yang zalim itu berkata:) orang-orang kafir itu kepada orang-orang Mukmin, (\"Tidak lain kamu sekalian hanyalah mengikuti seorang lelaki yang kena sihir\") orang yang akalnya tidak waras karena pengaruh sihir. Maka Allah berfirman pada ayat selanjutnya:",[["أَوْ","Atau"],["يُلْقَىٰٓ","dihantar"],["إِلَيْهِ","kepadanya"],["كَنزٌ","harta karun"],["أَوْ","atau"],["تَكُونُ","ialah"],["لَهُۥ","baginya"],["جَنَّةٌۭ","sebuah taman"],["يَأْكُلُ","dia boleh makan"],["مِنْهَا ۚ","daripadanya"],["وَقَالَ","Dan katakan"],["ٱلظَّـٰلِمُونَ","orang yang zalim"],["إِن","Tidak"],["تَتَّبِعُونَ","kamu ikut"],["إِلَّا","tetapi"],["رَجُلًۭا","seorang lelaki"],["مَّسْحُورًا","disihir"]]],"2864":["(Perhatikanlah, bagaimana mereka membuat perumpamaan-perumpamaan tentang kamu) dengan julukan sebagai orang yang kena pengaruh sihir, orang yang membutuhkan nafkah, orang yang harus ditemani oleh Malaikat yang bersama-sama menyampaikan tugasnya (lalu sesatlah mereka) dari petunjuk disebabkan ucapannya itu (mereka tidak sanggup mendapatkan jalan untuk menentang kerasulannya) maksudnya mereka tidak akan dapat menemukan jalan untuk menentangnya.",[["ٱنظُرْ","Lihat"],["كَيْفَ","bagaimana"],["ضَرَبُوا۟","mereka menetapkan"],["لَكَ","bagi kamu"],["ٱلْأَمْثَـٰلَ","persamaan itu"],["فَضَلُّوا۟","tetapi mereka telah sesat"],["فَلَا","jadi tidak"],["يَسْتَطِيعُونَ","mereka dapat (mencari)"],["سَبِيلًۭا","satu cara"]]],"2865":["(Maha Agung Allah) Maha Kaya akan kebaikan (yang jika Dia menghendaki, niscaya dijadikan-Nya bagimu yang lebih baik dari yang demikian) yakni lebih baik daripada perbendaharaan harta dan kebun yang mereka mintakan di dunia ini (yaitu surga-surga yang di bawahnya mengalir sungai-sungai) karena Dia telah menjanjikan akan memberikan kepadanya nanti di akhirat (dan dijadikan-Nya pula) lafal ayat ini dibaca Jazm (untukmu istana-istana) dan menurut qiraat yang lain, lafal Yaj'al dibaca Yaj'alu sehingga kedudukannya menjadi kalimat Isti'naf, atau kalimat baru.",[["تَبَارَكَ","Diberkati Dia"],["ٱلَّذِىٓ","Siapa"],["إِن","jika"],["شَآءَ","Dia berkehendak"],["جَعَلَ","(boleh) dibuat"],["لَكَ","bagi kamu"],["خَيْرًۭا","lebih baik"],["مِّن","daripada"],["ذَٰلِكَ","itu"],["جَنَّـٰتٍۢ","taman-taman"],["تَجْرِى","aliran"],["مِن","daripada"],["تَحْتِهَا","di bawahnya"],["ٱلْأَنْهَـٰرُ","sungai-sungai"],["وَيَجْعَل","dan Dia (boleh) menjadikan"],["لَّكَ","bagi kamu"],["قُصُورًۢا","istana"]]],"2866":["(Bahkan mereka mendustakan hari kiamat) hari terakhir yang tiada hari lagi sesudahnya. (Dan Kami menyediakan neraka yang menyala-nyala bagi siapa yang mendustakan hari kiamat) neraka yang apinya menyala-nyala dengan nyala yang besar.",[["بَلْ","Bahkan"],["كَذَّبُوا۟","mereka menafikan"],["بِٱلسَّاعَةِ ۖ","Jam itu"],["وَأَعْتَدْنَا","dan telah Kami sediakan"],["لِمَن","untuk (mereka) yang"],["كَذَّبَ","menafikan"],["بِٱلسَّاعَةِ","Jam itu"],["سَعِيرًا","api yang menyala-nyala"]]],"2867":["(Apabila neraka itu melihat mereka dari tempat yang jauh, mereka mendengar kegeramannya) yakni suara mendidihnya seperti halnya orang yang sedang marah (dan suara nyalanya) suara yang keras sekali dari nyala apinya. Atau makna yang dimaksud adalah jika orang-orang tersebut melihat neraka sekalipun dari tempat yang jauh, mereka akan mendengar suara gemuruh dan nyala apinya.",[["إِذَا","Apabila"],["رَأَتْهُم","ia melihat mereka"],["مِّن","daripada"],["مَّكَانٍۭ","sebuah tempat"],["بَعِيدٍۢ","jauh"],["سَمِعُوا۟","mereka akan mendengar"],["لَهَا","itu"],["تَغَيُّظًۭا","mengamuk"],["وَزَفِيرًۭا","dan mengaum"]]],"2868":["(Dan apabila mereka dicampakkan ke tempat yang sempit di neraka itu) dapat dibaca Dhayyiqan dengan memakai harakat Tasydid pada huruf Ya, dapat pula dibaca Takhfif atau tanpa Tasydid sehingga bacaannya menjadi Dhayqan, maksudnya neraka itu menghimpit mereka. Lafal Minhaa berkedudukan menjadi Hal dari lafal Makaanan, karena pada asalnya ia adalah kata sifat baginya (dengan dibelenggu) yakni tangan dan leher mereka dibelenggu menjadi satu; harakat Tasydid yang ada pada lafal Muqarraniina menunjukkan makna Taktsir atau banyak (mereka di sana mengharapkan kebinasaan) maksudnya mereka ingin mati saja karena pedihnya siksaan. Dikatakan oleh Allah swt. kepada mereka,",[["وَإِذَآ","Dan apabila"],["أُلْقُوا۟","mereka dilemparkan"],["مِنْهَا","daripadanya"],["مَكَانًۭا","(di) suatu tempat"],["ضَيِّقًۭا","sempit"],["مُّقَرَّنِينَ","terikat dalam rantai"],["دَعَوْا۟","mereka akan memanggil"],["هُنَالِكَ","di sana"],["ثُبُورًۭا","(untuk) kemusnahan"]]],"2869":["(\"Janganlah kamu sekalian mengharapkan satu kebinasaan, melainkan harapkanlah kebinasaan yang banyak\") sesuai dengan azab yang menimpa kalian ini.",[["لَّا","Jangan"],["تَدْعُوا۟","panggilan"],["ٱلْيَوْمَ","hari ini"],["ثُبُورًۭا","(untuk) kemusnahan"],["وَٰحِدًۭا","satu"],["وَٱدْعُوا۟","tapi call"],["ثُبُورًۭا","(untuk) kemusnahan"],["كَثِيرًۭا","ramai"]]],"2870":["(Katakanlah! \"Apa yang demikian itukah) hal yang telah disebutkan itukah, yaitu ancaman dan gambaran tentang neraka (yang baik, atau surga yang kekal yang telah dijanjikan) (kepada orang-orang yang bertakwa?\" Surga itu untuk mereka) menurut ilmu Allah (sebagai balasan) sebagai pahala (dan tempat kembali) tempat menetap yang abadi.",[["قُلْ","Katakanlah"],["أَذَٰلِكَ","Adakah itu"],["خَيْرٌ","lebih baik"],["أَمْ","atau"],["جَنَّةُ","Taman"],["ٱلْخُلْدِ","(dari) Keabadian"],["ٱلَّتِى","yang"],["وُعِدَ","dijanjikan"],["ٱلْمُتَّقُونَ ۚ","(kepada) orang-orang yang soleh"],["كَانَتْ","Ia akan menjadi"],["لَهُمْ","bagi mereka"],["جَزَآءًۭ","ganjaran"],["وَمَصِيرًۭا","dan destinasi"]]],"2871":["(Bagi mereka di dalam surga itu apa yang mereka kehendaki, sedangkan mereka kekal) lafal Khaalidiina menjadi Hal yang bersifat Lazimah atau harus (adalah) janji mereka seperti yang telah disebutkan tadi (janji dari Rabbmu yang patut dimohonkan kepada-Nya) artinya orang yang telah dijanjikan kepadanya hal itu patut untuk memohon kepada-Nya, sebagaimana yang diungkapkan oleh firman-Nya yang lain, yaitu, \"Ya Rabb kami! Berilah kami apa yang telah Engkau janjikan kepada kami dengan perantaraan rasul-rasul Engkau.\" (Q.S. Ali Imran, 194) atau hal itu dimintakan oleh para Malaikat buat mereka, sebagaimana yang diungkapkan oleh firman-Nya yang lain, yaitu, \"Ya Rabb kami! Masukkanlah mereka ke dalam surga Adn yang telah Engkau janjikan-kepada mereka.\" (Q.S. Al Mukmin, 8).",[["لَّهُمْ","Untuk mereka"],["فِيهَا","di dalamnya"],["مَا","(adalah) apa sahaja"],["يَشَآءُونَ","mereka mahu"],["خَـٰلِدِينَ ۚ","mereka akan kekal selama-lamanya"],["كَانَ","Ia adalah"],["عَلَىٰ","pada"],["رَبِّكَ","Tuhanmu"],["وَعْدًۭا","sebuah janji"],["مَّسْـُٔولًۭا","diminta"]]],"2872":["(Dan pada suatu hari ketika Allah menghimpunkan mereka) lafal Yahsyuruhum dapat pula dibaca Nahsyuruhum, sehingga artinya menjadi, Kami menghimpun mereka (beserta apa yang mereka sembah selain Allah) yakni seperti malaikat; Nabi Isa, dan Nabi Uzair, serta jin (lalu Allah berkata:) kepada mereka yang disembah untuk memantapkan hujah-Nya terhadap orang-orang yang menyembah mereka. Lafal Fayaquulu dapat pula dibaca Fanaquulu, artinya, Kami berkata, (\"Apakah kalian) lafal A-antum dapat dibaca secara Tahqiq yaitu dengan menyatakan kedua Hamzahnya, dan dapat pula dibaca Tas-hil yaitu dengan menggantikan Hamzah yang kedua menjadi Alif sehingga bacaan Hamzahnya menjadi panjang, dapat pula dibaca pendek yakni tanpa memakai Alif (yang menyesatkan hamba-hamba-Ku itu) artinya apakah kalian telah menjerumuskan mereka ke dalam kesesatan dengan perintah kalian kepada mereka, supaya mereka menyembah kalian? (atau mereka sendirilah yang sesat dari jalan yang benar?\") yakni atas kehendak mereka sendiri.",[["وَيَوْمَ","Dan (hari) itu"],["يَحْشُرُهُمْ","Dia akan mengumpulkan mereka"],["وَمَا","dan apa"],["يَعْبُدُونَ","mereka menyembah"],["مِن","selain Allah"],["دُونِ","selain Allah"],["ٱللَّهِ","selain Allah"],["فَيَقُولُ","dan Dia akan berkata"],["ءَأَنتُمْ","Adakah kamu"],["أَضْلَلْتُمْ","[kamu] menyesatkan"],["عِبَادِى","budak-budak aku"],["هَـٰٓؤُلَآءِ","ini"],["أَمْ","atau"],["هُمْ","mereka"],["ضَلُّوا۟","sesat"],["ٱلسَّبِيلَ","(dari) jalan"]]],"2873":["(Mereka yang disembah itu menjawab, \"Maha Suci Engkau,) dari apa yang tidak layak bagi Engkau (tidaklah patut) tidaklah dibenarkan (bagi kami mengambil selain Engkau) (untuk jadi pelindung) lafal Min Auliyaa berkedudukan menjadi Maf'ul pertama, sedangkan huruf Min adalah Zaidah yang berfungsi mengukuhkan makna Nafi. Lafal sebelumnya berkedudukan menjadi Maf'ul kedua. Maksudnya, mana mungkin kami memerintahkan mereka untuk menyembah kami (akan tetapi Engkau telah memberi mereka dan bapak-bapak mereka kenikmatan hidup) sebelumnya yaitu di dunia, dengan umur yang panjang dan rezeki yang luas. (Sampai mereka lupa akan peringatan) yakni nasihat dan iman kepada Alquran (dan mereka adalah kaum yang binasa.\") Allah berfirman:",[["قَالُوا۟","Mereka berkata"],["سُبْحَـٰنَكَ","Maha Suci Engkau"],["مَا","Tidak"],["كَانَ","ia adalah wajar"],["يَنۢبَغِى","ia adalah wajar"],["لَنَآ","bagi kami"],["أَن","bahawa"],["نَّتَّخِذَ","kita ambil"],["مِن","selain Engkau"],["دُونِكَ","selain Engkau"],["مِنْ","sebarang"],["أَوْلِيَآءَ","pelindung"],["وَلَـٰكِن","Tetapi"],["مَّتَّعْتَهُمْ","Kamu memberi mereka keselesaan"],["وَءَابَآءَهُمْ","dan nenek moyang mereka"],["حَتَّىٰ","sehingga"],["نَسُوا۟","mereka lupa"],["ٱلذِّكْرَ","Mesej"],["وَكَانُوا۟","dan menjadi"],["قَوْمًۢا","suatu kaum"],["بُورًۭا","hancur"]]],"2874":["(\"Maka sesungguhnya mereka yang disembah itu telah mendustakan kalian) yang disembah itu berdusta kepada mereka yang menyembahnya (tentang apa yang kalian katakan) bahwasanya mereka adalah tuhan-tuhan (maka kalian tidak akan dapat) kalau dibaca yastathii'uuna artinya maka mereka tidak akan dapat; maksudnya baik mereka atau pun kalian (menolak) azab dari diri kalian (dan tidak pula menolong) mencegah azab yang menimpa diri kalian (dan barang siapa berbuat zalim) dengan memperbuat kemusyrikan (di antara kalian, niscaya Kami rasakan kepadanya azab yang besar) azab yang keras di akhirat.",[["فَقَدْ","Maka sesungguhnya"],["كَذَّبُوكُم","mereka menafikan kamu"],["بِمَا","pada apa"],["تَقُولُونَ","kamu cakap"],["فَمَا","jadi tidak"],["تَسْتَطِيعُونَ","kamu mampu"],["صَرْفًۭا","(untuk) mengelak"],["وَلَا","dan bukan"],["نَصْرًۭا ۚ","(untuk) menolong"],["وَمَن","Dan sesiapa"],["يَظْلِم","buat salah"],["مِّنكُمْ","antara kamu"],["نُذِقْهُ","Kita akan buat dia rasa"],["عَذَابًۭا","azab"],["كَبِيرًۭا","yang besar"]]],"2875":["(Dan Kami tidak mengutus rasul-rasul sebelum kamu, melainkan mereka sungguh memakan makanan dan berjalan di pasar-pasar) maka kamu adalah sama seperti mereka dalam hal ini. Maksudnya, telah dikatakan pula hal yang serupa terhadap mereka, sebagaimana apa yang dikatakan kepadamu sekarang ini. (Dan Kami jadikan sebagian kalian cobaan bagi sebagian yang lain) yakni orang yang kaya dicoba dengan adanya orang fakir dan orang yang sehat dicoba dengan adanya orang yang sakit, dan orang yang terhormat dicoba dengan adanya orang yang rendah. Maka golongan yang kedua dari orang-orang tadi mengatakan, 'Mengapa aku tidak seperti dia dalam segala hal?' (Maukah kalian bersabar?) di dalam menghadapi perkataan yang kalian dengar dari orang-orang yang kalian mendapat cobaan dari mereka. Istifham atau kata tanya di sini mengandung arti perintah, maksudnya bersabarlah kalian (dan adalah Rabbmu Maha Melihat\") terhadap orang-orang yang sabar dan yang tidak sabar.",[["وَمَآ","Dan tidak"],["أَرْسَلْنَا","Kami utus"],["قَبْلَكَ","sebelum kamu"],["مِنَ","sebarang"],["ٱلْمُرْسَلِينَ","Utusan"],["إِلَّآ","tetapi"],["إِنَّهُمْ","sesungguhnya, mereka"],["لَيَأْكُلُونَ","[pasti] makan"],["ٱلطَّعَامَ","makanan"],["وَيَمْشُونَ","dan berjalan"],["فِى","dalam"],["ٱلْأَسْوَاقِ ۗ","pasaran-pasaran"],["وَجَعَلْنَا","Dan Kami telah menjadikan"],["بَعْضَكُمْ","sebahagian daripada kamu"],["لِبَعْضٍۢ","untuk orang lain"],["فِتْنَةً","perbicaraan"],["أَتَصْبِرُونَ ۗ","adakah kamu akan bersabar"],["وَكَانَ","Dan adakah"],["رَبُّكَ","Tuhanmu"],["بَصِيرًۭا","Maha Melihat"]]]});